--
-- Name: a_films_verdict_moves(integer, integer, integer, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_films_verdict_moves(p_film integer, p_logs integer, p_rated integer, p_sum numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  t private.film_tallies%ROWTYPE;
BEGIN
  IF p_film IS NULL OR p_film <= 0 THEN
    RETURN;
  END IF;

  UPDATE private.film_tallies
     SET logs = logs + p_logs, rated = rated + p_rated, rating_sum = rating_sum + p_sum
   WHERE film_id = p_film
  RETURNING * INTO t;

  IF NOT FOUND THEN
    -- The film's first move: its records counted once (a withheld one is in no film's verdict, H-B10).
    INSERT INTO private.film_tallies AS k (film_id, logs, rated, rating_sum)
    SELECT p_film, count(*), count(*) FILTER (WHERE l.rating > 0), COALESCE(sum(l.rating) FILTER (WHERE l.rating > 0), 0)
      FROM public.logs l
     WHERE l.film_id = p_film
       AND l.withheld_at IS NULL
    ON CONFLICT (film_id) DO UPDATE
      SET logs = k.logs + p_logs, rated = k.rated + p_rated, rating_sum = k.rating_sum + p_sum
    RETURNING * INTO t;
  END IF;

  INSERT INTO public.films AS f (id, avg_rating, rating_count, log_count)
  VALUES (p_film, CASE WHEN t.rated > 0 THEN ROUND(t.rating_sum / t.rated, 2) END, t.rated, t.logs)
  ON CONFLICT (id) DO UPDATE
    SET avg_rating   = EXCLUDED.avg_rating,
        rating_count = EXCLUDED.rating_count,
        log_count    = EXCLUDED.log_count;
END $$;


--
-- Name: a_judge_is_refused(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_judge_is_refused(p_judge uuid, p_ruler uuid, p_target uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Why this judge may not judge this case, or nothing when they may: the member it is about is refused
  -- (OWN_CASE), as the one who ruled is (OWN_VERDICT). A lift has no ruler to ask (p_ruler NULL).
  SELECT CASE
    WHEN p_judge IS NOT DISTINCT FROM p_target THEN 'OWN_CASE'
    WHEN p_ruler IS NOT NULL AND p_judge IS NOT DISTINCT FROM p_ruler THEN 'OWN_VERDICT'
  END
$$;


--
-- Name: a_members_pieces_are_queued(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_members_pieces_are_queued() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.username IS NOT DISTINCT FROM NEW.username
     AND OLD.display_name IS NOT DISTINCT FROM NEW.display_name THEN
    RETURN NULL;
  END IF;
  IF TG_OP <> 'INSERT' THEN
    INSERT INTO private.member_grams_waiting (gram, username, id, sign)
    SELECT g, OLD.username, OLD.id, -1 FROM unnest(private.member_grams_of(OLD.username, OLD.display_name)) g;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    INSERT INTO private.member_grams_waiting (gram, username, id, sign)
    SELECT g, NEW.username, NEW.id, 1 FROM unnest(private.member_grams_of(NEW.username, NEW.display_name)) g;
  END IF;
  -- Counted, so the settling knows at once whether anything waits (the transaction's own setting).
  PERFORM set_config('reelhouse.member_grams_queued',
                     (COALESCE(NULLIF(current_setting('reelhouse.member_grams_queued', true), ''), '0')::bigint + 1)::text, true);
  RETURN NULL;
END $$;


--
-- Name: a_members_room_is_spent(uuid, text, real, real); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_members_room_is_spent(p_member uuid, p_kind text, p_room real, p_every real) RETURNS TABLE(tokens real, n integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  INSERT INTO public.write_budget AS b (user_id, kind, tokens, refilled_at, day, n)
  VALUES (p_member, p_kind, p_room - 1, now(), (now() AT TIME ZONE 'UTC')::date, 1)
  ON CONFLICT (user_id, kind) DO UPDATE SET
    tokens      = LEAST(p_room, b.tokens + GREATEST(0, extract(epoch FROM now() - b.refilled_at))::real / p_every) - 1,
    refilled_at = GREATEST(b.refilled_at, now()),
    day         = (now() AT TIME ZONE 'UTC')::date,
    n           = (CASE WHEN b.day = (now() AT TIME ZONE 'UTC')::date THEN b.n ELSE 0 END) + 1
  RETURNING b.tokens, b.n;
$$;


--
-- Name: a_picture_is_held(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_picture_is_held(p_bucket text, p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  -- A page's picture is kept in the bucket under its member's folder; asked by that member's key of the
  -- reports still pending about their page (their words as reported) and of the verdicts that cleared it
  -- (what puts it back), each by its own index.
  SELECT p_bucket = 'avatars' AND split_part(p_name, '/', 1) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND (
    EXISTS (SELECT 1 FROM public.reports r JOIN public.reported_words w ON w.report_id = r.id
             WHERE r.status = 'pending' AND r.content_type = 'profile' AND r.content_id = split_part(p_name, '/', 1)
               AND position(('/avatars/' || p_name) IN coalesce(w.words ->> 'avatar_url', '')) > 0)
    OR EXISTS (SELECT 1 FROM public.mod_actions m
                WHERE m.target_user_id = split_part(p_name, '/', 1)::uuid AND m.action = 'delete_content'
                  AND coalesce(m.appeal_status, 'pending') = 'pending'
                  AND position(('/avatars/' || p_name) IN coalesce(m.content_snapshot -> 'kept' ->> 'avatar_url', '')) > 0))
$_$;


