--
-- Name: lounge_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lounge_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lounge_id uuid NOT NULL,
    user_id uuid,
    content text DEFAULT ''::text,
    type text DEFAULT 'text'::text,
    metadata jsonb DEFAULT '{}'::jsonb,
    reply_to_id uuid,
    reply_to_content text,
    reply_to_username text,
    created_at timestamp with time zone DEFAULT now(),
    deleted_at timestamp with time zone,
    film_id integer,
    film_title text,
    film_poster text,
    carries_words_of uuid[],
    CONSTRAINT lounge_messages_content_len CHECK ((char_length(content) <= 2000)),
    CONSTRAINT lounge_messages_film_poster_len CHECK ((char_length(film_poster) <= 2048)),
    CONSTRAINT lounge_messages_film_title_len CHECK ((char_length(film_title) <= 300)),
    CONSTRAINT lounge_messages_metadata_len CHECK ((char_length((metadata)::text) <= 8000)),
    CONSTRAINT lounge_messages_reply_to_content_len CHECK ((char_length(reply_to_content) <= 2000)),
    CONSTRAINT lounge_messages_reply_to_username_len CHECK ((char_length(reply_to_username) <= 100)),
    CONSTRAINT lounge_messages_type_len CHECK ((char_length(type) <= 100))
);


--
-- Name: COLUMN lounge_messages.carries_words_of; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lounge_messages.carries_words_of IS 'The members whose words this message carries besides its writer''s: the author of the message it answers (its quote), the author of the piece its card shows, the author of a card it answers. Written by the house alone (a_reply_quotes_its_message on insert; a_keeps_what_it_is keeps it from its writer). NULL: none. lounge_messages_hide_blocked hides a message carrying the words of one hidden from the reader, unless it is the reader''s own.';


--
-- Name: a_shared_card(public.lounge_messages, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_shared_card(p_msg public.lounge_messages, p_refuse_gone boolean) RETURNS public.lounge_messages
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  -- What only the house may write on a card: a byline, a count, a kind, its pictures, its marks, and the
  -- words the website's reader draws beside a title.
  v_houses  text[] := ARRAY['author_username', 'owner_username', 'curator', 'filmCount', 'topPosters', 'kind',
                            'gone', 'sealed', 'caption', 'subtitle', 'reviewer', 'author', 'excerpt', 'review',
                            'rating', 'poster_path', 'backdrop_path', 'profile_path'];
  v_meta    jsonb := coalesce(p_msg.metadata, '{}'::jsonb);
  v_named   text;
  v_film    text;
  v_log     record;
  v_post    record;
  v_list    record;
  v_known   record;
BEGIN
  IF p_msg.type = 'log_share' THEN
    v_named := coalesce(v_meta ->> 'log_id', v_meta ->> 'logId');
    IF v_named IS NULL THEN
      -- A card that names no record keeps none of a card's words: it shows nothing.
      p_msg.metadata := '{}'::jsonb; p_msg.film_id := NULL; p_msg.film_title := NULL; p_msg.film_poster := NULL;
      RETURN p_msg;
    END IF;
    -- Read as the caller: a sharer may put on a card only a record they may read.
    SELECT l.id, l.user_id, l.film_id, l.film_title, l.poster_path, l.alt_poster INTO v_log
      FROM public.logs l
     WHERE v_named ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND l.id = v_named::uuid;
    IF NOT FOUND THEN
      IF p_refuse_gone THEN
        RAISE EXCEPTION 'LOG_GONE' USING ERRCODE = 'P0002';
      END IF;
      p_msg.metadata := jsonb_build_object('log_id', v_named, 'gone', true);
      p_msg.film_title := NULL; p_msg.film_poster := NULL;
      RETURN p_msg;
    END IF;
    p_msg.film_id := v_log.film_id;
    p_msg.film_title := private.a_card_cut(v_log.film_title);
    -- The record's poster: the one its owner chose for it, or the film's.
    p_msg.film_poster := CASE WHEN p_msg.film_poster IN (v_log.poster_path, v_log.alt_poster) THEN p_msg.film_poster
                              ELSE v_log.poster_path END;
    p_msg.metadata := jsonb_strip_nulls(jsonb_build_object(
      'log_id', v_log.id::text,
      'logId', CASE WHEN v_meta ? 'logId' THEN v_log.id::text END,
      'title', p_msg.film_title,
      'poster_path', p_msg.film_poster,
      'owner_username', (SELECT p.username FROM public.profiles p WHERE p.id = v_log.user_id)));
    RETURN p_msg;
  END IF;

  IF p_msg.type = 'dossier_share' THEN
    v_named := coalesce(v_meta ->> 'dossier_id', v_meta ->> 'dossierId');
    IF v_named IS NULL THEN
      p_msg.metadata := '{}'::jsonb; p_msg.film_id := NULL; p_msg.film_title := NULL; p_msg.film_poster := NULL;
      RETURN p_msg;
    END IF;
    -- Read as the caller: a draft, a withheld filing or a hidden author's is not theirs to show.
    SELECT d.id, d.user_id, d.author_username, d.kind, d.title, d.body, d.spoiler_label, d.subject_kind,
           d.subject_title, d.ended_at, d.is_published INTO v_post
      FROM public.dispatch_posts d
     WHERE v_named ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND d.id = v_named::uuid;
    IF NOT FOUND OR v_post.ended_at IS NOT NULL OR NOT v_post.is_published THEN
      IF p_refuse_gone THEN
        RAISE EXCEPTION 'PIECE_GONE' USING ERRCODE = 'P0002';
      END IF;
      -- As round 11 takes a filing's card down when the filing goes.
      p_msg.film_title := NULL; p_msg.film_poster := NULL; p_msg.film_id := NULL;
      p_msg.metadata := jsonb_build_object('dossier_id', v_named, 'gone', true);
      RETURN p_msg;
    END IF;
    v_film := CASE WHEN v_post.subject_kind = 'film' THEN v_post.subject_title END;
    -- The filing's line by the share's rule, cut as the phone cuts it: never where its sharer chose.
    p_msg.film_title := private.a_filings_line(v_post.kind, v_post.title, v_post.body, v_post.spoiler_label, v_film);
    p_msg.film_id := NULL;
    p_msg.film_poster := NULL;
    p_msg.metadata := jsonb_strip_nulls(jsonb_build_object(
      'dossier_id', v_post.id::text,
      'dossierId', CASE WHEN v_meta ? 'dossierId' THEN v_post.id::text END,
      -- The website draws a card by its title: the same line, kept with the line on the phone.
      'title', p_msg.film_title,
      -- An account closed leaves its filings unsigned: no byline.
      'author_username', CASE WHEN v_post.user_id IS NOT NULL THEN v_post.author_username END,
      'kind', v_post.kind));
    RETURN p_msg;
  END IF;

  IF p_msg.type = 'list_share' THEN
    v_named := v_meta ->> 'listId';
    IF v_named IS NULL THEN
      p_msg.metadata := '{}'::jsonb; p_msg.film_id := NULL; p_msg.film_title := NULL; p_msg.film_poster := NULL;
      RETURN p_msg;
    END IF;
    -- Read as the caller; a sealed stack was refused before this (a_sealed_stack_is_not_shared).
    SELECT l.id, l.title, l.user_id INTO v_list
      FROM public.lists l
     WHERE v_named ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND l.id = v_named::uuid;
    IF NOT FOUND THEN
      IF p_refuse_gone THEN
        RAISE EXCEPTION 'STACK_GONE' USING ERRCODE = 'P0002';
      END IF;
      p_msg.metadata := jsonb_build_object('listId', v_named, 'gone', true);
      p_msg.film_id := NULL; p_msg.film_title := NULL; p_msg.film_poster := NULL;
      RETURN p_msg;
    END IF;
    -- As a_sealed_stack_takes_its_cards makes a card when a stack is opened again.
    p_msg.film_id := NULL; p_msg.film_title := NULL; p_msg.film_poster := NULL;
    p_msg.metadata := jsonb_build_object(
      'listId', v_list.id::text,
      'title', v_list.title,
      'filmCount', (SELECT count(*) FROM public.list_items i WHERE i.list_id = v_list.id),
      'curator', (SELECT p.username FROM public.profiles p WHERE p.id = v_list.user_id),
      'topPosters', coalesce((SELECT jsonb_agg(x.poster_path ORDER BY x.place)
                                FROM (SELECT i.poster_path,
                                             row_number() OVER (ORDER BY i.rank_position NULLS LAST, i.created_at, i.id) AS place
                                        FROM public.list_items i
                                       WHERE i.list_id = v_list.id AND i.poster_path IS NOT NULL
                                       ORDER BY i.rank_position NULLS LAST, i.created_at, i.id
                                       LIMIT 4) x), '[]'::jsonb));
    RETURN p_msg;
  END IF;

  -- A film's or a person's card: no byline, count, kind, picture or mark of the house, whatever was sent.
  p_msg.metadata := v_meta - v_houses;
  IF p_msg.type = 'film_share' THEN
    SELECT f.title, f.poster_path, f.year INTO v_known
      FROM public.films f
     WHERE f.id = coalesce(p_msg.film_id,
                           CASE WHEN (v_meta ->> 'filmId') ~ '^[0-9]{1,9}$' THEN (v_meta ->> 'filmId')::integer END)
       AND nullif(btrim(coalesce(f.title, '')), '') IS NOT NULL;
    IF FOUND THEN
      -- The film as the house holds it: its title (cut as the phone cuts a card's), poster and year.
      IF p_msg.film_title IS NOT NULL THEN
        p_msg.film_title := private.a_card_cut(v_known.title);
      END IF;
      p_msg.film_poster := coalesce(v_known.poster_path, p_msg.film_poster);
      p_msg.metadata := p_msg.metadata || jsonb_strip_nulls(jsonb_build_object(
        'title', CASE WHEN p_msg.metadata ? 'title' THEN private.a_card_cut(v_known.title) END,
        'poster_path', v_known.poster_path,
        'subtitle', v_known.year::text));
    END IF;
  END IF;
  RETURN p_msg;
END $_$;


--
-- Name: a_vote_is_counted(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_vote_is_counted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP IN ('DELETE', 'UPDATE') THEN
    -- An option's last vote takes its row with it.
    DELETE FROM private.ballot_counts WHERE post_id = OLD.post_id AND option_index = OLD.option_index AND n <= 1;
    UPDATE private.ballot_counts SET n = n - 1
     WHERE post_id = OLD.post_id AND option_index = OLD.option_index;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    INSERT INTO private.ballot_counts AS c (post_id, option_index, n) VALUES (NEW.post_id, NEW.option_index, 1)
    ON CONFLICT (post_id, option_index) DO UPDATE SET n = c.n + 1;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: a_withheld_piece_holds_it(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_withheld_piece_holds_it(p_kind text, p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Whether a critique's piece is withheld from the reader (withheld, and not theirs): its critiques go
  -- with it, the critic's own too (a critique's own reading rule lets its writer read it anywhere).
  SELECT coalesce(CASE p_kind
           WHEN 'log'  THEN (SELECT l.withheld_at IS NOT NULL AND l.user_id IS DISTINCT FROM (SELECT auth.uid()) FROM public.logs l WHERE l.id = p_id)
           WHEN 'list' THEN (SELECT s.withheld_at IS NOT NULL AND s.user_id IS DISTINCT FROM (SELECT auth.uid()) FROM public.lists s WHERE s.id = p_id)
         END, false)
$$;


--
-- Name: a_withheld_piece_turns_its_cards(text, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.a_withheld_piece_turns_its_cards(p_kind text, p_id uuid, p_withheld boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_type    text := CASE p_kind WHEN 'log' THEN 'log_share' WHEN 'list' THEN 'list_share' WHEN 'dispatch_post' THEN 'dossier_share' END;
  v_key     text := CASE p_kind WHEN 'log' THEN 'log_id' WHEN 'list' THEN 'listId' WHEN 'dispatch_post' THEN 'dossier_id' END;
  v_alt     text := CASE p_kind WHEN 'log' THEN 'logId' WHEN 'dispatch_post' THEN 'dossierId' END;
  v_cards   uuid[];
  v_caption text;
  v_list    record;
BEGIN
  IF v_type IS NULL THEN
    RETURN;
  END IF;
  -- Run by the house's own functions, so a_keeps_what_it_is lets the write (the sharer's message is not
  -- the house's). Asked as containment, so the cards' own index (lounge_messages_card_names) finds them.
  IF p_withheld THEN
    WITH turned AS (
      UPDATE public.lounge_messages m
         SET metadata = jsonb_build_object(v_key, p_id::text, 'gone', true, 'withheld', true)
                        || CASE WHEN p_kind = 'list' AND (m.metadata @> '{"caption": true}'::jsonb OR (m.content <> '' AND (
                          (m.metadata ? 'title' AND (m.content = m.metadata ->> 'title'
                             OR left(m.content, char_length(m.metadata ->> 'title') + 3) = (m.metadata ->> 'title') || ' · '))
                          OR m.content ~ ' · [0-9]+ films · by @[^ ]+$')))
                                THEN '{"caption": true}'::jsonb ELSE '{}'::jsonb END,
             content = CASE WHEN p_kind = 'list' AND m.content <> '' AND (
                          (m.metadata ? 'title' AND (m.content = m.metadata ->> 'title'
                             OR left(m.content, char_length(m.metadata ->> 'title') + 3) = (m.metadata ->> 'title') || ' · '))
                          OR m.content ~ ' · [0-9]+ films · by @[^ ]+$') THEN '' ELSE m.content END,
             film_id = CASE WHEN p_kind = 'log' THEN m.film_id END,
             film_title = NULL,
             film_poster = NULL
       WHERE m.type = v_type
         AND m.metadata <> '{}'::jsonb
         AND (m.metadata @> jsonb_build_object(v_key, p_id::text)
              OR (v_alt IS NOT NULL AND m.metadata @> jsonb_build_object(v_alt, p_id::text)))
         AND NOT (m.metadata @> '{"gone": true}'::jsonb)
      RETURNING m.id, m.metadata
    )
    SELECT array_agg(id) INTO v_cards FROM turned WHERE metadata @> '{"caption": true}'::jsonb;
    -- The replies that quote a stack's caption taken: the quote goes with it.
    IF v_cards IS NOT NULL THEN
      UPDATE public.lounge_messages r SET reply_to_content = NULL
       WHERE r.reply_to_id = ANY (v_cards) AND r.reply_to_content IS NOT NULL;
    END IF;
    RETURN;
  END IF;

  IF p_kind = 'list' THEN
    SELECT l.title, l.user_id, coalesce(l.is_private, false) AS sealed INTO v_list FROM public.lists l WHERE l.id = p_id;
    IF NOT FOUND THEN
      RETURN;
    END IF;
    IF v_list.sealed THEN
      -- Sealed by its curator meanwhile: its cards are sealed cards, opened again as a seal opens them.
      UPDATE public.lounge_messages m
         SET metadata = jsonb_build_object('listId', p_id::text, 'sealed', true)
                        || CASE WHEN m.metadata @> '{"caption": true}'::jsonb THEN '{"caption": true}'::jsonb ELSE '{}'::jsonb END
       WHERE m.type = 'list_share' AND m.metadata @> jsonb_build_object('listId', p_id::text, 'withheld', true);
      RETURN;
    END IF;
    v_caption := v_list.title || ' · ' || (SELECT count(*) FROM public.list_items i WHERE i.list_id = p_id) || ' films'
                 || coalesce(' · by @' || (SELECT p.username FROM public.profiles p WHERE p.id = v_list.user_id), '');
  END IF;
  WITH made AS MATERIALIZED (
    SELECT x.id, (x.metadata @> '{"caption": true}'::jsonb) AS had_caption, private.a_shared_card(x, false) AS card
      FROM public.lounge_messages x
     WHERE x.type = v_type AND x.metadata @> jsonb_build_object(v_key, p_id::text, 'withheld', true)
  ), turned AS (
    UPDATE public.lounge_messages m
       SET film_id = (c.card).film_id, film_title = (c.card).film_title, film_poster = (c.card).film_poster,
           metadata = (c.card).metadata,
           content = CASE WHEN c.had_caption AND v_caption IS NOT NULL THEN v_caption ELSE m.content END
      FROM made c
     WHERE m.id = c.id
    RETURNING m.id, m.content, m.deleted_at
  )
  SELECT array_agg(id) INTO v_cards FROM turned WHERE v_caption IS NOT NULL AND content = v_caption AND deleted_at IS NULL;
  -- The replies that quoted a stack's caption have it back.
  IF v_cards IS NOT NULL THEN
    UPDATE public.lounge_messages r SET reply_to_content = v_caption
     WHERE r.reply_to_id = ANY (v_cards) AND r.reply_to_content IS NULL;
  END IF;
END;
$_$;


--
-- Name: an_appeal_may_be_heard(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.an_appeal_may_be_heard(p_ruler uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.profiles p
                  WHERE p.role = 'admin' AND private.a_judge_is_refused(p.id, p_ruler, p_target) IS NULL)
$$;


--
-- Name: can_view_user_data(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_view_user_data(target_uid uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me          uuid := auth.uid();
  is_private    boolean;
  profile_found boolean;
  is_following  boolean;
  across        boolean;
BEGIN
  IF v_me = target_uid THEN RETURN TRUE; END IF;

  -- The member's row, and whether a block stands between them and the caller either way (the rule
  -- of a_block_stands_between; a visitor, with no one signed in, has none).
  SELECT p.is_social_private, TRUE,
         EXISTS (SELECT 1 FROM public.user_blocks b
                  WHERE b.blocker_id = v_me AND b.blocked_id = p.id AND b.type = 'block')
      OR EXISTS (SELECT 1 FROM public.user_blocks b
                  WHERE b.blocker_id = p.id AND b.blocked_id = v_me AND b.type = 'block')
    INTO is_private, profile_found, across
    FROM public.profiles p WHERE p.id = target_uid;

  IF NOT COALESCE(profile_found, false) OR across THEN RETURN FALSE; END IF;
  IF NOT COALESCE(is_private, false)   THEN RETURN TRUE;  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.interactions
    WHERE type = 'follow' AND user_id = v_me AND target_user_id = target_uid
  ) INTO is_following;

  RETURN COALESCE(is_following, false);
END $$;


--
-- Name: FUNCTION can_view_user_data(target_uid uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.can_view_user_data(target_uid uuid) IS 'Whether the caller may read a member''s file: their own, an open member''s, a private member''s they follow, never one across a block. Asked by the read rules as the member; never served by the API, so no member can ask it of one member after another.';


--
-- Name: closed_ballots_told(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.closed_ballots_told(p_voters integer DEFAULT 500) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET lock_timeout TO '100ms'
    AS $$
DECLARE
  v_left  integer := GREATEST(COALESCE(p_voters, 500), 1);
  v_told  integer := 0;
  v_n     integer;
  v_wrote integer;
  v_ids   uuid[];
  v_open  boolean;
  v_msg   text;
  q       record;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('private.closed_ballots_told')) THEN
    RETURN 'waited';
  END IF;
  FOR q IN SELECT w.post_id, w.author, w.title, w.after FROM private.ballot_notices_waiting w ORDER BY w.queued_at, w.post_id LOOP
    EXIT WHEN v_left = 0;
    -- A ballot no voter can open now (ended, withheld by the house, unpublished, or gone) is told to no one more.
    SELECT p.ended_at IS NULL AND p.withheld_at IS NULL AND COALESCE(p.is_published, false) INTO v_open
      FROM public.dispatch_posts p WHERE p.id = q.post_id;
    IF NOT COALESCE(v_open, false) THEN
      DELETE FROM private.ballot_notices_waiting WHERE post_id = q.post_id;
      CONTINUE;
    END IF;
    -- Its next voters, by its key (post_id, user_id): one range from the last told, that one left out.
    SELECT array_agg(v.user_id ORDER BY v.user_id) INTO v_ids
      FROM (SELECT dv.user_id FROM public.dispatch_votes dv
             WHERE dv.post_id = q.post_id
               AND dv.user_id >= COALESCE(q.after, '00000000-0000-0000-0000-000000000000'::uuid)
               AND dv.user_id IS DISTINCT FROM q.after
             ORDER BY dv.user_id LIMIT v_left) v;
    v_n := COALESCE(cardinality(v_ids), 0);
    IF v_n > 0 THEN
      v_msg := CASE WHEN btrim(COALESCE(q.title, '')) = ''
                    THEN 'A ballot you voted in has closed.'
                    ELSE 'The ballot “' || btrim(q.title) || '” you voted in has closed.' END;
      -- Each voter, but one who blocked or muted the author, or whom the author blocked: the same test
      -- dispatch_notify makes of every other Dispatch notice; and a voter whose account is gone, never.
      INSERT INTO public.notifications (user_id, type, from_user_id, message, metadata, group_key)
      SELECT t.id, 'ballot', q.author, v_msg,
             jsonb_build_object('dispatch_post_id', q.post_id, 'kind', 'ballot', 'title', q.title),
             'endorse:post:' || q.post_id
        FROM unnest(v_ids) t(id)
       WHERE NOT EXISTS (SELECT 1 FROM public.user_blocks b
                          WHERE (b.blocker_id = t.id AND b.blocked_id = q.author)
                             OR (b.blocker_id = q.author AND b.blocked_id = t.id AND b.type = 'block'))
         AND EXISTS (SELECT 1 FROM public.profiles pr WHERE pr.id = t.id)
       ORDER BY t.id;
      GET DIAGNOSTICS v_wrote = ROW_COUNT;
      v_told := v_told + v_wrote;
    END IF;
    IF v_n < v_left THEN
      -- Every voter reached: the ballot leaves the list.
      DELETE FROM private.ballot_notices_waiting WHERE post_id = q.post_id;
    ELSE
      UPDATE private.ballot_notices_waiting SET after = v_ids[v_n] WHERE post_id = q.post_id;
    END IF;
    v_left := v_left - v_n;
  END LOOP;
  -- Nothing waits: the job leaves the schedule (a ballot put on the list puts it back).
  IF NOT EXISTS (SELECT 1 FROM private.ballot_notices_waiting) THEN
    IF to_regclass('cron.job') IS NOT NULL THEN
      PERFORM cron.unschedule(j.jobid) FROM cron.job j WHERE j.jobname = 'the-closed-ballots-are-told';
    END IF;
    RETURN 'told ' || v_told || ', none waits';
  END IF;
  RETURN 'told ' || v_told;
END $$;


--
-- Name: hidden_authors(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hidden_authors() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(array_agg(DISTINCT h.author), '{}'::uuid[]) FROM (
    SELECT b.blocked_id AS author FROM public.user_blocks b WHERE b.blocker_id = auth.uid()
    UNION ALL
    SELECT b.blocker_id FROM public.user_blocks b WHERE b.blocked_id = auth.uid() AND b.type = 'block'
  ) h;
$$;


--
-- Name: FUNCTION hidden_authors(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.hidden_authors() IS 'The members whose words are hidden from the caller: those they blocked or muted, and those who blocked them. The same rule as is_hidden_by, asked once per statement. Called by the read rules and members'' own functions as the member; never served by the API, so no member can list who blocked them.';


--
-- Name: is_hidden_by(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_hidden_by(viewer_id uuid, author_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- viewer_id is deliberately ignored; the session decides who the viewer is.
  -- The second branch is intentionally narrower: only a 'block' is mutual.
  SELECT EXISTS (
    SELECT 1 FROM public.user_blocks
    WHERE (blocker_id = auth.uid()  AND blocked_id = author_id)
       OR (blocker_id = author_id   AND blocked_id = auth.uid() AND type = 'block')
  );
$$;


--
-- Name: FUNCTION is_hidden_by(viewer_id uuid, author_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.is_hidden_by(viewer_id uuid, author_id uuid) IS 'Whether an author is hidden from the caller (the session decides who the caller is; viewer_id is ignored). Never served by the API.';


--
-- Name: lobby_edition_begun(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lobby_edition_begun() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_edition date := (now() AT TIME ZONE 'UTC')::date;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('public.lobby_choose_edition'));
  IF NOT EXISTS (SELECT 1 FROM public.lobby_editions WHERE edition = v_edition) THEN
    INSERT INTO private.lobby_drafts (edition) VALUES (v_edition) ON CONFLICT (edition) DO NOTHING;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM private.lobby_drafts) THEN
    RETURN 'chosen already';
  END IF;
  IF to_regclass('cron.job') IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = 'the-lobby-edition-is-drafted') THEN
      PERFORM cron.schedule('the-lobby-edition-is-drafted', '1 seconds', 'SELECT private.lobby_edition_drafted();');
    END IF;
  END IF;
  RETURN 'drafted';
END $$;


--
-- Name: lobby_edition_drafted(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lobby_edition_drafted(p_rows integer DEFAULT 2000) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '100ms'
    AS $$
DECLARE
  v_edition date;
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('public.lobby_choose_edition')) THEN
    RETURN 'waited';
  END IF;
  SELECT d.edition INTO v_edition FROM private.lobby_drafts d ORDER BY d.edition LIMIT 1;
  IF v_edition IS NULL THEN
    IF to_regclass('cron.job') IS NOT NULL THEN
      PERFORM cron.unschedule(j.jobid) FROM cron.job j WHERE j.jobname = 'the-lobby-edition-is-drafted';
    END IF;
    RETURN 'none drafted';
  END IF;
  RETURN private.lobby_edition_step(v_edition, p_rows);
END $$;


--
-- Name: lobby_edition_step(date, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lobby_edition_step(p_edition date, p_rows integer DEFAULT 2000) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET lock_timeout TO '100ms'
    AS $$
DECLARE
  -- the edition's moment: 00:00 UTC of its day; its regard is the day before it
  v_end     timestamptz := p_edition::timestamp AT TIME ZONE 'UTC';
  v_start   timestamptz := (p_edition::timestamp AT TIME ZONE 'UTC') - interval '1 day';
  v_rows    integer := GREATEST(COALESCE(p_rows, 2000), 1);
  v_judge   integer := GREATEST(COALESCE(p_rows, 2000) / 5, 1);
  d         record;
  v_from    timestamptz;
  v_slot    text;
  v_how     text;
  v_ats     timestamptz[];
  v_ids     uuid[];
  v_targets uuid[];
  v_members uuid[];
  v_slots   text[];
  v_n       integer;
  v_chosen  integer;
BEGIN
  SELECT * INTO d FROM private.lobby_drafts WHERE edition = p_edition FOR UPDATE;
  IF NOT FOUND THEN
    RETURN 'not drafted';
  END IF;
  -- From the last row read (one range of each source's index of when it was given), that row left out.
  v_from := GREATEST(v_start, COALESCE(d.after_at, v_start));

  IF d.stage BETWEEN 1 AND 6 THEN
    -- who marked what in the day before, and how: 'c' certified, 'q' critiqued; a source a stage
    IF d.stage = 1 THEN
      v_slot := 'log'; v_how := 'c';
      SELECT array_agg(x.created_at ORDER BY x.created_at, x.id), array_agg(x.id ORDER BY x.created_at, x.id),
             array_agg(x.target_log_id ORDER BY x.created_at, x.id), array_agg(x.user_id ORDER BY x.created_at, x.id)
        INTO v_ats, v_ids, v_targets, v_members
        FROM (SELECT x.created_at, x.id, x.target_log_id, x.user_id FROM public.interactions x
               WHERE x.type = 'endorse_log' AND x.created_at >= v_from AND x.created_at < v_end
                 AND (d.after_at IS NULL OR (x.created_at, x.id) > (d.after_at, d.after_id))
               ORDER BY x.created_at, x.id LIMIT v_rows) x;
    ELSIF d.stage = 2 THEN
      v_slot := 'log'; v_how := 'q';
      SELECT array_agg(c.created_at ORDER BY c.created_at, c.id), array_agg(c.id ORDER BY c.created_at, c.id),
             array_agg(c.log_id ORDER BY c.created_at, c.id), array_agg(c.user_id ORDER BY c.created_at, c.id)
        INTO v_ats, v_ids, v_targets, v_members
        FROM (SELECT c.created_at, c.id, c.log_id, c.user_id FROM public.log_comments c
               WHERE c.user_id IS NOT NULL AND c.withheld_at IS NULL  -- a critique the house withholds is no regard (H-B10)
                 AND c.created_at >= v_from AND c.created_at < v_end
                 AND (d.after_at IS NULL OR (c.created_at, c.id) > (d.after_at, d.after_id))
               ORDER BY c.created_at, c.id LIMIT v_rows) c;
    ELSIF d.stage = 3 THEN
      v_slot := 'list'; v_how := 'c';
      SELECT array_agg(x.created_at ORDER BY x.created_at, x.id), array_agg(x.id ORDER BY x.created_at, x.id),
             array_agg(x.target_list_id ORDER BY x.created_at, x.id), array_agg(x.user_id ORDER BY x.created_at, x.id)
        INTO v_ats, v_ids, v_targets, v_members
        FROM (SELECT x.created_at, x.id, x.target_list_id, x.user_id FROM public.interactions x
               WHERE x.type = 'endorse_list' AND x.created_at >= v_from AND x.created_at < v_end
                 AND (d.after_at IS NULL OR (x.created_at, x.id) > (d.after_at, d.after_id))
               ORDER BY x.created_at, x.id LIMIT v_rows) x;
    ELSIF d.stage = 4 THEN
      v_slot := 'list'; v_how := 'q';
      SELECT array_agg(c.created_at ORDER BY c.created_at, c.id), array_agg(c.id ORDER BY c.created_at, c.id),
             array_agg(c.list_id ORDER BY c.created_at, c.id), array_agg(c.user_id ORDER BY c.created_at, c.id)
        INTO v_ats, v_ids, v_targets, v_members
        FROM (SELECT c.created_at, c.id, c.list_id, c.user_id FROM public.list_comments c
               WHERE c.user_id IS NOT NULL AND c.withheld_at IS NULL  -- a critique the house withholds is no regard (H-B10)
                 AND c.created_at >= v_from AND c.created_at < v_end
                 AND (d.after_at IS NULL OR (c.created_at, c.id) > (d.after_at, d.after_id))
               ORDER BY c.created_at, c.id LIMIT v_rows) c;
    ELSIF d.stage = 5 THEN
      v_slot := 'post'; v_how := 'c';
      SELECT array_agg(c.created_at ORDER BY c.created_at, c.id), array_agg(c.id ORDER BY c.created_at, c.id),
             array_agg(c.post_id ORDER BY c.created_at, c.id), array_agg(c.user_id ORDER BY c.created_at, c.id)
        INTO v_ats, v_ids, v_targets, v_members
        FROM (SELECT c.created_at, c.id, c.post_id, c.user_id FROM public.dispatch_certifications c
               WHERE c.post_id IS NOT NULL AND c.created_at >= v_from AND c.created_at < v_end
                 AND (d.after_at IS NULL OR (c.created_at, c.id) > (d.after_at, d.after_id))
               ORDER BY c.created_at, c.id LIMIT v_rows) c;
    ELSE
      v_slot := 'post'; v_how := 'q';
      SELECT array_agg(c.created_at ORDER BY c.created_at, c.id), array_agg(c.id ORDER BY c.created_at, c.id),
             array_agg(c.post_id ORDER BY c.created_at, c.id), array_agg(c.user_id ORDER BY c.created_at, c.id)
        INTO v_ats, v_ids, v_targets, v_members
        FROM (SELECT c.created_at, c.id, c.post_id, c.user_id FROM public.dispatch_comments c
               WHERE c.user_id IS NOT NULL AND c.withheld_at IS NULL  -- a critique the house withholds is no regard (H-B10)
                 AND c.created_at >= v_from AND c.created_at < v_end
                 AND (d.after_at IS NULL OR (c.created_at, c.id) > (d.after_at, d.after_id))
               ORDER BY c.created_at, c.id LIMIT v_rows) c;
    END IF;
    v_n := COALESCE(cardinality(v_ids), 0);
    IF v_n > 0 THEN
      -- Never its author's own (the piece looked up by its key); a banned member's regard counts for
      -- nothing. Each member's regard of a piece kept once a way, the piece a candidate.
      WITH kept AS (
        INSERT INTO private.lobby_draft_regard (edition, slot, target, how, member)
        SELECT p_edition, v_slot, t.target, v_how, t.member
          FROM unnest(v_targets, v_members) t(target, member)
         WHERE t.member <> CASE v_slot
                             WHEN 'log'  THEN (SELECT l.user_id FROM public.logs l WHERE l.id = t.target)
                             WHEN 'list' THEN (SELECT x.user_id FROM public.lists x WHERE x.id = t.target)
                             ELSE             (SELECT p.user_id FROM public.dispatch_posts p WHERE p.id = t.target)
                           END
           AND EXISTS (SELECT 1 FROM public.profiles m WHERE m.id = t.member AND NOT coalesce(m.is_banned, false))
        ON CONFLICT DO NOTHING
        RETURNING target
      )
      INSERT INTO private.lobby_draft_candidates (edition, slot, id)
      SELECT DISTINCT p_edition, v_slot, k.target FROM kept k
      ON CONFLICT DO NOTHING;
    END IF;
    IF v_n < v_rows THEN
      UPDATE private.lobby_drafts SET stage = d.stage + 1, after_at = NULL, after_id = NULL WHERE edition = p_edition;
    ELSE
      UPDATE private.lobby_drafts SET after_at = v_ats[v_n], after_id = v_ids[v_n] WHERE edition = p_edition;
    END IF;
    RETURN 'regard ' || v_n;
  END IF;

  IF d.stage = 7 THEN
    -- The pieces honoured before, and the newest of each kind (which a quiet day reaches), as candidates.
    INSERT INTO private.lobby_draft_candidates (edition, slot, id)
    SELECT p_edition, x.slot, x.id FROM (
      SELECT e.slot, e.target_id AS id
        FROM public.lobby_editions e
       WHERE e.edition < p_edition AND e.place <= CASE e.slot WHEN 'post' THEN 3 ELSE 1 END
      UNION
      (SELECT 'log'::text, n.id FROM public.logs n
         JOIN public.profiles np ON np.id = n.user_id
        WHERE n.review IS NOT NULL AND n.review <> ''  -- as logs_reviewed_newest holds them
          AND char_length(btrim(coalesce(n.review, ''))) >= 30 AND NOT coalesce(n.is_spoiler, false)
          AND n.created_at < v_end
          AND NOT coalesce(np.is_banned, false) AND NOT coalesce(np.is_social_private, false)
          AND NOT EXISTS (SELECT 1 FROM public.lobby_editions h
                           WHERE h.edition < p_edition AND h.place <= 1 AND h.slot = 'log' AND h.target_id = n.id)
        ORDER BY n.created_at DESC, n.id DESC LIMIT 24)
      UNION
      (SELECT 'list'::text, n.id FROM public.lists n
         JOIN public.profiles np ON np.id = n.user_id
        WHERE n.is_private IS NOT TRUE AND n.created_at < v_end  -- open to all, as lists_open_newest holds them
          AND (SELECT count(*) FROM public.list_items i WHERE i.list_id = n.id) >= 4
          AND NOT coalesce(np.is_banned, false) AND NOT coalesce(np.is_social_private, false)
          AND NOT EXISTS (SELECT 1 FROM public.lobby_editions h
                           WHERE h.edition < p_edition AND h.place <= 1 AND h.slot = 'list' AND h.target_id = n.id)
        ORDER BY n.created_at DESC, n.id DESC LIMIT 24)
      UNION
      (SELECT 'post'::text, n.id FROM public.dispatch_posts n
         JOIN public.profiles np ON np.id = n.user_id
        WHERE n.is_published AND n.withheld_at IS NULL  -- as dispatch_posts_paper_latest holds them
          AND n.ended_at IS NULL AND n.spoiler_label IS NULL AND n.created_at < v_end
          AND char_length(btrim(coalesce(n.title, '') || ' ' || coalesce(nullif(n.full_content, ''), n.body, ''))) >= 30
          AND NOT coalesce(np.is_banned, false) AND NOT coalesce(np.is_social_private, false)
          AND NOT EXISTS (SELECT 1 FROM public.lobby_editions h
                           WHERE h.edition < p_edition AND h.place <= 3 AND h.slot = 'post' AND h.target_id = n.id)
        ORDER BY n.created_at DESC, n.id DESC LIMIT 24)
    ) x
    ON CONFLICT DO NOTHING;
    UPDATE private.lobby_drafts SET stage = 8, after_at = NULL, after_id = NULL, after_slot = NULL WHERE edition = p_edition;
    RETURN 'candidates';
  END IF;

  IF d.stage = 8 THEN
    -- The next candidates, by their key from the last judged; each read by its key and judged as every
    -- piece always was, with its day.
    SELECT array_agg(k.slot ORDER BY k.slot, k.id), array_agg(k.id ORDER BY k.slot, k.id) INTO v_slots, v_ids
      FROM (SELECT k.slot, k.id FROM private.lobby_draft_candidates k
             WHERE k.edition = p_edition
               AND (d.after_slot IS NULL OR (k.slot, k.id) > (d.after_slot, d.after_id))
             ORDER BY k.slot, k.id LIMIT v_judge) k;
    v_n := COALESCE(cardinality(v_ids), 0);
    IF v_n > 0 THEN
      INSERT INTO private.lobby_draft_pieces (edition, slot, id, author, created_at, day)
      SELECT p_edition, a.slot, a.id, a.author, a.created_at,
             (SELECT count(*) FROM private.lobby_draft_regard r WHERE r.edition = p_edition AND r.slot = a.slot AND r.target = a.id)
        FROM (
          SELECT 'log'::text AS slot, l.id, l.user_id AS author, l.created_at
            FROM unnest(v_slots, v_ids) k(slot, id)
            CROSS JOIN LATERAL (SELECT x.id, x.user_id, x.created_at, x.review, x.is_spoiler, x.withheld_at
                                  FROM public.logs x WHERE x.id = k.id OFFSET 0) l
            JOIN public.profiles p ON p.id = l.user_id
           WHERE k.slot = 'log'
             AND btrim(coalesce(l.review, '')) <> '' AND NOT coalesce(l.is_spoiler, false)
             AND l.withheld_at IS NULL  -- a piece the house withholds never hangs (H-B10)
             AND l.created_at < v_end
             AND NOT coalesce(p.is_banned, false) AND NOT coalesce(p.is_social_private, false)
             AND NOT EXISTS (SELECT 1 FROM public.lobby_withheld w WHERE w.kind = 'log' AND w.target_id = l.id)
             AND NOT EXISTS (SELECT 1 FROM public.reports r WHERE r.content_type = 'log' AND r.content_id = l.id::text
                                                              AND coalesce(r.status, 'pending') = 'pending')
          UNION ALL
          SELECT 'list', s.id, s.user_id, s.created_at
            FROM unnest(v_slots, v_ids) k(slot, id)
            CROSS JOIN LATERAL (SELECT x.id, x.user_id, x.created_at, x.is_private, x.withheld_at
                                  FROM public.lists x WHERE x.id = k.id OFFSET 0) s
            JOIN public.profiles p ON p.id = s.user_id
           WHERE k.slot = 'list'
             AND NOT coalesce(s.is_private, false)
             AND s.withheld_at IS NULL  -- a piece the house withholds never hangs (H-B10)
             AND (SELECT count(*) FROM public.list_items i WHERE i.list_id = s.id) >= 4
             AND s.created_at < v_end
             AND NOT coalesce(p.is_banned, false) AND NOT coalesce(p.is_social_private, false)
             AND NOT EXISTS (SELECT 1 FROM public.lobby_withheld w WHERE w.kind = 'list' AND w.target_id = s.id)
             AND NOT EXISTS (SELECT 1 FROM public.reports r WHERE r.content_type = 'list' AND r.content_id = s.id::text
                                                              AND coalesce(r.status, 'pending') = 'pending')
          UNION ALL
          SELECT 'post', d2.id, d2.user_id, d2.created_at
            FROM unnest(v_slots, v_ids) k(slot, id)
            CROSS JOIN LATERAL (SELECT x.id, x.user_id, x.created_at, x.is_published, x.withheld_at, x.ended_at, x.spoiler_label
                                  FROM public.dispatch_posts x WHERE x.id = k.id OFFSET 0) d2
            JOIN public.profiles p ON p.id = d2.user_id
           WHERE k.slot = 'post'
             AND coalesce(d2.is_published, false) AND d2.withheld_at IS NULL AND d2.ended_at IS NULL
             AND d2.spoiler_label IS NULL AND d2.created_at < v_end
             AND NOT coalesce(p.is_banned, false) AND NOT coalesce(p.is_social_private, false)
             AND NOT EXISTS (SELECT 1 FROM public.lobby_withheld w WHERE w.kind = 'post' AND w.target_id = d2.id)
             AND NOT EXISTS (SELECT 1 FROM public.reports r WHERE r.content_type = 'dispatch_post' AND r.content_id = d2.id::text
                                                              AND coalesce(r.status, 'pending') = 'pending')
        ) a
      ON CONFLICT DO NOTHING;
    END IF;
    IF v_n < v_judge THEN
      UPDATE private.lobby_drafts SET stage = 9, after_slot = NULL, after_id = NULL WHERE edition = p_edition;
    ELSE
      UPDATE private.lobby_drafts SET after_slot = v_slots[v_n], after_id = v_ids[v_n] WHERE edition = p_edition;
    END IF;
    RETURN 'judged ' || v_n;
  END IF;

  -- Stage 9: the edition placed from the pieces judged, as it always was placed.
  WITH honoured AS (
    -- what the wall has shown before: first log, first stack, first three filings
    SELECT e.slot, e.target_id, e.author_id, e.edition
      FROM public.lobby_editions e
     WHERE e.edition < p_edition AND e.place <= CASE e.slot WHEN 'post' THEN 3 ELSE 1 END
  ),
  scored AS (
    SELECT a.slot, a.id, a.author, a.created_at, a.day,
           EXISTS (SELECT 1 FROM honoured h WHERE h.slot = a.slot AND h.target_id = a.id) AS had_its_day,
           EXISTS (SELECT 1 FROM honoured h WHERE h.author_id = a.author AND h.edition >= p_edition - 7) AS honoured_lately
      FROM private.lobby_draft_pieces a WHERE a.edition = p_edition
  ),
  ranked AS (
    SELECT s.*,
           row_number() OVER (PARTITION BY s.slot
                              ORDER BY s.had_its_day, s.day DESC, s.honoured_lately,
                                       s.created_at DESC, s.id) AS merit
      FROM scored s
  ),
  -- one member, one bill: each author's second piece in a slot, and the first log's author among stacks
  spread AS (
    SELECT r.*,
           row_number() OVER (PARTITION BY r.slot, r.author ORDER BY r.merit) AS nth,
           (r.slot = 'list' AND r.author = (SELECT author FROM ranked WHERE slot = 'log' AND merit = 1)) AS holds_the_log
      FROM ranked r
  ),
  placed AS (
    SELECT s.slot, s.id, s.author, s.day,
           row_number() OVER (PARTITION BY s.slot
                              ORDER BY s.holds_the_log, (s.slot = 'post' AND s.nth > 1), s.merit) AS place
      FROM spread s
  )
  INSERT INTO public.lobby_editions (edition, slot, place, target_id, author_id, score)
  SELECT p_edition, slot, place, id, author, day FROM placed WHERE place <= 12;

  GET DIAGNOSTICS v_chosen = ROW_COUNT;

  -- The authors of what hangs are told without a push — once a piece, never again (the notices already
  -- told found by the index of the Lobby's own notices).
  INSERT INTO public.notifications (user_id, type, message, group_key)
  SELECT e.author_id, 'featured',
         CASE e.slot WHEN 'log'  THEN 'Your log hangs in the Lobby today.'
                     WHEN 'list' THEN 'Your stack hangs in the Lobby today.'
                     ELSE             'Your filing hangs in the Lobby today.' END,
         'lobby:' || e.slot || ':' || e.target_id
    FROM public.lobby_editions e
   WHERE e.edition = p_edition
     AND e.place <= CASE e.slot WHEN 'post' THEN 3 ELSE 1 END
     AND NOT EXISTS (SELECT 1 FROM public.notifications n
                      WHERE n.type = 'featured' AND n.group_key = 'lobby:' || e.slot || ':' || e.target_id);

  -- The draft goes: its rows emptied at once when no other draft waits.
  DELETE FROM private.lobby_drafts WHERE edition = p_edition;
  IF NOT EXISTS (SELECT 1 FROM private.lobby_drafts) THEN
    TRUNCATE private.lobby_draft_regard, private.lobby_draft_candidates, private.lobby_draft_pieces;
  ELSE
    DELETE FROM private.lobby_draft_regard WHERE edition = p_edition;
    DELETE FROM private.lobby_draft_candidates WHERE edition = p_edition;
    DELETE FROM private.lobby_draft_pieces WHERE edition = p_edition;
  END IF;
  RETURN 'chosen ' || v_chosen;
END $$;


--
-- Name: logs_seen_again_in(uuid, date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.logs_seen_again_in(p_user_id uuid, p_first date, p_last date) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT coalesce(array_agg(l.id), '{}'::uuid[])
    FROM public.logs l
   WHERE jsonb_typeof(l.viewing_history) = 'array' AND l.viewing_history <> '[]'::jsonb
     AND private.viewing_months(l.user_id, l.viewing_history, l.created_at) && private.viewing_months_between(p_user_id, p_first, p_last);
$$;


--
-- Name: member_grams; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.member_grams (
    gram text NOT NULL COLLATE pg_catalog."C",
    username text NOT NULL,
    id uuid NOT NULL
);


--
-- Name: member_grams_apply(private.member_grams[], private.member_grams[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_grams_apply(p_gone private.member_grams[], p_came private.member_grams[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_off_g text[];
  v_off_n integer[];
  v_on_g  text[];
  v_on_n  integer[];
  v_cut   text[] := '{}';
  v_last  text[] := '{}';
  v_gram  text;
  v_k     integer;
  v_at    text;
  v_n     integer;
  v_cap   integer;
BEGIN
  -- Nothing to settle (members the job has not reached): the lists not touched.
  IF cardinality(p_gone) = 0 AND cardinality(p_came) = 0 THEN
    RETURN 0;
  END IF;
  SELECT f.cap INTO v_cap FROM private.member_grams_filled f;
  -- A head for each new piece; then every piece touched, locked in one order.
  INSERT INTO private.member_gram_heads (gram, holders, listed, upto)
  SELECT DISTINCT c.gram, 0, 0, NULL::text FROM unnest(p_came) c ORDER BY 1
  ON CONFLICT (gram) DO NOTHING;
  PERFORM 1 FROM private.member_gram_heads h
   WHERE h.gram IN (SELECT g.gram FROM unnest(p_gone) g UNION SELECT c.gram FROM unnest(p_came) c)
   ORDER BY h.gram FOR UPDATE;
  -- The leavers off the lists; the comers on, where their piece lists every holder or they sort at or
  -- before its last. Each counted by piece.
  WITH off AS (
    DELETE FROM private.member_grams m USING unnest(p_gone) g
     WHERE m.gram = g.gram AND m.username = g.username AND m.id = g.id
    RETURNING m.gram
  ) SELECT coalesce(array_agg(o.gram), '{}'), coalesce(array_agg(o.n), '{}') INTO v_off_g, v_off_n
      FROM (SELECT off.gram, count(*)::integer AS n FROM off GROUP BY off.gram) o;
  WITH came AS (
    INSERT INTO private.member_grams (gram, username, id)
    SELECT c.gram, c.username, c.id FROM unnest(p_came) c JOIN private.member_gram_heads h ON h.gram = c.gram
     WHERE h.upto IS NULL OR c.username <= h.upto
    RETURNING gram
  ) SELECT coalesce(array_agg(o.gram), '{}'), coalesce(array_agg(o.n), '{}') INTO v_on_g, v_on_n
      FROM (SELECT came.gram, count(*)::integer AS n FROM came GROUP BY came.gram) o;
  -- A list past its cap (a thousand) ends at its thousandth: those past it go, the last of them first.
  FOR v_gram, v_k IN
    SELECT h.gram, h.listed + o.n - coalesce(f.n, 0) - v_cap
      FROM unnest(v_on_g, v_on_n) o(gram, n) JOIN private.member_gram_heads h ON h.gram = o.gram
      LEFT JOIN unnest(v_off_g, v_off_n) f(gram, n) ON f.gram = o.gram
     WHERE h.listed + o.n - coalesce(f.n, 0) > v_cap
     ORDER BY h.gram
  LOOP
    DELETE FROM private.member_grams m
     WHERE m.gram = v_gram
       AND m.username IN (SELECT x.username FROM private.member_grams x WHERE x.gram = v_gram ORDER BY x.username DESC LIMIT v_k);
    SELECT max(m.username) INTO v_at FROM private.member_grams m WHERE m.gram = v_gram;
    v_cut := v_cut || v_gram;
    v_last := v_last || v_at;
  END LOOP;
  -- Each head written once: its holders by the change, its list as it now ends.
  UPDATE private.member_gram_heads h
     SET holders = h.holders + d.came - d.gone,
         listed  = CASE WHEN c.last IS NOT NULL THEN v_cap ELSE h.listed + d.went_on - d.came_off END,
         upto    = CASE WHEN c.last IS NOT NULL THEN c.last
                        WHEN h.holders + d.came - d.gone = h.listed + d.went_on - d.came_off THEN NULL
                        ELSE h.upto END
    FROM (SELECT x.gram, sum(x.came) AS came, sum(x.gone) AS gone, sum(x.went_on) AS went_on, sum(x.came_off) AS came_off
            FROM (SELECT c.gram, 1 AS came, 0 AS gone, 0 AS went_on, 0 AS came_off FROM unnest(p_came) c
                  UNION ALL SELECT g.gram, 0, 1, 0, 0 FROM unnest(p_gone) g
                  UNION ALL SELECT o.gram, 0, 0, o.n, 0 FROM unnest(v_on_g, v_on_n) o(gram, n)
                  UNION ALL SELECT f.gram, 0, 0, 0, f.n FROM unnest(v_off_g, v_off_n) f(gram, n)) x
           GROUP BY x.gram) d
    LEFT JOIN (SELECT unnest(v_cut) AS gram, unnest(v_last) AS last) c ON c.gram = d.gram
   WHERE h.gram = d.gram;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;


--
-- Name: member_grams_fill(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_grams_fill(p_members integer DEFAULT 500) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET lock_timeout TO '100ms'
    AS $$
DECLARE
  v_after    uuid;
  v_complete boolean;
  v_came     private.member_grams[];
  v_read     integer;
  v_last     uuid;
BEGIN
  SELECT f.complete INTO v_complete FROM private.member_grams_filled f;
  IF NOT v_complete THEN
    -- Read again once the lock is held: the last run's end, and every member committed before it. Its
    -- row is held too, and a run gives way at once to whoever holds it.
    BEGIN
      PERFORM pg_advisory_xact_lock(hashtext('private.member_grams_fill'));
      SELECT f.complete, f.after INTO v_complete, v_after FROM private.member_grams_filled f FOR UPDATE NOWAIT;
    EXCEPTION WHEN lock_not_available THEN
      RETURN 'waited';
    END;
  END IF;
  IF v_complete THEN
    IF to_regclass('cron.job') IS NOT NULL THEN
      PERFORM cron.unschedule(j.jobid) FROM cron.job j WHERE j.jobname = 'the-members-pieces-are-listed';
    END IF;
    RETURN 'complete';
  END IF;
  -- The next members after the last run's, each with every piece they hold.
  WITH next AS (
    SELECT p.id, p.username, p.display_name FROM public.profiles p
     -- One range of the ids from the last run's end (the same plan at every run), its end itself left out.
     WHERE p.id >= COALESCE(v_after, '00000000-0000-0000-0000-000000000000'::uuid) AND p.id IS DISTINCT FROM v_after
     ORDER BY p.id LIMIT GREATEST(p_members, 1)
  )
  SELECT array_agg(ROW(g.g, n.username, n.id)::private.member_grams) FILTER (WHERE g.g IS NOT NULL),
         count(DISTINCT n.id), (array_agg(n.id ORDER BY n.id DESC))[1]
    INTO v_came, v_read, v_last
    FROM next n LEFT JOIN LATERAL unnest(private.member_grams_of(n.username, n.display_name)) g(g) ON true;
  IF v_read = 0 THEN
    UPDATE private.member_grams_filled SET complete = true, ended = now();
    ANALYZE private.member_gram_heads;
    ANALYZE private.member_grams;
    RETURN 'complete';
  END IF;
  PERFORM private.member_grams_apply('{}', COALESCE(v_came, '{}'));
  UPDATE private.member_grams_filled SET after = v_last, members = members + v_read;
  RETURN 'listed ' || v_read;
END $$;


--
-- Name: member_grams_of(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_grams_of(p_handle text, p_name text) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  -- Each three characters of the handle and of the name, lower case, once, in byte order (the order the
  -- pieces are locked in): marked "a" as held anywhere (a search of handles and names), and the handle's
  -- marked "h" as well (a search of handles alone).
  SELECT coalesce(array_agg(DISTINCT g.gram ORDER BY g.gram), '{}'::text[])
    FROM (SELECT (v.f || substr(v.x, i, 3)) COLLATE "C" AS gram
            FROM (VALUES (lower(p_handle), 'a'), (lower(p_name), 'a'), (lower(p_handle), 'h')) v(x, f)
           CROSS JOIN LATERAL generate_series(1, char_length(v.x) - 2) i) g
$$;


--
-- Name: member_grams_settle(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_grams_settle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_queued   text := COALESCE(current_setting('reelhouse.member_grams_queued', true), '');
  v_complete boolean;
  v_after    uuid;
BEGIN
  -- Run once a written member as the transaction commits: the first settles everything waiting, the rest
  -- find nothing new.
  IF v_queued = '' OR v_queued = COALESCE(current_setting('reelhouse.member_grams_settled', true), '') THEN
    RETURN NULL;
  END IF;
  -- While the job is filling the lists, only the members it has passed are settled here (it reads the
  -- others as they stand): its lock is taken, shared, before its row is read, so a batch of the job
  -- reads this transaction's writes once committed or lists them before this reads how far it went.
  SELECT f.complete, f.after INTO v_complete, v_after FROM private.member_grams_filled f;
  IF NOT v_complete THEN
    PERFORM pg_advisory_xact_lock_shared(hashtext('private.member_grams_fill'));
    SELECT f.complete, f.after INTO v_complete, v_after FROM private.member_grams_filled f;
  END IF;
  -- Each member's net change to each piece: joined and left in one transaction is no change.
  PERFORM private.member_grams_apply(
    ARRAY(SELECT ROW(w.gram, w.username, w.id)::private.member_grams FROM private.member_grams_waiting w
           WHERE w.txid = txid_current() AND (v_complete OR w.id <= v_after)
           GROUP BY w.gram, w.username, w.id HAVING sum(w.sign) < 0),
    ARRAY(SELECT ROW(w.gram, w.username, w.id)::private.member_grams FROM private.member_grams_waiting w
           WHERE w.txid = txid_current() AND (v_complete OR w.id <= v_after)
           GROUP BY w.gram, w.username, w.id HAVING sum(w.sign) > 0));
  DELETE FROM private.member_grams_waiting WHERE txid = txid_current();
  PERFORM set_config('reelhouse.member_grams_settled', v_queued, true);
  RETURN NULL;
END $$;


--
-- Name: member_pattern_grams(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.member_pattern_grams(p_pattern text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_text text := lower(p_pattern);
  v_n    integer := char_length(v_text);
  v_i    integer := 1;
  v_c    text;
  v_seg  text := '';
  v_out  text[] := '{}';
BEGIN
  -- The pieces every holder of the words holds: each three characters of each run of the words between
  -- wildcards, its escapes read, lower case as ILIKE reads them. NULL when no run has three.
  WHILE v_i <= v_n + 1 LOOP
    v_c := CASE WHEN v_i <= v_n THEN substr(v_text, v_i, 1) END;
    IF v_c = '\' AND v_i < v_n THEN
      v_seg := v_seg || substr(v_text, v_i + 1, 1);
      v_i := v_i + 2;
      CONTINUE;
    END IF;
    IF v_c IS NULL OR v_c IN ('%', '_') THEN
      FOR k IN 1 .. char_length(v_seg) - 2 LOOP
        v_out := v_out || substr(v_seg, k, 3);
      END LOOP;
      v_seg := '';
    ELSE
      v_seg := v_seg || v_c;
    END IF;
    v_i := v_i + 1;
  END LOOP;
  IF cardinality(v_out) = 0 THEN
    RETURN NULL;
  END IF;
  RETURN (SELECT array_agg(DISTINCT g ORDER BY g) FROM unnest(v_out) g);
END $$;


--
-- Name: members_blocking_me(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.members_blocking_me() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The members who have blocked the caller: for the read rules alone, which read each of them as no
  -- one. None for a visitor (no one signed in), and none for an admin, who moderates every member.
  -- Read as the house (the owner of the tables), so the profiles rule that asks it is not asked again.
  SELECT CASE
    WHEN (SELECT auth.uid()) IS NULL THEN '{}'::uuid[]
    WHEN EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = (SELECT auth.uid()) AND p.role = 'admin') THEN '{}'::uuid[]
    ELSE COALESCE((SELECT array_agg(b.blocker_id) FROM public.user_blocks b
                    WHERE b.blocked_id = (SELECT auth.uid()) AND b.type = 'block'), '{}'::uuid[])
  END;
$$;


--
-- Name: FUNCTION members_blocking_me(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.members_blocking_me() IS 'The members who have blocked the caller, for the read rules that read each of them as no one to the caller. Never served by the API.';


--
-- Name: no_block_stands_with(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.no_block_stands_with(p_one uuid, p_two uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Whether no block stands, either way, between the caller and either of two members: the follows
  -- rule asks it of a follow whose one end's file is open to the caller. The blocks are read as the
  -- house (a member may read only their own); a visitor has none.
  SELECT NOT EXISTS (SELECT 1 FROM public.user_blocks b
                      WHERE b.blocker_id = (SELECT auth.uid()) AND b.blocked_id IN (p_one, p_two) AND b.type = 'block')
     AND NOT EXISTS (SELECT 1 FROM public.user_blocks b
                      WHERE b.blocked_id = (SELECT auth.uid()) AND b.blocker_id IN (p_one, p_two) AND b.type = 'block');
$$;


--
-- Name: FUNCTION no_block_stands_with(p_one uuid, p_two uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.no_block_stands_with(p_one uuid, p_two uuid) IS 'Whether no block stands between the caller and either of two members, for the follows rule. Never served by the API.';


--
-- Name: pattern_grams(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pattern_grams(p_pattern text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_text text := lower(p_pattern);
  v_n    integer := char_length(v_text);
  v_i    integer := 1;
  v_c    text;
  v_seg  text := '';
  v_out  text[] := '{}';
BEGIN
  WHILE v_i <= v_n + 1 LOOP
    v_c := CASE WHEN v_i <= v_n THEN substr(v_text, v_i, 1) END;
    IF v_c = '\' AND v_i < v_n THEN
      v_seg := v_seg || substr(v_text, v_i + 1, 1);
      v_i := v_i + 2;
      CONTINUE;
    END IF;
    IF v_c IS NULL OR v_c IN ('%', '_') THEN
      IF char_length(v_seg) = 1 THEN
        v_out := v_out || v_seg;
      ELSE
        FOR k IN 1 .. char_length(v_seg) - 1 LOOP
          v_out := v_out || substr(v_seg, k, 2);
        END LOOP;
      END IF;
      v_seg := '';
    ELSE
      v_seg := v_seg || v_c;
    END IF;
    v_i := v_i + 1;
  END LOOP;
  RETURN CASE WHEN cardinality(v_out) = 0 THEN NULL ELSE v_out END;
END $$;


--
-- Name: search_grams(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.search_grams(p_one text, p_two text) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT private.short_grams(coalesce(p_one, '')) || private.short_grams(coalesce(p_two, ''));
$$;


--
-- Name: short_grams(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.short_grams(p_text text) RETURNS text[]
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT string_to_array(x.t, NULL)
      || ARRAY(SELECT m[1] FROM regexp_matches(x.t, '(..)', 'g') m)
      || ARRAY(SELECT m[1] FROM regexp_matches(substr(x.t, 2), '(..)', 'g') m)
    FROM (SELECT lower(p_text) AS t) x;
$$;


--
-- Name: the_cards_made_true(integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.the_cards_made_true(p_part integer) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  -- The part's ids: from x0000000-0000-0000-0000-000000000000 to xfffffff-ffff-ffff-ffff-ffffffffffff.
  v_from uuid;
  v_last uuid;
  v_made integer;
BEGIN
  IF p_part IS NULL OR p_part NOT BETWEEN 0 AND 15 THEN
    RAISE EXCEPTION 'A part is a figure from 0 to 15.' USING ERRCODE = '22023';
  END IF;
  v_from := (to_hex(p_part) || '0000000-0000-0000-0000-000000000000')::uuid;
  v_last := (to_hex(p_part) || 'fffffff-ffff-ffff-ffff-ffffffffffff')::uuid;
  WITH cards AS MATERIALIZED (
    SELECT x.id, private.a_shared_card(x, false) AS card
      FROM public.lounge_messages x
     WHERE x.id BETWEEN v_from AND v_last
       AND x.type IN ('film_share', 'person_share', 'log_share', 'list_share', 'dossier_share')
       AND NOT (coalesce(x.metadata, '{}'::jsonb) @> '{"gone": true}'::jsonb)
       AND NOT (coalesce(x.metadata, '{}'::jsonb) @> '{"sealed": true}'::jsonb)
  )
  UPDATE public.lounge_messages m
     SET film_id = (c.card).film_id, film_title = (c.card).film_title, film_poster = (c.card).film_poster,
         metadata = (c.card).metadata
    FROM cards c
   WHERE m.id = c.id
     AND (m.film_id, m.film_title, m.film_poster, m.metadata)
         IS DISTINCT FROM ((c.card).film_id, (c.card).film_title, (c.card).film_poster, (c.card).metadata);
  GET DIAGNOSTICS v_made = ROW_COUNT;
  RETURN v_made;
END $$;


--
-- Name: the_moderators_words_made_clean(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.the_moderators_words_made_clean() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_made  integer := 0;
  v_count integer;
BEGIN
  -- The notices of an appeal heard, written in the moment it was heard.
  UPDATE public.notifications n
     SET body = public.clean_member_text(n.body), message = public.clean_member_text(n.message)
    FROM public.mod_actions m
   WHERE m.appeal_judged_at IS NOT NULL
     AND n.user_id = m.target_user_id AND n.created_at = m.appeal_judged_at
     AND n.type = 'moderation' AND n.metadata ->> 'action' = 'appeal'
     AND (n.body, n.message) IS DISTINCT FROM (public.clean_member_text(n.body), public.clean_member_text(n.message));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_made := v_made + v_count;
  -- The notices of a sanction lifted, written in the moment it was lifted, the reason they carry with them.
  UPDATE public.notifications n
     SET body = public.clean_member_text(n.body), message = public.clean_member_text(n.message),
         metadata = CASE WHEN n.metadata ? 'reason'
                         THEN jsonb_set(n.metadata, '{reason}', to_jsonb(public.clean_member_text(n.metadata ->> 'reason')))
                         ELSE n.metadata END
    FROM public.mod_actions m
   WHERE m.lifted_at IS NOT NULL
     AND n.user_id = m.target_user_id AND n.created_at = m.lifted_at
     AND n.type = 'moderation' AND n.metadata ->> 'action' = 'lift'
     AND (n.body, n.message, n.metadata ->> 'reason')
         IS DISTINCT FROM (public.clean_member_text(n.body), public.clean_member_text(n.message), public.clean_member_text(n.metadata ->> 'reason'));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_made := v_made + v_count;
  -- The verdicts' appeals, the Tribunal's words and the lifts' reasons.
  UPDATE public.mod_actions
     SET appeal = public.clean_member_text(appeal), appeal_note = public.clean_member_text(appeal_note),
         lift_reason = public.clean_member_text(lift_reason)
   WHERE (appeal IS NOT NULL OR lift_reason IS NOT NULL)
     AND (appeal, appeal_note, lift_reason)
         IS DISTINCT FROM (public.clean_member_text(appeal), public.clean_member_text(appeal_note), public.clean_member_text(lift_reason));
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_made + v_count;
END $$;


--
-- Name: viewing_months(uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.viewing_months(p_user uuid, p_history jsonb, p_created timestamp with time zone) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT ARRAY(
    SELECT DISTINCT p_user::text || '/' || k.month
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_history) = 'array' THEN p_history ELSE '[]'::jsonb END) e
     CROSS JOIN LATERAL (SELECT e->>'date' AS d) w
     CROSS JOIN LATERAL (SELECT coalesce(w.d ~ '^\d{4}-\d{2}-\d{2}', false) AS written,
                                coalesce(w.d ~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|1[0-9]|2[0-8])' AND left(w.d, 4) <> '0000', false) AS sure) s
     CROSS JOIN LATERAL (
       SELECT left(w.d, 7) AS month WHERE s.written
       UNION ALL
       SELECT lpad(extract(year FROM x.day)::int::text, 4, '0') || '-' || lpad(extract(month FROM x.day)::int::text, 2, '0')
         FROM (VALUES ((p_created AT TIME ZONE 'UTC')::date - 1), ((p_created AT TIME ZONE 'UTC')::date + 1)) x(day)
        WHERE NOT s.sure AND p_created IS NOT NULL
     ) k
     WHERE jsonb_typeof(e) = 'object'
  );
$$;


--
-- Name: viewing_months_between(uuid, date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.viewing_months_between(p_user uuid, p_first date, p_last date) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT ARRAY(
    SELECT p_user::text || '/' || lpad(extract(year FROM m)::int::text, 4, '0') || '-' || lpad(extract(month FROM m)::int::text, 2, '0')
      FROM generate_series(date_trunc('month', p_first::timestamp), p_last::timestamp, interval '1 month') m
  );
$$;


--
-- Name: viewings_between(uuid, date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.viewings_between(p_user_id uuid, p_first date, p_last date) RETURNS TABLE(log_id uuid, viewing_id uuid, film_id integer, film_title text, poster_path text, rating numeric, day date)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT l.id, l.viewing_id, l.film_id, l.film_title, l.poster_path, l.rating, l.watched_date
    FROM public.logs l
   WHERE l.user_id = p_user_id
     AND l.watched_date BETWEEN p_first AND p_last
     AND (l.withheld_at IS NULL OR l.user_id = (SELECT auth.uid()))  -- withheld: its author's alone (H-B10)
  UNION ALL
  SELECT l.id, h.viewing_id, l.film_id, l.film_title, l.poster_path, h.rating, h.day
    FROM public.logs l
   CROSS JOIN LATERAL (
     SELECT CASE WHEN pg_input_is_valid(e->>'viewingId', 'uuid') THEN (e->>'viewingId')::uuid END AS viewing_id,
            COALESCE(CASE WHEN e->>'date' ~ '^\d{4}-\d{2}-\d{2}' AND pg_input_is_valid(left(e->>'date', 10), 'date')
                          THEN left(e->>'date', 10)::date END,
                     l.created_at::date) AS day,
            CASE WHEN pg_input_is_valid(e->>'rating', 'numeric') THEN (e->>'rating')::numeric END AS rating
       FROM jsonb_array_elements(CASE WHEN jsonb_typeof(l.viewing_history) = 'array' THEN l.viewing_history ELSE '[]'::jsonb END) e
      WHERE jsonb_typeof(e) = 'object'
   ) h
   WHERE l.id = ANY ((SELECT private.logs_seen_again_in(p_user_id, p_first, p_last))::uuid[])
     AND l.user_id = p_user_id
     AND (l.withheld_at IS NULL OR l.user_id = (SELECT auth.uid()))  -- withheld: its author's alone (H-B10)
     AND h.day BETWEEN p_first AND p_last;
$$;


--
-- Name: a_block_stands_between(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_block_stands_between(p_one uuid, p_other uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_blocks b
     WHERE b.type = 'block'
       AND ((b.blocker_id = p_one AND b.blocked_id = p_other)
         OR (b.blocker_id = p_other AND b.blocked_id = p_one))
  );
$$;


--
-- Name: a_cards_author(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_cards_author(p_type text, p_metadata jsonb) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  -- The piece a card shows, named as the phone and the website name it in the card's metadata; a
  -- name that is not an id, or a piece no longer in the house, has no author.
  SELECT CASE p_type
           WHEN 'log_share'     THEN (SELECT l.user_id FROM public.logs l WHERE l.id = k.id)
           WHEN 'list_share'    THEN (SELECT s.user_id FROM public.lists s WHERE s.id = k.id)
           WHEN 'dossier_share' THEN (SELECT d.user_id FROM public.dispatch_posts d WHERE d.id = k.id)
         END
    FROM (SELECT CASE WHEN n.named ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN n.named::uuid END AS id
            FROM (SELECT CASE p_type
                           WHEN 'log_share'     THEN coalesce(p_metadata ->> 'log_id', p_metadata ->> 'logId')
                           WHEN 'list_share'    THEN p_metadata ->> 'listId'
                           WHEN 'dossier_share' THEN coalesce(p_metadata ->> 'dossier_id', p_metadata ->> 'dossierId')
                         END AS named) n) k
$_$;


--
-- Name: a_certification_takes_its_notice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_certification_takes_its_notice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Its notice was written with these keys (notify_on_interaction); its author may be gone with
  -- the log or the stack, so the notice is found by its sender and its key.
  DELETE FROM public.notifications
   WHERE from_user_id = OLD.user_id
     AND type = 'endorse'
     AND group_key = CASE OLD.type
           WHEN 'endorse_log' THEN 'endorse:log:' || OLD.target_log_id
           ELSE 'endorse:list:' || OLD.target_list_id
         END;
  RETURN NULL;
END $$;


--
-- Name: a_critique_has_its_page(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_critique_has_its_page() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'log_comments' THEN
    IF NOT EXISTS (SELECT 1 FROM public.logs l WHERE l.id = NEW.log_id) THEN
      RAISE EXCEPTION 'LOG_GONE' USING ERRCODE = 'P0002';
    END IF;
  ELSIF TG_TABLE_NAME = 'list_comments' THEN
    IF NOT EXISTS (SELECT 1 FROM public.lists l WHERE l.id = NEW.list_id) THEN
      RAISE EXCEPTION 'STACK_GONE' USING ERRCODE = 'P0002';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: a_critique_takes_its_notice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_critique_takes_its_notice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_group text;
  v_left  boolean;
BEGIN
  -- The piece the critique was on, as its notice's group names it, and whether its member has
  -- another critique there still.
  IF TG_TABLE_NAME = 'log_comments' THEN
    v_group := 'endorse:log:' || OLD.log_id;
    v_left := EXISTS (SELECT 1 FROM public.log_comments WHERE log_id = OLD.log_id AND user_id = OLD.user_id);
  ELSIF TG_TABLE_NAME = 'list_comments' THEN
    v_group := 'endorse:list:' || OLD.list_id;
    v_left := EXISTS (SELECT 1 FROM public.list_comments WHERE list_id = OLD.list_id AND user_id = OLD.user_id);
  ELSIF TG_TABLE_NAME = 'dispatch_comments' THEN
    v_group := 'endorse:post:' || OLD.post_id;
    v_left := EXISTS (SELECT 1 FROM public.dispatch_comments WHERE post_id = OLD.post_id AND user_id = OLD.user_id);
  ELSE
    RETURN NULL;
  END IF;

  -- The notices naming this critique: its own, and the answer's (a filing's critique taken as its answer).
  DELETE FROM public.notifications
   WHERE from_user_id = OLD.user_id
     AND type = 'comment'
     AND group_key = v_group
     AND metadata ->> 'comment_id' = OLD.id::text;

  -- A notice written before notices named their critique: taken once its member has none left there.
  IF NOT v_left THEN
    DELETE FROM public.notifications
     WHERE from_user_id = OLD.user_id
       AND type = 'comment'
       AND group_key = v_group
       AND NOT (coalesce(metadata, '{}'::jsonb) ? 'comment_id');
  END IF;
  RETURN NULL;
END $$;


--
-- Name: a_deleted_stack_leaves_its_cards(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_deleted_stack_leaves_its_cards() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- The house's own write, so a_keeps_what_it_is lets it (the sharer's message is not the deleter's).
  UPDATE public.lounge_messages m
     SET metadata = jsonb_build_object('listId', OLD.id::text, 'gone', true)
   WHERE m.type = 'list_share'
     AND m.metadata <> '{}'::jsonb
     AND m.metadata @> jsonb_build_object('listId', OLD.id::text);
  RETURN NULL;
END $$;


--
-- Name: a_dispatch_certification_takes_its_notice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_dispatch_certification_takes_its_notice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Found by what dispatch_notify_certify wrote in its metadata: a critique's by the critique
  -- (whatever key it was written under), a filing's by the filing and no critique.
  IF OLD.comment_id IS NOT NULL THEN
    DELETE FROM public.notifications
     WHERE from_user_id = OLD.user_id
       AND type = 'endorse'
       AND metadata ->> 'comment_id' = OLD.comment_id::text;
  ELSE
    DELETE FROM public.notifications
     WHERE from_user_id = OLD.user_id
       AND type = 'endorse'
       AND metadata ->> 'dispatch_post_id' = OLD.post_id::text
       AND NOT (metadata ? 'comment_id');
  END IF;
  RETURN NULL;
END $$;


--
-- Name: a_filings_shared_line(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_filings_shared_line(p_kind text, p_title text, p_body text, p_spoiler text, p_film text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT private.a_card_cut(CASE
    WHEN nullif(btrim(coalesce(p_title, '')), '') IS NOT NULL THEN p_title
    WHEN p_spoiler IS NULL AND nullif(btrim(coalesce(p_body, '')), '') IS NOT NULL THEN p_body
    ELSE CASE lower(p_kind) WHEN 'take' THEN 'TAKE' WHEN 'seeking' THEN 'SEEKING' WHEN 'wire' THEN 'WIRE'
                            WHEN 'ballot' THEN 'BALLOT' WHEN 'dossier' THEN 'ESSAY' ELSE upper(p_kind) END
         || coalesce(' on ' || nullif(btrim(coalesce(p_film, '')), ''), '')
         || CASE WHEN p_spoiler IS NOT NULL THEN ' · SPOILERS' ELSE '' END
  END)
$$;


--
-- Name: a_follow_takes_its_notice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_follow_takes_its_notice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Its notice was written with these keys (notify_on_interaction): to the one followed, from the
  -- follower, saying they follow.
  DELETE FROM public.notifications
   WHERE user_id = OLD.target_user_id
     AND from_user_id = OLD.user_id
     AND type = 'follow';
  RETURN NULL;
END $$;


--
-- Name: a_hidden_members_word_is_not_written(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_hidden_members_word_is_not_written() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- The pair is asked for directly, as dispatch_notify asks it: inside a trigger the session's
  -- viewer is the one acting, never the one told.
  IF NEW.from_user_id IS NOT NULL
     AND NEW.from_user_id IS DISTINCT FROM NEW.user_id
     AND NEW.type NOT IN ('moderation', 'featured')
     AND EXISTS (SELECT 1 FROM public.user_blocks b
                  WHERE (b.blocker_id = NEW.user_id AND b.blocked_id = NEW.from_user_id)
                     OR (b.blocker_id = NEW.from_user_id AND b.blocked_id = NEW.user_id AND b.type = 'block'))
  THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: a_members_call_is_paced(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_members_call_is_paced(p_member uuid, p_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now      timestamptz := now();
  v_day      date := (now() AT TIME ZONE 'UTC')::date;
  v_room     real;
  v_every    real;
  v_ceiling  integer;
  v_tokens   real;
  v_count    integer;
  v_midnight integer := ceil(extract(epoch FROM ((v_day + 1)::timestamp AT TIME ZONE 'UTC') - v_now))::integer;
BEGIN
  IF p_member IS NULL THEN
    RAISE EXCEPTION 'a_members_call_is_paced: no member' USING ERRCODE = '22004';
  END IF;
  IF p_kind = 'store_read' THEN
    v_room := 10; v_every := 30; v_ceiling := 200;
  ELSE
    RAISE EXCEPTION 'a_members_call_is_paced: no such kind' USING ERRCODE = '22023', DETAIL = coalesce(p_kind, '');
  END IF;

  SELECT s.tokens, s.n INTO v_tokens, v_count FROM private.a_members_room_is_spent(p_member, p_kind, v_room, v_every) AS s;

  IF v_tokens < 0 THEN
    -- The refill's seconds for each call short of one.
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'member',
      HINT = GREATEST(1, ceil(-v_tokens * v_every))::integer::text;
  END IF;
  IF v_count > v_ceiling THEN
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'day',
      HINT = GREATEST(1, v_midnight)::text;
  END IF;
END $$;


--
-- Name: a_new_row_is_dated(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_new_row_is_dated() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row jsonb := to_jsonb(NEW);
  v_at  timestamptz := now();
  v_set jsonb := '{}'::jsonb;
BEGIN
  -- The house's own writes keep their dates: only a member's or a visitor's request runs as these roles.
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  -- 'not_after': a date in the past is kept (an imported archive's), one after now is now.
  IF TG_ARGV[0] = 'not_after' AND NEW.created_at IS NOT NULL THEN
    v_at := LEAST(NEW.created_at, v_at);
  END IF;
  v_set := jsonb_build_object('created_at', v_at);
  IF v_row ? 'updated_at' THEN v_set := v_set || jsonb_build_object('updated_at', v_at); END IF;
  IF v_row ? 'edited_at' THEN v_set := v_set || jsonb_build_object('edited_at', NULL); END IF;
  IF v_row ? 'withheld_at' THEN v_set := v_set || jsonb_build_object('withheld_at', NULL); END IF;
  IF v_row ? 'ended_at' THEN v_set := v_set || jsonb_build_object('ended_at', NULL); END IF;
  IF v_row ? 'deleted_at' THEN v_set := v_set || jsonb_build_object('deleted_at', NULL); END IF;
  NEW := jsonb_populate_record(NEW, v_set);
  RETURN NEW;
END $$;


--
-- Name: a_notice_gone_is_told(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_notice_gone_is_told() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  r record;
BEGIN
  -- One word per member a statement touched, holding the ids of their notices that went. A member
  -- whose account went with them has no phone to tell.
  FOR r IN SELECT g.user_id, jsonb_agg(g.id) AS ids
             FROM gone g
            WHERE EXISTS (SELECT 1 FROM auth.users u WHERE u.id = g.user_id)
            GROUP BY g.user_id
  LOOP
    PERFORM realtime.send(jsonb_build_object('ids', r.ids), 'notices_gone', 'notices:' || r.user_id::text, true);
  END LOOP;
  RETURN NULL;
END $$;


--
-- Name: a_rank_is_counted(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_rank_is_counted(p_event text, p_rank text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  INSERT INTO public.gate_metrics AS m (day, event, feature_id, rank, standing, count)
  VALUES (current_date, p_event, '', coalesce(p_rank, ''), '', 1)
  ON CONFLICT (day, event, feature_id, rank, standing)
  DO UPDATE SET count = m.count + 1;
$$;


--
-- Name: a_reaction_is_in_its_message_salon(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_reaction_is_in_its_message_salon() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.lounge_messages m
                  WHERE m.id = NEW.message_id AND m.lounge_id = NEW.lounge_id) THEN
    RAISE EXCEPTION 'A reaction belongs to its message''s salon.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: a_reply_quotes_its_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_reply_quotes_its_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  q public.lounge_messages%ROWTYPE;
BEGIN
  IF NEW.reply_to_id IS NULL THEN
    NEW.reply_to_content := NULL;
    NEW.reply_to_username := NULL;
  ELSE
    SELECT * INTO q FROM public.lounge_messages WHERE id = NEW.reply_to_id;
    IF NOT FOUND OR q.lounge_id IS DISTINCT FROM NEW.lounge_id THEN
      RAISE EXCEPTION 'A reply answers a message of its own salon.' USING ERRCODE = '42501';
    END IF;
    NEW.reply_to_content := CASE WHEN q.deleted_at IS NULL THEN q.content END;
    NEW.reply_to_username := CASE WHEN q.user_id IS NULL THEN '[deleted]'
                                  ELSE (SELECT p.username FROM public.profiles p WHERE p.id = q.user_id) END;
  END IF;
  -- Whose words it carries besides its writer's, named by the house: the hiding rule reads it.
  NEW.carries_words_of := public.whose_words_a_message_carries(NEW.user_id, NEW.type, NEW.metadata, NEW.reply_to_id);
  RETURN NEW;
END $$;


--
-- Name: a_request_takes_its_notice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_request_takes_its_notice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  DELETE FROM public.notifications
   WHERE user_id = OLD.target_user_id
     AND type = 'follow_request'
     AND from_user_id = OLD.user_id;
  RETURN NULL;
END;
$$;


--
-- Name: a_row_keeps_what_it_is(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_row_keeps_what_it_is() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  kept jsonb := '{}'::jsonb;
  was  jsonb := to_jsonb(OLD);
  col  text;
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  FOREACH col IN ARRAY TG_ARGV LOOP
    kept := kept || jsonb_build_object(col, was -> col);
  END LOOP;
  RETURN jsonb_populate_record(NEW, kept);
END $$;


--
-- Name: a_salon_request_takes_its_notice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_salon_request_takes_its_notice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Asked again while still pending (the status written over with itself): the request stands.
  IF TG_OP = 'UPDATE' AND NEW.status = 'pending' THEN
    RETURN NULL;
  END IF;
  -- The request's notice: about this salon, from the one who asked, to someone else (the host).
  DELETE FROM public.notifications
   WHERE type IN ('salon', 'system')
     AND related_lounge_id = OLD.lounge_id
     AND from_user_id = OLD.user_id
     AND user_id IS DISTINCT FROM OLD.user_id;
  RETURN NULL;
END $$;


--
-- Name: a_sealed_stack_is_not_shared(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_sealed_stack_is_not_shared() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_named   text := NEW.metadata ->> 'listId';
  v_private boolean;
BEGIN
  -- A card that names no stack shows none: nothing to keep.
  IF NEW.type IS DISTINCT FROM 'list_share' OR v_named IS NULL THEN
    RETURN NEW;
  END IF;
  -- Read as the house, whoever shares: the sharer may not be the curator, and a sealed stack is
  -- refused to every sharer, its curator included.
  SELECT coalesce(l.is_private, false) INTO v_private
    FROM public.lists l
   WHERE v_named ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND l.id = v_named::uuid
     FOR SHARE OF l;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'STACK_GONE' USING ERRCODE = 'P0002';
  END IF;
  IF v_private THEN
    RAISE EXCEPTION 'STACK_SEALED' USING ERRCODE = '42501',
      HINT = 'A sealed stack is read by its curator alone; it cannot be shown in a salon.';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: a_sealed_stack_takes_its_cards(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_sealed_stack_takes_its_cards() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_cards   uuid[];
  v_caption text;
BEGIN
  IF coalesce(NEW.is_private, false) = coalesce(OLD.is_private, false) THEN
    RETURN NULL;
  END IF;
  -- The house's own write, so a_keeps_what_it_is lets it (the sharer's message is not the curator's).
  -- Asked as containment, so the cards' own index (lounge_messages_card_names) finds them; a card
  -- already gone stays gone.
  IF coalesce(NEW.is_private, false) THEN
    -- Sealed: each card says only which stack; a caption the website wrote goes, marked so it comes back.
    WITH turned AS (
      UPDATE public.lounge_messages m
         SET metadata = jsonb_build_object('listId', NEW.id::text, 'sealed', true)
                        || CASE WHEN m.content <> '' AND (
                                  (m.metadata ? 'title' AND (m.content = m.metadata ->> 'title'
                                     OR left(m.content, char_length(m.metadata ->> 'title') + 3) = (m.metadata ->> 'title') || ' · '))
                                  OR m.content ~ ' · [0-9]+ films · by @[^ ]+$')
                                THEN '{"caption": true}'::jsonb ELSE '{}'::jsonb END,
             content = CASE WHEN m.content <> '' AND (
                                  (m.metadata ? 'title' AND (m.content = m.metadata ->> 'title'
                                     OR left(m.content, char_length(m.metadata ->> 'title') + 3) = (m.metadata ->> 'title') || ' · '))
                                  OR m.content ~ ' · [0-9]+ films · by @[^ ]+$')
                            THEN '' ELSE m.content END
       WHERE m.type = 'list_share'
         AND m.metadata <> '{}'::jsonb
         AND m.metadata @> jsonb_build_object('listId', NEW.id::text)
         AND NOT (m.metadata @> '{"gone": true}'::jsonb)
         AND NOT (m.metadata @> '{"sealed": true}'::jsonb)
      RETURNING m.id, m.metadata
    )
    SELECT array_agg(id) INTO v_cards FROM turned WHERE metadata @> '{"caption": true}'::jsonb;
    -- The replies that quote a caption taken: the quote goes with it, as a withdrawn message's does.
    IF v_cards IS NOT NULL THEN
      UPDATE public.lounge_messages r SET reply_to_content = NULL
       WHERE r.reply_to_id = ANY (v_cards) AND r.reply_to_content IS NOT NULL;
    END IF;
  ELSE
    -- Opened again: each sealed card made again from the stack as it stands now, as the phone makes
    -- one (its title, its count of reels, its curator, its first four posters in the stack's order),
    -- and a caption written back where there was one, as the website writes it.
    v_caption := NEW.title || ' · ' || (SELECT count(*) FROM public.list_items i WHERE i.list_id = NEW.id) || ' films'
                 || coalesce(' · by @' || (SELECT p.username FROM public.profiles p WHERE p.id = NEW.user_id), '');
    WITH turned AS (
      UPDATE public.lounge_messages m
         SET metadata = jsonb_build_object(
               'listId', NEW.id::text,
               'title', NEW.title,
               'filmCount', (SELECT count(*) FROM public.list_items i WHERE i.list_id = NEW.id),
               'curator', (SELECT p.username FROM public.profiles p WHERE p.id = NEW.user_id),
               'topPosters', coalesce((SELECT jsonb_agg(x.poster_path ORDER BY x.place)
                                         FROM (SELECT i.poster_path,
                                                      row_number() OVER (ORDER BY i.rank_position NULLS LAST, i.created_at, i.id) AS place
                                                 FROM public.list_items i
                                                WHERE i.list_id = NEW.id AND i.poster_path IS NOT NULL
                                                ORDER BY i.rank_position NULLS LAST, i.created_at, i.id
                                                LIMIT 4) x), '[]'::jsonb)),
             content = CASE WHEN m.metadata @> '{"caption": true}'::jsonb THEN v_caption ELSE m.content END
       WHERE m.type = 'list_share'
         AND m.metadata <> '{}'::jsonb
         AND m.metadata @> jsonb_build_object('listId', NEW.id::text, 'sealed', true)
      RETURNING m.id, m.content, m.deleted_at
    )
    SELECT array_agg(id) INTO v_cards FROM turned WHERE content = v_caption AND deleted_at IS NULL;
    -- The replies that quoted the caption have it back.
    IF v_cards IS NOT NULL THEN
      UPDATE public.lounge_messages r SET reply_to_content = v_caption
       WHERE r.reply_to_id = ANY (v_cards) AND r.reply_to_content IS NULL;
    END IF;
  END IF;
  RETURN NULL;
END $_$;


--
-- Name: a_shared_card_is_the_houses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_shared_card_is_the_houses() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- The kinds the apps send: words, or a card of a film, a person, a record, a stack or a filing.
  IF NEW.type IS NULL OR NEW.type NOT IN ('text', 'film_share', 'person_share', 'log_share', 'list_share', 'dossier_share') THEN
    RAISE EXCEPTION 'MESSAGE_KIND' USING ERRCODE = '22023',
      HINT = 'A salon message is words, or a card of a film, a person, a record, a stack or a filing.';
  END IF;
  IF NEW.type = 'text' THEN
    RETURN NEW;
  END IF;
  -- Run as the member writing (no SECURITY DEFINER): the piece is read under the house's read rules.
  RETURN private.a_shared_card(NEW, true);
END $$;


--
-- Name: a_spoiler_take_veils_its_cards(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_spoiler_take_veils_its_cards() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_line text := public.a_filings_shared_line(NEW.kind, NEW.title, NEW.body, NEW.spoiler_label,
                   CASE WHEN NEW.subject_kind = 'film' THEN NEW.subject_title END);
BEGIN
  -- The house's own write, so a_keeps_what_it_is lets it (the sharer's message is not the author's).
  -- Asked as containment, so the cards' own index (lounge_messages_card_names) finds them; a card
  -- already gone stays gone.
  UPDATE public.lounge_messages m
     SET film_title = v_line,
         metadata = CASE WHEN m.metadata ? 'title' THEN m.metadata || jsonb_build_object('title', v_line) ELSE m.metadata END
   WHERE m.type = 'dossier_share'
     AND m.metadata <> '{}'::jsonb
     AND m.metadata @> jsonb_build_object('dossier_id', NEW.id::text)
     AND NOT (m.metadata @> '{"gone": true}'::jsonb);
  RETURN NULL;
END $$;


--
-- Name: a_withdrawn_message_leaves_its_quotes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.a_withdrawn_message_leaves_its_quotes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR NEW.deleted_at IS NOT NULL THEN
    UPDATE public.lounge_messages SET reply_to_content = NULL
     WHERE reply_to_id = OLD.id AND reply_to_content IS NOT NULL;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: accept_follow_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_follow_request(requester_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_granted integer;
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501'; END IF;

  -- A request across a block admits no one: it is taken from the door instead. One can be
  -- waiting there only if it was made in the same moment as the block.
  IF public.a_block_stands_between(requester_id, v_me) THEN
    DELETE FROM public.interactions
     WHERE user_id = requester_id
       AND target_user_id = v_me
       AND type = 'follow_request';
    RETURN false;
  END IF;

  -- Convert follow_request → follow
  UPDATE public.interactions
     SET type = 'follow'
   WHERE user_id = requester_id
     AND target_user_id = v_me
     AND type = 'follow_request';
  GET DIAGNOSTICS v_granted = ROW_COUNT;
  -- No request at the door: withdrawn (or answered) meanwhile. No one is admitted.
  IF v_granted = 0 THEN RETURN false; END IF;

  -- the follow count trigger counts inserts and deletes; a granted request is an update, so it is counted here
  UPDATE public.profiles SET followers_count = COALESCE(followers_count, 0) + 1 WHERE id = v_me;
  UPDATE public.profiles SET following_count = COALESCE(following_count, 0) + 1 WHERE id = requester_id;

  INSERT INTO public.notifications (user_id, type, from_username, from_user_id, message)
  SELECT requester_id, 'follow_accept', p.username, v_me, 'accepted your follow request. You can now view their archive.'
    FROM public.profiles p WHERE p.id = v_me;
  RETURN true;
END;
$$;


--
-- Name: analytics_events_daily_ceiling(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_events_daily_ceiling() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me  uuid := auth.uid();
  v_day date := (now() AT TIME ZONE 'UTC')::date;
  v_n   integer;
BEGIN
  -- The house's own writes are not counted: a member's request always carries the member.
  IF v_me IS NULL THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.analytics_budget AS b (user_id, day, n)
  VALUES (v_me, v_day, 1)
  ON CONFLICT (user_id) DO UPDATE SET
    day = v_day,
    n   = (CASE WHEN b.day = v_day THEN b.n ELSE 0 END) + 1
  RETURNING n INTO v_n;
  IF v_n > 1000 THEN
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'day',
      HINT = GREATEST(1, ceil(extract(epoch FROM ((v_day + 1)::timestamp AT TIME ZONE 'UTC') - now())))::integer::text;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: approve_lounge_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_lounge_member(p_lounge_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_lname text; v_sanction text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF auth.uid() IS DISTINCT FROM (SELECT creator_id FROM public.lounges WHERE id = p_lounge_id) THEN
    RAISE EXCEPTION 'Only the host can admit members'; END IF;
  -- A banned member cannot be pending (request_lounge_membership refuses them),
  -- so the only sanction met here is a mute.
  SELECT status INTO v_sanction FROM public.lounge_sanctions WHERE lounge_id = p_lounge_id AND user_id = p_user_id;
  UPDATE public.lounge_members SET status = COALESCE(v_sanction, 'approved')
   WHERE lounge_id = p_lounge_id AND user_id = p_user_id AND status = 'pending';
  IF FOUND THEN
    SELECT name INTO v_lname FROM public.lounges WHERE id = p_lounge_id;
    INSERT INTO public.notifications (user_id, type, from_user_id, message, related_lounge_id)
    VALUES (p_user_id, 'salon', auth.uid(), 'You were admitted to ' || COALESCE(v_lname,'the lounge') || '.', p_lounge_id);
  END IF;
END $$;


--
-- Name: assign_list_item_position(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_list_item_position() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.rank_position IS NULL THEN
    SELECT COALESCE(MAX(li.rank_position) + 1, 0)
      INTO NEW.rank_position
      FROM public.list_items li
     WHERE li.list_id = NEW.list_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: audience_allows(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audience_allows(p_actor uuid, p_owner uuid, p_pref text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_owner IS NULL THEN TRUE
    WHEN auth.uid() = p_owner THEN TRUE
    WHEN public.a_block_stands_between(auth.uid(), p_owner) THEN FALSE
    WHEN NOT private.can_view_user_data(p_owner) THEN FALSE
    WHEN COALESCE(p_pref, 'everyone') = 'everyone' THEN TRUE
    WHEN COALESCE(p_pref, 'everyone') = 'nobody' THEN FALSE
    ELSE EXISTS (SELECT 1 FROM public.interactions
                 WHERE type = 'follow' AND user_id = auth.uid() AND target_user_id = p_owner)
  END;
$$;


--
-- Name: ballot_tally(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ballot_tally(p_post uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN EXISTS (
      SELECT 1 FROM public.dispatch_posts p
       WHERE p.id = p_post
         AND p.kind = 'ballot'
         AND p.is_published AND p.withheld_at IS NULL AND p.ended_at IS NULL
         AND NOT COALESCE(p.user_id = ANY ((SELECT private.hidden_authors())::uuid[]), false)
         -- Voted in, or closed: until then the result is not the reader's to see.
         AND (p.closes_at <= now()
              OR EXISTS (SELECT 1 FROM public.dispatch_votes v
                          WHERE v.post_id = p.id AND v.user_id = auth.uid())))
    THEN (
      -- sum(t.n), not count(*): `t` is one row per option, as freeze_closed_ballots counts.
      SELECT jsonb_build_object(
               'total', COALESCE(sum(t.n), 0),
               'counts', COALESCE(jsonb_object_agg(t.option_index, t.n)
                                  FILTER (WHERE t.option_index IS NOT NULL), '{}'::jsonb))
        -- Each option's votes as counted when they were cast (private.ballot_counts): never the
        -- ballot's every vote read again.
        FROM (SELECT c.option_index, c.n FROM private.ballot_counts c
               WHERE c.post_id = p_post AND c.n > 0) t)
  END
$$;


--
-- Name: bulk_dismiss_reports(uuid[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_dismiss_reports(p_report_ids uuid[], p_admin_id uuid, p_reason text DEFAULT 'Bulk dismissed'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
  v_count int;
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;

  WITH dismissed AS (
    UPDATE reports
       SET status = 'resolved', resolved_at = now(), resolved_by = v_admin_id, resolution_action = 'dismiss'
     WHERE id = ANY(p_report_ids) AND status = 'pending'
       -- A case about the moderator stays pending, for another moderator (a_judge_is_refused).
       AND private.a_judge_is_refused(v_admin_id, NULL, target_user_id) IS NULL
    RETURNING id, target_user_id, reporter_id
  ), recorded AS (
    INSERT INTO mod_actions (report_id, target_user_id, admin_id, action, reason)
    SELECT d.id, d.target_user_id, v_admin_id, 'dismiss', p_reason FROM dismissed d
    RETURNING report_id
  ), told AS (
    -- Each reporter told as a single dismissal tells them (resolve_moderation_report_v2).
    INSERT INTO notifications (user_id, type, title, body, message, metadata)
    SELECT d.reporter_id, 'moderation', 'Your Report Was Reviewed',
           'Thank you for looking after the house. Your report was reviewed, and the matter is settled.',
           'Thank you for looking after the house. Your report was reviewed, and the matter is settled.',
           jsonb_build_object('report_id', d.id, 'action', 'dismiss')
      FROM dismissed d
     WHERE d.reporter_id IS NOT NULL
  )
  SELECT count(*) INTO v_count FROM recorded;

  RETURN v_count;
END;
$$;


--
-- Name: calendar_days(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_days(p_user_id uuid) RETURNS TABLE(day date, films integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The grid's 364 days end on the member's today: the house's yesterday, today or tomorrow.
  -- Each viewing on its own day: a rewatch adds a night, it never moves the one before it.
  SELECT v.day, count(*)::integer
    FROM private.viewings_between(p_user_id, (now() AT TIME ZONE 'UTC')::date - 364, (now() AT TIME ZONE 'UTC')::date + 1) v
   GROUP BY v.day
   ORDER BY v.day DESC;
$$;


--
-- Name: can_annotate_list(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_annotate_list(p_actor uuid, p_list_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- A stack the house withholds takes no critique meanwhile, from anyone (H-B10).
  SELECT NOT (COALESCE(l.is_private, false) AND l.user_id IS DISTINCT FROM auth.uid())
     AND l.withheld_at IS NULL
     AND public.audience_allows(p_actor, l.user_id,
           (SELECT preferences->>'privacy_annotations' FROM public.profiles WHERE id = l.user_id))
  FROM public.lists l WHERE l.id = p_list_id;
$$;


--
-- Name: can_annotate_log(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_annotate_log(p_actor uuid, p_log_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- A log the house withholds takes no critique meanwhile, from anyone (H-B10).
  SELECT l.withheld_at IS NULL AND public.audience_allows(p_actor, l.user_id,
    (SELECT preferences->>'privacy_annotations' FROM public.profiles WHERE id = l.user_id))
  FROM public.logs l WHERE l.id = p_log_id;
$$;


--
-- Name: can_endorse_content(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_endorse_content(p_actor uuid, p_type text, p_log_id uuid, p_list_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_owner uuid; v_pref text; v_private boolean := false; v_withheld boolean := false;
BEGIN
  IF p_type = 'endorse_log' THEN
    SELECT user_id, withheld_at IS NOT NULL INTO v_owner, v_withheld FROM public.logs WHERE id = p_log_id;
  ELSIF p_type = 'endorse_list' THEN
    SELECT user_id, COALESCE(is_private, false), withheld_at IS NOT NULL INTO v_owner, v_private, v_withheld FROM public.lists WHERE id = p_list_id;
  ELSE
    RETURN TRUE;
  END IF;
  -- A piece the house withholds takes no mark meanwhile, from anyone (H-B10).
  IF v_withheld THEN
    RETURN FALSE;
  END IF;
  IF v_private AND v_owner IS DISTINCT FROM auth.uid() THEN
    RETURN FALSE;
  END IF;
  SELECT preferences->>'privacy_endorsements' INTO v_pref FROM public.profiles WHERE id = v_owner;
  RETURN public.audience_allows(p_actor, v_owner, v_pref);
END;
$$;


