$$;


--
-- Name: FUNCTION can_view_user_data(target_uid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_view_user_data(target_uid uuid) IS 'private.can_view_user_data(), for the house''s own functions that call it by this name. No member or visitor may call it: the API would serve it.';


--
-- Name: check_critique_pace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_critique_pace() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now      timestamptz := now();
  v_day      date := (now() AT TIME ZONE 'UTC')::date;
  v_target   text;
  v_again    boolean;
  v_tokens   real;
  v_count    integer;
  v_swept    timestamptz;
  v_n        integer;
  v_since    timestamptz;
  v_midnight integer := ceil(extract(epoch FROM ((v_day + 1)::timestamp AT TIME ZONE 'UTC') - v_now))::integer;
BEGIN
  -- The house's own writes are not paced: a member's request always carries the member.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  -- The piece critiqued, and whether this critique is already filed (sent again, its answer lost).
  IF TG_TABLE_NAME = 'log_comments' THEN
    v_target := 'critique:log:' || NEW.log_id::text;
    v_again := EXISTS (SELECT 1 FROM public.log_comments WHERE id = NEW.id);
  ELSIF TG_TABLE_NAME = 'list_comments' THEN
    v_target := 'critique:list:' || NEW.list_id::text;
    v_again := EXISTS (SELECT 1 FROM public.list_comments WHERE id = NEW.id);
  ELSIF TG_TABLE_NAME = 'dispatch_comments' THEN
    v_target := 'critique:post:' || NEW.post_id::text;
    v_again := EXISTS (SELECT 1 FROM public.dispatch_comments WHERE id = NEW.id);
  ELSE
    RETURN NEW;
  END IF;
  IF v_again THEN
    RETURN NEW;
  END IF;

  -- The member's room to critique, refilled for the time since, less this critique; and the day's
  -- count. One row, one statement: a member's critiques at the same moment wait on each other here.
  INSERT INTO public.critique_budget AS b (user_id, tokens, refilled_at, day, n, swept_at)
  VALUES (NEW.user_id, 29, v_now, v_day, 1, v_now)
  ON CONFLICT (user_id) DO UPDATE SET
    tokens      = LEAST(30, b.tokens + GREATEST(0, extract(epoch FROM v_now - b.refilled_at))::real / 20) - 1,
    refilled_at = GREATEST(b.refilled_at, v_now),
    day         = v_day,
    n           = (CASE WHEN b.day = v_day THEN b.n ELSE 0 END) + 1,
    swept_at    = CASE WHEN b.swept_at <= v_now - interval '1 hour' THEN v_now ELSE b.swept_at END
  RETURNING tokens, n, swept_at INTO v_tokens, v_count, v_swept;

  IF v_tokens < 0 THEN
    -- Twenty seconds for each critique short of one.
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'member',
      HINT = GREATEST(1, ceil(-v_tokens * 20))::integer::text;
  END IF;
  IF v_count > 500 THEN
    -- The day's own word, so a ceiling met a minute before midnight is never told as a pace.
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'day',
      HINT = GREATEST(1, v_midnight)::text;
  END IF;

  -- Once an hour, by their next critique, the member's critiques of pieces over an hour ago are let go.
  IF v_swept = v_now THEN
    DELETE FROM public.interaction_churn
     WHERE user_id = NEW.user_id AND target LIKE 'critique:%' AND since <= v_now - interval '1 hour';
  END IF;
  INSERT INTO public.interaction_churn AS c (user_id, target, since, n)
  VALUES (NEW.user_id, v_target, v_now, 1)
  ON CONFLICT (user_id, target) DO UPDATE SET
    since = CASE WHEN c.since <= v_now - interval '1 hour' THEN v_now ELSE c.since END,
    n     = CASE WHEN c.since <= v_now - interval '1 hour' THEN 1 ELSE c.n + 1 END
  RETURNING n, since INTO v_n, v_since;
  IF v_n > 20 THEN
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'target',
      HINT = GREATEST(1, ceil(extract(epoch FROM v_since + interval '1 hour' - v_now)))::integer::text;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: check_interaction_rate_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_interaction_rate_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now      timestamptz := now();
  v_day      date := (now() AT TIME ZONE 'UTC')::date;
  v_follow   boolean := NEW.type IN ('follow', 'follow_request');
  v_cert     boolean := NEW.type IN ('endorse_log', 'endorse_list');
  v_target   text := CASE
                       WHEN NEW.type IN ('follow', 'follow_request') THEN 'member:' || NEW.target_user_id::text
                       WHEN NEW.type = 'endorse_log' THEN 'log:' || NEW.target_log_id::text
                       WHEN NEW.type = 'endorse_list' THEN 'list:' || NEW.target_list_id::text
                     END;
  v_tokens   real;
  v_follows  integer;
  v_certs    integer;
  v_swept    timestamptz;
  v_n        integer;
  v_since    timestamptz;
  v_midnight integer := ceil(extract(epoch FROM ((v_day + 1)::timestamp AT TIME ZONE 'UTC') - v_now))::integer;
BEGIN
  -- The house's own writes are not paced: a member's request always carries the member.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  -- The member's room to act, refilled for the time since, less this act; and the day's counts.
  -- One row, one statement: a member's acts at the same moment wait on each other here.
  INSERT INTO public.interaction_budget AS b (user_id, tokens, refilled_at, day, follows, certs, swept_at)
  VALUES (NEW.user_id, 119, v_now, v_day, v_follow::integer, v_cert::integer, v_now)
  ON CONFLICT (user_id) DO UPDATE SET
    tokens      = LEAST(120, b.tokens + GREATEST(0, extract(epoch FROM v_now - b.refilled_at))::real / 2) - 1,
    refilled_at = GREATEST(b.refilled_at, v_now),
    day         = v_day,
    follows     = (CASE WHEN b.day = v_day THEN b.follows ELSE 0 END) + v_follow::integer,
    certs       = (CASE WHEN b.day = v_day THEN b.certs ELSE 0 END) + v_cert::integer,
    swept_at    = CASE WHEN b.swept_at <= v_now - interval '1 hour' THEN v_now ELSE b.swept_at END
  RETURNING tokens, follows, certs, swept_at INTO v_tokens, v_follows, v_certs, v_swept;

  IF v_tokens < 0 THEN
    -- Two seconds for each act short of one.
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'member',
      HINT = GREATEST(1, ceil(-v_tokens * 2))::integer::text;
  END IF;
  IF v_follows > 400 OR v_certs > 3000 THEN
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'member',
      HINT = GREATEST(1, v_midnight)::text;
  END IF;

  IF v_target IS NOT NULL THEN
    -- Once an hour, by their next act, the member's acts at things over an hour ago are let go.
    IF v_swept = v_now THEN
      DELETE FROM public.interaction_churn
       WHERE user_id = NEW.user_id AND since <= v_now - interval '1 hour';
    END IF;
    INSERT INTO public.interaction_churn AS c (user_id, target, since, n)
    VALUES (NEW.user_id, v_target, v_now, 1)
    ON CONFLICT (user_id, target) DO UPDATE SET
      since = CASE WHEN c.since <= v_now - interval '1 hour' THEN v_now ELSE c.since END,
      n     = CASE WHEN c.since <= v_now - interval '1 hour' THEN 1 ELSE c.n + 1 END
    RETURNING n, since INTO v_n, v_since;
    IF v_n > (CASE WHEN v_follow THEN 3 ELSE 5 END) THEN
      RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'target',
        HINT = GREATEST(1, ceil(extract(epoch FROM v_since + interval '1 hour' - v_now)))::integer::text;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: check_write_pace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_write_pace() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_now      timestamptz := now();
  v_day      date := (now() AT TIME ZONE 'UTC')::date;
  v_kind     text;
  v_room     real;
  v_every    real;
  v_ceiling  integer;
  v_member   uuid;
  v_again    boolean;
  v_tokens   real;
  v_count    integer;
  v_midnight integer := ceil(extract(epoch FROM ((v_day + 1)::timestamp AT TIME ZONE 'UTC') - v_now))::integer;
BEGIN
  -- The house's own writes are not paced: a member's request always carries the member.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  -- The kind, its room, the seconds for one more, its day's ceiling, and whether this row is already there.
  IF TG_TABLE_NAME = 'logs' THEN
    v_kind := 'record'; v_room := 50000; v_every := 0.1; v_ceiling := 100000;
    v_again := EXISTS (SELECT 1 FROM public.logs WHERE user_id = NEW.user_id AND film_id = NEW.film_id);
  ELSIF TG_TABLE_NAME = 'lists' THEN
    v_kind := 'stack'; v_room := 500; v_every := 10; v_ceiling := 2000;
    v_again := EXISTS (SELECT 1 FROM public.lists WHERE id = NEW.id);
  ELSIF TG_TABLE_NAME = 'list_items' THEN
    v_kind := 'stack_entry'; v_room := 20000; v_every := 0.1; v_ceiling := 100000;
    v_again := EXISTS (SELECT 1 FROM public.list_items WHERE list_id = NEW.list_id AND film_id = NEW.film_id);
  ELSIF TG_TABLE_NAME = 'dispatch_posts' THEN
    v_kind := 'filing'; v_room := 10; v_every := 360; v_ceiling := 50;
    v_again := EXISTS (SELECT 1 FROM public.dispatch_posts WHERE id = NEW.id);
  ELSIF TG_TABLE_NAME = 'lounges' THEN
    v_kind := 'salon'; v_room := 5; v_every := 3600; v_ceiling := 20;
    v_again := EXISTS (SELECT 1 FROM public.lounges WHERE id = NEW.id);
  ELSIF TG_TABLE_NAME = 'lounge_message_reactions' THEN
    v_kind := 'reaction'; v_room := 120; v_every := 2; v_ceiling := 2000;
    v_again := EXISTS (SELECT 1 FROM public.lounge_message_reactions
                        WHERE message_id = NEW.message_id AND user_id = NEW.user_id AND reaction = NEW.reaction);
  ELSIF TG_TABLE_NAME = 'dispatch_certifications' THEN
    v_kind := 'certification'; v_room := 120; v_every := 2; v_ceiling := 2000;
    v_again := EXISTS (SELECT 1 FROM public.dispatch_certifications WHERE id = NEW.id);
  ELSIF TG_TABLE_NAME = 'dispatch_saves' THEN
    v_kind := 'save'; v_room := 300; v_every := 1; v_ceiling := 3000;
    v_again := EXISTS (SELECT 1 FROM public.dispatch_saves WHERE user_id = NEW.user_id AND post_id = NEW.post_id);
  ELSIF TG_TABLE_NAME = 'dispatch_votes' THEN
    v_kind := 'vote'; v_room := 120; v_every := 1; v_ceiling := 2000;
    v_again := EXISTS (SELECT 1 FROM public.dispatch_votes WHERE post_id = NEW.post_id AND user_id = NEW.user_id);
  ELSIF TG_TABLE_NAME = 'user_blocks' THEN
    v_kind := 'block'; v_room := 100; v_every := 1; v_ceiling := 1000;
    v_again := EXISTS (SELECT 1 FROM public.user_blocks WHERE blocker_id = NEW.blocker_id AND blocked_id = NEW.blocked_id);
  ELSIF TG_TABLE_NAME = 'watchlists' THEN
    v_kind := 'watchlist_entry'; v_room := 20000; v_every := 0.1; v_ceiling := 100000;
    v_again := EXISTS (SELECT 1 FROM public.watchlists WHERE user_id = NEW.user_id AND film_id = NEW.film_id);
  ELSIF TG_TABLE_NAME = 'physical_archive' THEN
    v_kind := 'shelf_entry'; v_room := 2000; v_every := 0.5; v_ceiling := 10000;
    v_again := EXISTS (SELECT 1 FROM public.physical_archive WHERE user_id = NEW.user_id AND film_id = NEW.film_id);
  ELSIF TG_TABLE_NAME = 'member_drafts' THEN
    v_kind := 'draft'; v_room := 300; v_every := 1; v_ceiling := 5000;
    v_again := EXISTS (SELECT 1 FROM public.member_drafts WHERE user_id = NEW.user_id AND kind = NEW.kind AND scope = NEW.scope);
  ELSIF TG_TABLE_NAME = 'push_subscriptions' THEN
    v_kind := 'push_address'; v_room := 20; v_every := 60; v_ceiling := 100;
    v_again := EXISTS (SELECT 1 FROM public.push_subscriptions WHERE endpoint = NEW.endpoint);
  ELSIF TG_TABLE_NAME = 'lounge_members' THEN
    v_kind := 'seat'; v_room := 60; v_every := 10; v_ceiling := 500;
    v_again := EXISTS (SELECT 1 FROM public.lounge_members WHERE lounge_id = NEW.lounge_id AND user_id = NEW.user_id);
  ELSE
    RETURN NEW;
  END IF;
  IF v_again THEN
    RETURN NEW;
  END IF;

  -- The member whose room it is: the one asking (a row names its own member; a stack entry, a list).
  v_member := auth.uid();

  -- The room, refilled for the time since, less this write; and the day's count. One row, one
  -- statement: a member's writes of a kind at the same moment wait on each other here.
  SELECT s.tokens, s.n INTO v_tokens, v_count FROM private.a_members_room_is_spent(v_member, v_kind, v_room, v_every) AS s;

  IF v_tokens < 0 THEN
    -- The refill's seconds for each write short of one.
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'member',
      HINT = GREATEST(1, ceil(-v_tokens * v_every))::integer::text;
  END IF;
  IF v_count > v_ceiling THEN
    -- The day's own word, so a ceiling met a minute before midnight is never told as a pace.
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'day',
      HINT = GREATEST(1, v_midnight)::text;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: claim_films_to_sync(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_films_to_sync(p_limit integer DEFAULT 20) RETURNS TABLE(id integer, sync_reads smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
#variable_conflict use_column
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
  v_taken integer;
BEGIN
  -- The films nobody has read yet (or read before popularity was kept): first, as before.
  RETURN QUERY
  UPDATE public.films f
     SET sync_claimed_at = now()
   WHERE f.id IN (
     SELECT c.id
       FROM public.films c
      WHERE (c.synced_at IS NULL OR c.popularity IS NULL)
        AND c.sync_failed < 3
        AND (c.sync_claimed_at IS NULL OR c.sync_claimed_at < now() - interval '10 minutes')
      ORDER BY c.synced_at IS NOT NULL, c.id
      LIMIT v_limit
      FOR UPDATE SKIP LOCKED
   )
  RETURNING f.id, f.sync_reads;
  GET DIAGNOSTICS v_taken = ROW_COUNT;
  IF v_taken >= v_limit THEN
    RETURN;
  END IF;

  -- Then the films read too early, oldest due first: one whose reread_after has come, and one read
  -- before the house counted that may have been read too early. The condition is idx_films_reread's
  -- own, so the claim reads only the films it names. A film claimed above is held (claimed now).
  RETURN QUERY
  UPDATE public.films f
     SET sync_claimed_at = now()
   WHERE f.id IN (
     SELECT c.id
       FROM public.films c
      WHERE (c.reread_after IS NOT NULL
             OR (c.synced_at IS NOT NULL AND c.sync_reads IS NULL
                 AND (cardinality(c.genres) = 0 OR c.director_id IS NULL OR cardinality(c.cast_ids) = 0
                      OR c.year IS NULL OR c.year >= 2026)))
        AND c.sync_failed < 3
        AND COALESCE(c.reread_after, c.synced_at) <= now()
        AND (c.sync_claimed_at IS NULL OR c.sync_claimed_at < now() - interval '10 minutes')
      ORDER BY COALESCE(c.reread_after, c.synced_at), c.id
      LIMIT v_limit - v_taken
      FOR UPDATE SKIP LOCKED
   )
  RETURNING f.id, f.sync_reads;
END;
$$;


--
-- Name: claim_founding_seat(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_founding_seat(p_user_id uuid, p_max_seats integer DEFAULT 100) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_seats_claimed INTEGER;
  v_already_founding BOOLEAN;
BEGIN
  SELECT is_founding INTO v_already_founding
  FROM public.profiles WHERE id = p_user_id;

  IF v_already_founding THEN
    RETURN true;
  END IF;

  SELECT seats_claimed INTO v_seats_claimed
  FROM public.founding_seat_counter
  WHERE id = 1
  FOR UPDATE;

  IF v_seats_claimed >= p_max_seats THEN
    RETURN false;
  END IF;

  UPDATE public.founding_seat_counter
  SET seats_claimed = seats_claimed + 1
  WHERE id = 1;

  UPDATE public.profiles
  SET is_founding = true
  WHERE id = p_user_id;

  RETURN true;
END;
$$;


--
-- Name: clean_member_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clean_member_text(words text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  s text;
  chars text[];
  kept text[] := '{}';
  n integer;
  c integer;
  before integer;
  after integer;
BEGIN
  IF words IS NULL THEN
    RETURN NULL;
  END IF;

  -- A line and a paragraph separator are the breaks they are.
  s := replace(replace(words, chr(8232), E'\n'), chr(8233), E'\n\n');

  -- The invisible characters but the two joiners, then the control characters
  -- but newline, carriage return and tab.
  s := regexp_replace(s,
    '[' || chr(8203) || chr(8206) || chr(8207) || chr(8234) || '-' || chr(8238)
        || chr(65279) || chr(173) || chr(847) || chr(8288) || '-' || chr(8292)
        || chr(8294) || '-' || chr(8303)
        || chr(1) || '-' || chr(8) || chr(11) || chr(12) || chr(14) || '-' || chr(31) || chr(127)
    || ']', '', 'g');

  -- A joiner is kept between two letters of a joining script, and a zero-width
  -- joiner between the end of an emoji and the start of the next; elsewhere it
  -- joins nothing and goes.
  IF strpos(s, chr(8204)) > 0 OR strpos(s, chr(8205)) > 0 THEN
    chars := string_to_array(s, NULL);
    n := coalesce(array_length(chars, 1), 0);
    FOR i IN 1..n LOOP
      c := ascii(chars[i]);
      IF c = 8204 OR c = 8205 THEN
        after := CASE WHEN i < n THEN ascii(chars[i + 1]) END;
        IF NOT coalesce(
             ((before BETWEEN 1536 AND 3583 OR before BETWEEN 4096 AND 4255 OR before BETWEEN 6016 AND 6319
               OR before BETWEEN 64336 AND 65023 OR before BETWEEN 65136 AND 65276)
              AND (after BETWEEN 1536 AND 3583 OR after BETWEEN 4096 AND 4255 OR after BETWEEN 6016 AND 6319
               OR after BETWEEN 64336 AND 65023 OR after BETWEEN 65136 AND 65276))
             OR (c = 8205
                 AND (before >= 65536 OR before = 65039 OR before BETWEEN 8592 AND 11263)
                 AND (after >= 65536 OR after BETWEEN 8592 AND 11263)),
             false) THEN
          CONTINUE;
        END IF;
      END IF;
      kept := kept || chars[i];
      before := c;
    END LOOP;
    s := array_to_string(kept, '');
  END IF;

  s := regexp_replace(s, E'\n{4,}', E'\n\n\n', 'g');
  s := regexp_replace(s, E'[ \t]{10,}', '  ', 'g');

  -- The ends, as String.prototype.trim finds them.
  RETURN btrim(s, E' \t\n\r' || chr(11) || chr(12) || chr(160) || chr(5760)
    || chr(8192) || chr(8193) || chr(8194) || chr(8195) || chr(8196) || chr(8197)
    || chr(8198) || chr(8199) || chr(8200) || chr(8201) || chr(8202)
    || chr(8232) || chr(8233) || chr(8239) || chr(8287) || chr(12288) || chr(65279));
END;
$$;


--
-- Name: clean_member_words(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clean_member_words() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  fields  jsonb := to_jsonb(NEW);
  patch   jsonb := '{}';
  arg     text;
  col     text;
  key     text;
  v       jsonb;
  cleaned jsonb;
BEGIN
  FOREACH arg IN ARRAY TG_ARGV LOOP
    col := split_part(arg, '.', 1);
    key := nullif(split_part(arg, '.', 2), '');
    v := coalesce(patch -> col, fields -> col);
    IF key IS NULL AND jsonb_typeof(v) = 'string' THEN
      cleaned := to_jsonb(public.clean_member_text(v #>> '{}'));
    ELSIF key IS NOT NULL AND jsonb_typeof(v) = 'array' THEN
      SELECT coalesce(jsonb_agg(
               CASE WHEN jsonb_typeof(e -> key) = 'string'
                    THEN jsonb_set(e, ARRAY[key], to_jsonb(public.clean_member_text(e ->> key)))
                    ELSE e END ORDER BY n), '[]'::jsonb)
        INTO cleaned
        FROM jsonb_array_elements(v) WITH ORDINALITY AS a(e, n);
    ELSE
      CONTINUE;
    END IF;
    IF cleaned IS DISTINCT FROM v THEN
      patch := patch || jsonb_build_object(col, cleaned);
    END IF;
  END LOOP;

  IF patch <> '{}'::jsonb THEN
    NEW := jsonb_populate_record(NEW, patch);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: create_lounge(text, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_lounge(p_name text, p_description text, p_is_private boolean, p_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid; v_uid uuid := auth.uid(); v_founder uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  -- Asked again with the id its form made (the first answer lost): the room it founded is the
  -- answer, before any gate can judge a second founding.
  IF p_id IS NOT NULL THEN
    SELECT creator_id INTO v_founder FROM public.lounges WHERE id = p_id;
    IF FOUND THEN
      IF v_founder IS DISTINCT FROM v_uid THEN
        RAISE EXCEPTION 'That room is another member''s.' USING ERRCODE = '42501';
      END IF;
      RETURN p_id;
    END IF;
  END IF;
  -- `invite_code` is deliberately NOT set. A room is entered by asking at the
  -- door and being admitted; a code would be a way around the door, and the
  -- table it would live in is readable by every member.
  INSERT INTO public.lounges (id, name, description, is_private, creator_id, member_count)
  VALUES (coalesce(p_id, gen_random_uuid()), p_name, p_description, COALESCE(p_is_private, false), v_uid, 0)
  ON CONFLICT (id) DO NOTHING
  RETURNING id INTO v_id;
  -- Two asks at once with one id: the first founded the room, and this one answers with it.
  IF v_id IS NULL THEN
    SELECT creator_id INTO v_founder FROM public.lounges WHERE id = p_id;
    IF v_founder IS DISTINCT FROM v_uid THEN
      RAISE EXCEPTION 'That room is another member''s.' USING ERRCODE = '42501';
    END IF;
    RETURN p_id;
  END IF;
  INSERT INTO public.lounge_members (lounge_id, user_id, status) VALUES (v_id, v_uid, 'approved');
  RETURN v_id;
END $$;


--
-- Name: logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.logs (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    film_id integer NOT NULL,
    film_title text NOT NULL,
    rating numeric,
    review text,
    watched_date date NOT NULL,
    format text,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    poster_path text,
    year text,
    status text DEFAULT 'watched'::text,
    is_spoiler boolean DEFAULT false,
    watched_with text,
    private_notes text,
    abandoned_reason text,
    physical_media text,
    is_autopsied boolean DEFAULT false,
    autopsy jsonb,
    alt_poster text,
    editorial_header text,
    drop_cap boolean DEFAULT false,
    pull_quote text,
    updated_at timestamp with time zone DEFAULT now(),
    video_url text,
    viewing_history jsonb DEFAULT '[]'::jsonb,
    view_count integer DEFAULT 1,
    viewing_id uuid DEFAULT gen_random_uuid() NOT NULL,
    withheld_at timestamp with time zone,
    CONSTRAINT check_rating_range CHECK (((rating >= (0)::numeric) AND (rating <= (5)::numeric))),
    CONSTRAINT check_title_not_empty CHECK (((film_title IS NOT NULL) AND (film_title <> ''::text))),
    CONSTRAINT logs_abandoned_reason_len CHECK ((char_length(abandoned_reason) <= 500)),
    CONSTRAINT logs_alt_poster_len CHECK ((char_length(alt_poster) <= 2048)),
    CONSTRAINT logs_autopsy_len CHECK ((char_length((autopsy)::text) <= 20000)),
    CONSTRAINT logs_editorial_header_len CHECK ((char_length(editorial_header) <= 2048)),
    CONSTRAINT logs_film_title_len CHECK ((char_length(film_title) <= 300)),
    CONSTRAINT logs_format_len CHECK ((char_length(format) <= 100)),
    CONSTRAINT logs_physical_media_len CHECK ((char_length(physical_media) <= 100)),
    CONSTRAINT logs_poster_path_len CHECK ((char_length(poster_path) <= 2048)),
    CONSTRAINT logs_private_notes_len CHECK ((char_length(private_notes) <= 1000)),
    CONSTRAINT logs_pull_quote_len CHECK ((char_length(pull_quote) <= 500)),
    CONSTRAINT logs_rating_check CHECK (((rating >= (0)::numeric) AND (rating <= (5)::numeric))),
    CONSTRAINT logs_review_len CHECK ((char_length(review) <= 5000)),
    CONSTRAINT logs_status_len CHECK ((char_length(status) <= 100)),
    CONSTRAINT logs_video_url_len CHECK ((char_length(video_url) <= 2048)),
    CONSTRAINT logs_viewing_history_len CHECK ((char_length((viewing_history)::text) <= 500000)),
    CONSTRAINT logs_watched_with_len CHECK ((char_length(watched_with) <= 200)),
    CONSTRAINT logs_year_len CHECK ((char_length(year) <= 20))
);


--
-- Name: COLUMN logs.withheld_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.logs.withheld_at IS 'Withheld by the house (a REMOVE CONTENT awaiting its appeal, withheld_pieces): read by its author alone until deleted or given back. Written by the house alone.';


--
-- Name: critiques_seen(public.logs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.critiques_seen(l public.logs) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH me AS (SELECT (SELECT private.hidden_authors()) AS hidden)
  SELECT CASE
    WHEN COALESCE(cardinality(me.hidden), 0) = 0
      THEN COALESCE((SELECT c.critique_count FROM public.log_counts c WHERE c.log_id = l.id), 0)
    ELSE (SELECT count(*)::integer FROM public.log_comments x
           WHERE x.log_id = l.id AND NOT COALESCE(x.user_id = ANY (me.hidden), false))
  END
  FROM me;
$$;


--
-- Name: decline_all_follow_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decline_all_follow_requests() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
BEGIN
  WITH deleted AS (
    DELETE FROM public.interactions
    WHERE target_user_id = auth.uid()
      AND type = 'follow_request'
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_count FROM deleted;
  RETURN COALESCE(v_count, 0);
END;
$$;


--
-- Name: decline_follow_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decline_follow_request(requester_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501'; END IF;
  DELETE FROM public.interactions
   WHERE user_id = requester_id
     AND target_user_id = auth.uid()
     AND type = 'follow_request';
END;
$$;


--
-- Name: decline_lounge_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decline_lounge_member(p_lounge_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  IF auth.uid() IS DISTINCT FROM (SELECT creator_id FROM public.lounges WHERE id = p_lounge_id) THEN
    RAISE EXCEPTION 'Only the host can decline requests'; END IF;
  DELETE FROM public.lounge_members WHERE lounge_id = p_lounge_id AND user_id = p_user_id AND status = 'pending';
END $$;


--
-- Name: delete_list_cascade(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_list_cascade(p_list_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_owner_id UUID;
BEGIN
  SELECT user_id INTO v_owner_id
  FROM lists
  WHERE id = p_list_id;

  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'List not found';
  END IF;

  IF v_owner_id != auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: you do not own this list';
  END IF;

  DELETE FROM list_items WHERE list_id = p_list_id;
  DELETE FROM list_comments WHERE list_id = p_list_id;
  DELETE FROM interactions WHERE target_list_id = p_list_id;
  DELETE FROM lists WHERE id = p_list_id;
END;
$$;


--
-- Name: delete_withheld_piece(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_withheld_piece(p_action_id uuid, p_due boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  w      public.withheld_pieces%ROWTYPE;
  v_rows integer := 0;
BEGIN
  SELECT * INTO w FROM public.withheld_pieces WHERE mod_action_id = p_action_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  -- Asked by the hourly job (p_due): its deadline asked again under the piece's lock, so an appeal filed
  -- since the job read it (file_appeal takes the deadline away) keeps it.
  IF p_due AND (w.delete_after IS NULL OR w.delete_after > now()) THEN
    RETURN false;
  END IF;
  -- Deleted as REMOVE CONTENT deleted it before; its counts left it out already (each counting trigger
  -- takes nothing off for a withheld row), and the notices set aside go with the register's row.
  CASE w.kind
    WHEN 'log'              THEN DELETE FROM public.logs              WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    WHEN 'list'             THEN DELETE FROM public.lists             WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    WHEN 'log_comment'      THEN DELETE FROM public.log_comments      WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    WHEN 'list_comment'     THEN DELETE FROM public.list_comments     WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    WHEN 'dispatch_comment' THEN DELETE FROM public.dispatch_comments WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    WHEN 'dispatch_post' THEN
      -- A filing is never deleted: ended by the house, its words emptied, as REMOVE CONTENT ended one.
      PERFORM public.dispatch_empty_filing(w.piece_id, 'house');
      UPDATE public.dispatch_posts SET withheld_at = NULL WHERE id = w.piece_id AND ended_at IS NOT NULL;
  END CASE;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  DELETE FROM public.withheld_pieces WHERE mod_action_id = p_action_id;
  RETURN v_rows > 0;
END;
$$;


--
-- Name: derive_author_username_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_author_username_column() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_handle text;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT username INTO v_handle FROM public.profiles WHERE id = NEW.user_id;
  IF v_handle IS NULL THEN
    RETURN NEW;
  END IF;
  NEW.author_username := v_handle;
  RETURN NEW;
END;
$$;


--
-- Name: derive_username_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.derive_username_column() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_handle text;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT username INTO v_handle FROM public.profiles WHERE id = NEW.user_id;
  IF v_handle IS NULL THEN
    RETURN NEW;
  END IF;
  NEW.username := v_handle;
  RETURN NEW;
END;
$$;


--
-- Name: dispatch_archive_films(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_archive_films(p_pattern text) RETURNS TABLE(subject_id integer, subject_title text, subject_sub text, subject_image text, filings bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH me AS (SELECT (SELECT private.hidden_authors()) AS hidden),
  hits AS (
    SELECT p.subject_id, p.subject_title, p.subject_sub, p.subject_image, p.created_at, p.id
      FROM public.dispatch_posts p CROSS JOIN me
     WHERE p.subject_kind = 'film'
       AND p.subject_id IS NOT NULL
       AND p.subject_title IS NOT NULL
       AND p.is_published
       AND p.withheld_at IS NULL
       AND p.ended_at IS NULL
       AND p.subject_title ILIKE '%' || COALESCE(p_pattern, '') || '%'
       AND NOT COALESCE(p.user_id = ANY (me.hidden), false)
  ),
  -- Each film once, its newest filing's poster and subtitle (an older one may carry a poster since replaced).
  films AS (
    SELECT DISTINCT ON (h.subject_id)
           h.subject_id, h.subject_title, h.subject_sub, h.subject_image,
           count(*) OVER (PARTITION BY h.subject_id) AS filings
      FROM hits h
     ORDER BY h.subject_id, h.created_at DESC, h.id DESC
  )
  SELECT f.subject_id, f.subject_title, f.subject_sub, f.subject_image, f.filings
    FROM films f
   ORDER BY f.filings DESC, f.subject_id
   LIMIT 120;
$$;


--
-- Name: dispatch_comments_pin_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_comments_pin_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  NEW.certify_count := OLD.certify_count;
  NEW.created_at    := OLD.created_at;
  -- Withheld by the house: only the house gives it back (H-B10).
  NEW.withheld_at   := OLD.withheld_at;
  -- A critique belongs to the filing it was written under. Moving it puts a
  -- member's words beneath somebody else's writing.
  NEW.post_id       := OLD.post_id;
  -- An edit is dated by the house's clock, never the phone's.
  IF NEW.edited_at IS DISTINCT FROM OLD.edited_at THEN
    NEW.edited_at := now();
  END IF;
  RETURN NEW;
END $$;


--
-- Name: dispatch_count_cert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_count_cert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.post_id IS NOT NULL THEN
      UPDATE public.dispatch_posts SET certify_count = certify_count + 1 WHERE id = NEW.post_id;
    ELSE
      UPDATE public.dispatch_comments SET certify_count = certify_count + 1 WHERE id = NEW.comment_id;
    END IF;
    RETURN NEW;
  ELSE
    IF OLD.post_id IS NOT NULL THEN
      UPDATE public.dispatch_posts
         SET certify_count = GREATEST(0, certify_count - 1) WHERE id = OLD.post_id;
    ELSE
      UPDATE public.dispatch_comments
         SET certify_count = GREATEST(0, certify_count - 1) WHERE id = OLD.comment_id;
    END IF;
    RETURN OLD;
  END IF;
END $$;


--
-- Name: dispatch_count_comment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_count_comment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.dispatch_posts SET comment_count = comment_count + 1 WHERE id = NEW.post_id;
    RETURN NEW;
  ELSE
    -- A critique the house withheld was taken off the count when it was withheld (H-B10).
    IF OLD.withheld_at IS NULL THEN
      UPDATE public.dispatch_posts
         SET comment_count = GREATEST(0, comment_count - 1) WHERE id = OLD.post_id;
    END IF;
    RETURN OLD;
  END IF;
END $$;


--
-- Name: dispatch_door(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_door() RETURNS TABLE(films integer, films_needed integer, days integer, days_needed integer, may_file boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT (SELECT count(DISTINCT film_id) FROM public.logs WHERE user_id = p.id)::int,
         5,
         GREATEST(0, floor(extract(epoch FROM now() - p.created_at) / 86400))::int,
         2,
         public.may_file()
    FROM public.profiles p WHERE p.id = auth.uid();
$$;


--
-- Name: dispatch_empty_filing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_empty_filing(p_post uuid, p_by text) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH ended AS (
    UPDATE public.dispatch_posts
       SET body = '', full_content = NULL, title = NULL,
           subject_image = NULL, subject_backdrop = NULL,
           source = NULL, source_url = NULL, spoiler_label = NULL,
           ended_at = now(), ended_by = p_by
     WHERE id = p_post AND ended_at IS NULL
    RETURNING id
  )
  UPDATE public.lounge_messages m
     SET film_title = NULL, film_poster = NULL,
         metadata = ((m.metadata - 'author_username') - 'title') || jsonb_build_object('gone', true)
    FROM ended
   WHERE m.type = 'dossier_share'
     AND m.metadata <> '{}'::jsonb
     AND m.metadata @> jsonb_build_object('dossier_id', ended.id::text);
$$;


--
-- Name: FUNCTION dispatch_empty_filing(p_post uuid, p_by text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dispatch_empty_filing(p_post uuid, p_by text) IS 'The one erase of a filing that ends, its cards in the salons with it. Called by end_filing and the no_hard_delete trigger (both SECURITY DEFINER); no role may call it directly.';


--
-- Name: dispatch_names(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_names(p_kind text, p_title text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT 'your '
      || CASE lower(btrim(coalesce(p_kind, '')))
           WHEN 'dossier' THEN 'essay'
           WHEN ''        THEN 'filing'
           ELSE lower(btrim(p_kind))
         END
      || CASE WHEN btrim(coalesce(p_title, '')) = '' THEN ''
              ELSE ' “' || btrim(p_title) || '”' END;
$$;


--
-- Name: dispatch_no_hard_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_no_hard_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF coalesce(current_setting('dispatch.allow_hard_delete', true), '') = 'on' THEN
    RETURN OLD;
  END IF;

  -- already ended: nothing to erase, and nothing to delete either
  IF OLD.ended_at IS NOT NULL THEN RETURN NULL; END IF;

  PERFORM public.dispatch_empty_filing(
    OLD.id,
    CASE WHEN OLD.user_id IS NOT DISTINCT FROM auth.uid() THEN 'author' ELSE 'house' END);

  RETURN NULL;   -- the delete does not happen
END $$;


--
-- Name: dispatch_notify(uuid, uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_notify(p_to uuid, p_from uuid, p_type text, p_message text, p_meta jsonb, p_group text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_to IS NULL OR p_from IS NULL OR p_to = p_from THEN RETURN; END IF;

  -- a block in either direction silences the notice. `is_hidden_by` reads the
  -- SESSION's viewer, which inside a trigger is the actor rather than the
  -- recipient, so the pair is asked for directly here.
  IF EXISTS (
    SELECT 1 FROM public.user_blocks
     WHERE (blocker_id = p_to AND blocked_id = p_from)
        OR (blocker_id = p_from AND blocked_id = p_to AND type = 'block')
  ) THEN RETURN; END IF;

  INSERT INTO public.notifications
    (user_id, from_user_id, from_username, type, message, metadata, group_key)
  SELECT p_to, p_from, pr.username, p_type, p_message, p_meta, p_group
    FROM public.profiles pr WHERE pr.id = p_from;
END $$;


--
-- Name: dispatch_notify_answer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_notify_answer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE c record;
BEGIN
  IF NEW.answer_id IS NOT DISTINCT FROM OLD.answer_id THEN
    RETURN NEW;
  END IF;
  -- The answer moved away (to another critique, or to none): its critic's notice goes with it. A
  -- notice written before the answer was marked is known by its words.
  IF OLD.answer_id IS NOT NULL THEN
    DELETE FROM public.notifications
     WHERE from_user_id = NEW.user_id
       AND type = 'comment'
       AND metadata ->> 'comment_id' = OLD.answer_id::text
       AND (metadata ? 'answer' OR message = 'took your critique as the answer.');
  END IF;
  IF NEW.answer_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT id, user_id INTO c FROM public.dispatch_comments WHERE id = NEW.answer_id;
  PERFORM public.dispatch_notify(
    c.user_id, NEW.user_id, 'comment',
    'took your critique as the answer.',
    jsonb_build_object('dispatch_post_id', NEW.id, 'kind', NEW.kind, 'comment_id', c.id, 'answer', true),
    'endorse:post:' || NEW.id);
  RETURN NEW;
END $$;


--
-- Name: dispatch_notify_ballot_closed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_notify_ballot_closed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.frozen_totals IS NULL OR OLD.frozen_totals IS NOT NULL THEN RETURN NEW; END IF;
  -- A ballot no voter can open (ended, withheld by the house, or unpublished) is told to no one.
  IF NEW.ended_at IS NOT NULL OR NEW.withheld_at IS NOT NULL OR NOT coalesce(NEW.is_published, false) THEN
    RETURN NEW;
  END IF;
  -- A ballot no one voted in has no one to tell.
  IF NOT EXISTS (SELECT 1 FROM public.dispatch_votes dv WHERE dv.post_id = NEW.id) THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('private.closed_ballots_told'));
  INSERT INTO private.ballot_notices_waiting (post_id, author, title)
  VALUES (NEW.id, NEW.user_id, NEW.title)
  ON CONFLICT (post_id) DO NOTHING;
  IF to_regclass('cron.job') IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM cron.job j WHERE j.jobname = 'the-closed-ballots-are-told') THEN
      PERFORM cron.schedule('the-closed-ballots-are-told', '1 seconds', 'SELECT private.closed_ballots_told();');
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: dispatch_notify_certify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_notify_certify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE p record; c record;
BEGIN
  IF NEW.post_id IS NOT NULL THEN
    SELECT id, user_id, kind, title INTO p
      FROM public.dispatch_posts WHERE id = NEW.post_id;
    PERFORM public.dispatch_notify(
      p.user_id, NEW.user_id, 'endorse',
      'certified ' || public.dispatch_names(p.kind, p.title) || '.',
      jsonb_build_object('dispatch_post_id', p.id, 'kind', p.kind, 'title', p.title),
      'endorse:post:' || p.id);
  ELSE
    SELECT id, user_id, post_id INTO c
      FROM public.dispatch_comments WHERE id = NEW.comment_id;
    -- Its own key: under the filing's, a critique's certifications were told as the filing's.
    PERFORM public.dispatch_notify(
      c.user_id, NEW.user_id, 'endorse',
      'certified your critique.',
      jsonb_build_object('dispatch_post_id', c.post_id, 'comment_id', c.id),
      'endorse:critique:' || c.post_id);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: dispatch_notify_critique(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_notify_critique() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE p record;
BEGIN
  SELECT id, user_id, kind, title INTO p
    FROM public.dispatch_posts WHERE id = NEW.post_id;
  PERFORM public.dispatch_notify(
    p.user_id, NEW.user_id, 'comment',
    'left a critique on ' || public.dispatch_names(p.kind, p.title) || '.',
    jsonb_build_object('dispatch_post_id', p.id, 'kind', p.kind,
                       'title', p.title, 'comment_id', NEW.id),
    'endorse:post:' || p.id);
  RETURN NEW;
END $$;


--
-- Name: dispatch_post_words(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_post_words(p_text text) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT cardinality(array_remove(regexp_split_to_array(coalesce(p_text, ''),
    '[\t\n\v\f\r \u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+'), ''))
$$;


--
-- Name: dispatch_posts_count_words(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_posts_count_words() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.words IS NULL
     OR NEW.full_content IS DISTINCT FROM OLD.full_content OR NEW.body IS DISTINCT FROM OLD.body
     OR NEW.words IS DISTINCT FROM OLD.words THEN
    NEW.words := public.dispatch_post_words(coalesce(NEW.full_content, NEW.body));
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: dispatch_posts_pin_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_posts_pin_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- The house's own machinery — the counters, `end_filing`, the Tribunal, the
  -- ballot freeze — all run as the table owner. Everything else is a member.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  -- Counts belong to the members who made them, not to the author.
  NEW.certify_count := OLD.certify_count;
  NEW.comment_count := OLD.comment_count;
  -- When it was filed is what orders the paper.
  NEW.created_at    := OLD.created_at;
  -- The kind is gated at INSERT by tier; changing it afterwards walks around
  -- that gate, so a take cannot quietly become a dossier.
  NEW.kind          := OLD.kind;
  -- Under review, or struck. Only the house moves these.
  NEW.withheld_at   := OLD.withheld_at;
  NEW.ended_at      := OLD.ended_at;
  NEW.ended_by      := OLD.ended_by;

  -- ── A BALLOT IS THE HOUSE'S, NOT THE AUTHOR'S ───────────────────────────
  -- The question is theirs to ask. The answer is not theirs to write, the
  -- films are not theirs to swap once anybody has voted on an index, and the
  -- deadline is not theirs to move after the fact.
  NEW.frozen_totals := OLD.frozen_totals;
  NEW.options       := OLD.options;
  NEW.closes_at     := OLD.closes_at;

  -- When a member changed it is the house's clock, never the phone's: a phone set a day ahead
  -- dated an edit tomorrow, and the newer of two copies read as the older.
  NEW.updated_at := now();
  IF NEW.edited_at IS DISTINCT FROM OLD.edited_at THEN
    NEW.edited_at := now();
  END IF;

  RETURN NEW;
END $$;


--
-- Name: dispatch_refuses_across_a_block(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_refuses_across_a_block() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row    jsonb := to_jsonb(NEW);
  v_author uuid;
BEGIN
  IF v_row ->> 'comment_id' IS NOT NULL THEN
    SELECT user_id INTO v_author FROM public.dispatch_comments WHERE id = (v_row ->> 'comment_id')::uuid;
  ELSE
    SELECT user_id INTO v_author FROM public.dispatch_posts WHERE id = (v_row ->> 'post_id')::uuid;
  END IF;
  IF public.a_block_stands_between(NEW.user_id, v_author) THEN
    RAISE EXCEPTION 'A block stands between these members.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: dispatch_room_totals(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_room_totals(p_user_id uuid) RETURNS TABLE(filed integer, certified bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    COUNT(*)::integer                        AS filed,
    COALESCE(SUM(p.certify_count), 0)::bigint AS certified
  FROM public.dispatch_posts p
  WHERE p.user_id = p_user_id
    AND p.is_published
    AND p.withheld_at IS NULL
    AND p.ended_at IS NULL;
$$;


--
-- Name: FUNCTION dispatch_room_totals(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dispatch_room_totals(p_user_id uuid) IS 'The two numbers at the head of a member''s room: how many filings they have standing, and how many certifications those carry. SECURITY INVOKER so every policy on dispatch_posts still applies — a blocked member learns nothing.';


--
-- Name: dispatch_scrub_departed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_scrub_departed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.user_id IS NULL AND OLD.user_id IS NOT NULL THEN
    NEW.author_username := '[deleted]';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: divert_private_notes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.divert_private_notes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v text := NULLIF(btrim(NEW.private_notes), '');
BEGIN
  IF v IS NOT NULL AND public.has_tier_at_least(1) THEN
    INSERT INTO public.log_private_notes (log_id, viewing_id, user_id, notes, updated_at)
    VALUES (NEW.id, NEW.viewing_id, NEW.user_id, left(v, 1000), now())
    ON CONFLICT (viewing_id) DO UPDATE SET notes = EXCLUDED.notes, updated_at = now();
  END IF;
  -- Below the rank a note is discarded, not refused: refusing would fail the
  -- whole log write and wedge an offline queue that cannot re-gate it.
  UPDATE public.logs SET private_notes = NULL WHERE id = NEW.id;
  RETURN NULL;
END $$;


--
-- Name: dossier_certifications_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dossier_certifications_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.dispatch_certifications (user_id, post_id)
    VALUES (NEW.user_id, NEW.dossier_id)
    RETURNING id INTO NEW.id;
    RETURN NEW;
  ELSE
    DELETE FROM public.dispatch_certifications
     WHERE user_id = OLD.user_id AND post_id = OLD.dossier_id;
    RETURN OLD;
  END IF;
END $$;


--
-- Name: dossier_comments_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dossier_comments_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.dispatch_comments (post_id, user_id, author_username, body)
    VALUES (NEW.dossier_id, NEW.user_id, coalesce(NEW.username, ''), NEW.body)
    RETURNING id INTO NEW.id;
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE public.dispatch_comments
       SET body            = NEW.body,
           user_id         = NEW.user_id,
           author_username = NEW.username,
           -- only a real edit is marked as one. An erasure changes the name and
           -- nothing else, and a critique that reads "edited" because its author
           -- closed their account is the app telling a small lie about a person
           -- who is no longer there to correct it.
           edited_at       = CASE WHEN NEW.body IS DISTINCT FROM OLD.body
                                  THEN now() ELSE edited_at END
     WHERE id = OLD.id;
    RETURN NEW;

  ELSE
    DELETE FROM public.dispatch_comments WHERE id = OLD.id;
    RETURN OLD;
  END IF;
END $$;


--
-- Name: dossiers_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dossiers_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.dispatch_posts
      (kind, user_id, author_username, title, body, full_content, is_published)
    VALUES ('dossier', NEW.user_id, NEW.author_username, NEW.title,
            coalesce(NEW.excerpt,''), NEW.full_content, coalesce(NEW.is_published,true))
    RETURNING id INTO NEW.id;
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE public.dispatch_posts
       SET title           = NEW.title,
           body            = coalesce(NEW.excerpt,''),
           full_content    = NEW.full_content,
           is_published    = NEW.is_published,
           -- carried, so an erasure through this name is a real erasure
           user_id         = NEW.user_id,
           author_username = NEW.author_username,
           -- an erasure is not an edit: it must not move the essay up the feed
           updated_at      = CASE WHEN NEW.user_id IS NULL AND OLD.user_id IS NOT NULL
                                  THEN updated_at ELSE now() END
     WHERE id = OLD.id;
    RETURN NEW;

  ELSE
    DELETE FROM public.dispatch_posts WHERE id = OLD.id;
    RETURN OLD;
  END IF;
END $$;


--
-- Name: end_filing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_filing(p_post uuid, p_by text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_by NOT IN ('author','house') THEN RAISE EXCEPTION 'bad ended_by'; END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = 'P0001';
  END IF;

  IF p_by = 'author' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.dispatch_posts
       WHERE id = p_post AND user_id = auth.uid()
    ) THEN
      RAISE EXCEPTION 'not yours' USING ERRCODE = '42501';
    END IF;
  ELSE
    -- 'house'. The same admin predicate the Tribunal uses, so there is one
    -- answer in this database to "is this the house" rather than two.
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles
       WHERE id = auth.uid() AND role = 'admin'
    ) THEN
      RAISE EXCEPTION 'not the house' USING ERRCODE = '42501';
    END IF;
  END IF;

  PERFORM public.dispatch_empty_filing(p_post, p_by);
END $$;


--
-- Name: FUNCTION end_filing(p_post uuid, p_by text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.end_filing(p_post uuid, p_by text) IS 'Withdraw a filing. Each branch proves its own right: the author proves ownership, the house proves role = admin. Before 2026-09-10 the house branch proved nothing and was granted to anon, so any caller could erase any filing.';


--
-- Name: enforce_log_tier_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_log_tier_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_auteur boolean; v_archivist boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;
  v_auteur    := public.has_tier_at_least(2);
  v_archivist := public.has_tier_at_least(1);

  IF TG_OP = 'INSERT' THEN
    IF NOT v_auteur THEN
      NEW.autopsy := NULL; NEW.is_autopsied := false; NEW.alt_poster := NULL;
    END IF;
    IF NOT v_archivist THEN
      NEW.editorial_header := NULL; NEW.pull_quote := NULL; NEW.drop_cap := false;
    END IF;
  ELSE
    IF NOT v_auteur THEN
      NEW.autopsy      := OLD.autopsy;
      NEW.is_autopsied := OLD.is_autopsied;
      NEW.alt_poster   := OLD.alt_poster;
    END IF;
    IF NOT v_archivist THEN
      NEW.editorial_header := OLD.editorial_header;
      NEW.pull_quote       := OLD.pull_quote;
      NEW.drop_cap         := OLD.drop_cap;
    END IF;
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_lounge_identity_freeze(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_lounge_identity_freeze() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_banned boolean;
  v_until  timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF (NEW.name, NEW.description, NEW.cover_image, NEW.is_private)
     IS NOT DISTINCT FROM (OLD.name, OLD.description, OLD.cover_image, OLD.is_private) THEN
    RETURN NEW;
  END IF;

  SELECT is_banned, suspended_until INTO v_banned, v_until
    FROM public.profiles WHERE id = auth.uid();

  IF COALESCE(v_banned, false) THEN
    RAISE EXCEPTION 'Your account has been silenced by The Society.' USING ERRCODE = '42501';
  END IF;
  IF v_until IS NOT NULL AND v_until > now() THEN
    RAISE EXCEPTION 'Your account is suspended until %.',
      to_char(v_until AT TIME ZONE 'UTC', 'DD Mon YYYY HH24:MI "UTC"')
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_not_restricted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_not_restricted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_banned boolean;
  v_until  timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT is_banned, suspended_until
    INTO v_banned, v_until
    FROM public.profiles WHERE id = auth.uid();

  IF COALESCE(v_banned, false) THEN
    RAISE EXCEPTION 'Your account has been silenced by The Society.'
      USING ERRCODE = '42501';
  END IF;

  IF v_until IS NOT NULL AND v_until > now() THEN
    RAISE EXCEPTION 'Your account is suspended until %.',
      to_char(v_until AT TIME ZONE 'UTC', 'DD Mon YYYY HH24:MI "UTC"')
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_privacy_on_follow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_privacy_on_follow() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_is_private BOOLEAN;
BEGIN
    IF NEW.type IN ('follow', 'follow_request')
       AND public.a_block_stands_between(NEW.user_id, NEW.target_user_id) THEN
        RAISE EXCEPTION 'A block stands between these members.' USING ERRCODE = '42501';
    END IF;
    IF NEW.type = 'follow' THEN
        SELECT is_social_private INTO v_is_private FROM public.profiles WHERE id = NEW.target_user_id;
        IF v_is_private THEN
            -- Automatically downgrade the 'follow' to a 'follow_request' at the database level.
            NEW.type := 'follow_request';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_profile_identity_freeze(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_profile_identity_freeze() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_banned boolean;
  v_until  timestamptz;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> NEW.id THEN
    RETURN NEW;
  END IF;

  NEW.is_banned         := OLD.is_banned;
  NEW.banned_at         := OLD.banned_at;
  NEW.suspended_until   := OLD.suspended_until;
  NEW.suspension_reason := OLD.suspension_reason;
  NEW.warning_count     := OLD.warning_count;

  IF (NEW.username, NEW.display_name, NEW.bio, NEW.avatar_url, NEW.social_links, NEW.persona)
     IS NOT DISTINCT FROM
     (OLD.username, OLD.display_name, OLD.bio, OLD.avatar_url, OLD.social_links, OLD.persona) THEN
    RETURN NEW;
  END IF;

  SELECT is_banned, suspended_until INTO v_banned, v_until
    FROM public.profiles WHERE id = auth.uid();

  IF COALESCE(v_banned, false) THEN
    RAISE EXCEPTION 'Your account has been silenced by The Society.' USING ERRCODE = '42501';
  END IF;
  IF v_until IS NOT NULL AND v_until > now() THEN
    RAISE EXCEPTION 'Your account is suspended until %.',
      to_char(v_until AT TIME ZONE 'UTC', 'DD Mon YYYY HH24:MI "UTC"')
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: enforce_tier_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tier_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT public.has_tier_at_least(TG_ARGV[0]::integer) THEN
    RAISE EXCEPTION '%', TG_ARGV[1] USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: enforce_username_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_username_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  reserved text[] := ARRAY[
    'admin','administrator','mod','moderator','support','help',
    'reelhouse','system','root','official','staff','team','bot',
    'null','undefined','anonymous','anon','deleted','unknown',
    'api','www','mail','email','noreply','no_reply',
    'settings','login','signup','logout','feed','discover',
    'profile','edit','delete','create','new','user','users'
  ];
  v_raw    text;
  v_clean  text;
  v_hex    text;
  v_base   text;
  v_n      integer;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.username IS NOT DISTINCT FROM OLD.username THEN
    RETURN NEW;
  END IF;

  -- An old build's save: the cleaned form of a handle that predates today's letters, sent with
  -- every save. The handle is kept. A rename the member chose (rename_my_handle marks its own
  -- write) goes on to the checks below.
  IF TG_OP = 'UPDATE'
     AND current_setting('reelhouse.deliberate_rename', true) IS DISTINCT FROM 'on'
     AND NEW.username = regexp_replace(
           regexp_replace(lower(btrim(coalesce(OLD.username, ''))), '[[:space:]]+', '_', 'g'),
           '[^a-z0-9_]', '', 'g') THEN
    NEW.username := OLD.username;
    RETURN NEW;
  END IF;

  v_raw := coalesce(NEW.username, '');

  v_clean := regexp_replace(
               regexp_replace(lower(btrim(v_raw)), '[[:space:]]+', '_', 'g'),
               '[^a-z0-9_]', '', 'g');

  IF TG_OP = 'UPDATE' THEN
    IF v_clean IS DISTINCT FROM v_raw THEN
      RAISE EXCEPTION 'Usernames may only contain lowercase letters, numbers and underscores.'
        USING ERRCODE = '23514';
    END IF;
    IF length(v_clean) < 3 THEN
      RAISE EXCEPTION 'Username must be at least 3 characters.' USING ERRCODE = '23514';
    END IF;
    IF length(v_clean) > 30 THEN
      RAISE EXCEPTION 'Username must be 30 characters or less.' USING ERRCODE = '23514';
    END IF;
    IF left(v_clean, 1) = '_' OR right(v_clean, 1) = '_' THEN
      RAISE EXCEPTION 'Username cannot start or end with an underscore.' USING ERRCODE = '23514';
    END IF;
    IF position('__' in v_clean) > 0 THEN
      RAISE EXCEPTION 'Username cannot have consecutive underscores.' USING ERRCODE = '23514';
    END IF;
    IF v_clean = ANY(reserved) THEN
      RAISE EXCEPTION 'This username is reserved.' USING ERRCODE = '23514';
    END IF;
    IF public.handle_is_unwelcome(v_clean) THEN
      RAISE EXCEPTION 'This username is not allowed.' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (SELECT 1 FROM public.profiles
                WHERE lower(username) = v_clean AND id <> NEW.id) THEN
      RAISE EXCEPTION 'This username is already taken.' USING ERRCODE = '23505';
    END IF;

    NEW.username := v_clean;
    RETURN NEW;
  END IF;

  v_hex := replace(NEW.id::text, '-', '');

  v_clean := regexp_replace(v_clean, '_+', '_', 'g');
  v_clean := btrim(v_clean, '_');
  v_clean := left(v_clean, 30);
  v_clean := btrim(v_clean, '_');

  IF length(v_clean) < 3 THEN
    v_clean := 'user_' || substr(v_hex, 1, 6);
  END IF;

  IF public.handle_is_unwelcome(v_clean) THEN
    v_clean := 'user_' || substr(v_hex, 1, 6);
  END IF;

  v_base := btrim(left(v_clean, 23), '_');
  v_n    := 0;
  WHILE v_clean = ANY(reserved)
        OR EXISTS (SELECT 1 FROM public.profiles
                    WHERE lower(username) = v_clean AND id <> NEW.id)
  LOOP
    v_n := v_n + 1;
    IF v_n > 20 THEN
      RAISE EXCEPTION 'Could not derive an available username.' USING ERRCODE = '23505';
    END IF;
    v_clean := v_base || '_' || substr(v_hex, v_n, 6);
  END LOOP;

  NEW.username := v_clean;
  RETURN NEW;
END;
$$;


--
-- Name: error_logs_daily_ceiling(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.error_logs_daily_ceiling() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  NEW.created_at := now();
  IF (SELECT count(*) FROM public.error_logs
       WHERE user_id = NEW.user_id AND created_at > now() - interval '1 day') >= 200 THEN
    RAISE EXCEPTION 'PGRST301: Too many requests. Please wait a moment.';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: expire_withheld_pieces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_withheld_pieces() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_n  integer := 0;
BEGIN
  -- The pieces whose 30 days passed unappealed: deleted as REMOVE CONTENT deleted them before. One whose
  -- appeal was filed in time carries no end (file_appeal), and waits for its hearing. Each is claimed
  -- under its lock (one an appeal or a hearing holds is left to the next hour), and its deadline asked
  -- again under that lock (delete_withheld_piece's p_due): an appeal filed meanwhile keeps it.
  FOR v_id IN SELECT mod_action_id FROM public.withheld_pieces WHERE delete_after <= now()
               ORDER BY delete_after LIMIT 500 FOR UPDATE SKIP LOCKED LOOP
    IF public.delete_withheld_piece(v_id, true) THEN
      v_n := v_n + 1;
    END IF;
  END LOOP;
  RETURN v_n;
END;
$$;


--
-- Name: file_appeal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_appeal(p_action_id uuid, p_appeal text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me    uuid := auth.uid();
  v_words text := btrim(coalesce(public.clean_member_text(p_appeal), ''));
  m       public.mod_actions%ROWTYPE;
BEGIN
  IF v_me IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF char_length(v_words) = 0 OR char_length(v_words) > 1000 THEN
    RAISE EXCEPTION 'An appeal is between 1 and 1,000 characters.' USING ERRCODE = 'P0001';
  END IF;
  -- Held while it is written: two presses at once file one appeal, the second refused.
  -- A member silenced or suspended may still appeal: the appeal is how they answer it.
  SELECT * INTO m FROM public.mod_actions
   WHERE id = p_action_id AND target_user_id = v_me AND action <> 'dismiss'
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VERDICT_GONE' USING ERRCODE = 'P0002';
  END IF;
  IF m.appeal IS NOT NULL THEN
    RAISE EXCEPTION 'ALREADY_APPEALED' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.mod_actions
     SET appeal = v_words, appeal_filed_at = now(), appeal_status = 'pending'
   WHERE id = p_action_id;
  -- A piece the verdict withheld is kept whole until the appeal is heard, however long that takes (H-B10).
  UPDATE public.withheld_pieces SET delete_after = NULL WHERE mod_action_id = p_action_id;
END;
$$;


--
-- Name: forget_other_devices(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forget_other_devices(p_keep_token text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_claim   text := auth.jwt() ->> 'session_id';
  v_session uuid := CASE WHEN v_claim ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                         THEN v_claim::uuid END;
  v_gone    integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  -- This phone's own row, written under the session this call is made from: claimed, so B8 reads
  -- every untied token that session could have registered as another phone's.
  IF v_session IS NOT NULL AND p_keep_token IS NOT NULL THEN
    UPDATE public.push_tokens SET session_id = v_session
     WHERE user_id = auth.uid() AND token = p_keep_token AND session_id IS DISTINCT FROM v_session;
  END IF;
  -- Every other phone's token of the member: this phone keeps its own, named by the token it holds
  -- or registered under this session.
  DELETE FROM public.push_tokens
   WHERE user_id = auth.uid()
     AND token IS DISTINCT FROM p_keep_token
     AND (v_session IS NULL OR session_id IS DISTINCT FROM v_session);
  GET DIAGNOSTICS v_gone = ROW_COUNT;
  RETURN v_gone;
END $_$;


--
-- Name: forget_push_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forget_push_token(p_token text, p_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Nothing a phone could hold: no row is looked for.
  IF p_token IS NULL OR p_user IS NULL OR char_length(p_token) NOT BETWEEN 1 AND 512 THEN
    RETURN false;
  END IF;
  -- The token, and the member it was registered to: a phone registered since to someone else keeps
  -- that member's row. At most one row (the token is UNIQUE).
  DELETE FROM public.push_tokens WHERE token = p_token AND user_id = p_user;
  RETURN true;
END $$;


--
-- Name: freeze_closed_ballots(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_closed_ballots() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE n integer;
BEGIN
  WITH tallied AS (
    SELECT p.id,
           jsonb_build_object(
             -- sum(v.n), not count(v.id): `v` is already GROUPED BY option, so
             -- it has no id to count and one row per option rather than one per
             -- vote. Counting its rows would have recorded "2 ballots cast" for
             -- a ballot with two options and two hundred voters — a permanent,
             -- plausible, wrong number, written once and never recomputed.
             'total', coalesce(sum(v.n), 0),
             'counts', coalesce(jsonb_object_agg(v.option_index, v.n)
                                FILTER (WHERE v.option_index IS NOT NULL), '{}'::jsonb),
             'frozen_at', now()
           ) AS totals
      FROM public.dispatch_posts p
      -- Each closing ballot's options as counted when the votes were cast (private.ballot_counts), read
      -- by the ballot (OFFSET 0 keeps it a lookup per ballot): never every vote of the house grouped again
      -- each time the schedule runs.
      LEFT JOIN LATERAL (
        SELECT c.option_index, c.n
          FROM private.ballot_counts c
         WHERE c.post_id = p.id AND c.n > 0
        OFFSET 0
      ) v ON true
     WHERE p.kind = 'ballot'
       AND p.closes_at <= now()
       AND p.frozen_totals IS NULL
       AND p.ended_at IS NULL
     GROUP BY p.id
  )
  UPDATE public.dispatch_posts p
     SET frozen_totals = t.totals
    FROM tallied t
   WHERE p.id = t.id;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: get_community_feed_auth_cursor(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_community_feed_auth_cursor(p_limit integer DEFAULT 40, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, film_id integer, film_title text, poster_path text, rating numeric, review text, drop_cap boolean, status text, abandoned_reason text, created_at timestamp with time zone, year text, user_id uuid, username text, avatar_url text, role text, editorial_header text, pull_quote text, watched_with text, is_autopsied boolean, autopsy jsonb, is_spoiler boolean, certify_count integer, critique_count integer, certified boolean, alt_poster text, physical_media text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH me AS (SELECT (SELECT private.hidden_authors()) AS hidden)
  SELECT
    l.id, l.film_id, l.film_title, l.poster_path, l.rating, l.review,
    l.drop_cap, l.status, l.abandoned_reason, l.created_at, l.year,
    l.user_id,
    p.username, p.avatar_url, p.role,
    l.editorial_header, l.pull_quote, l.watched_with,
    l.is_autopsied, l.autopsy, l.is_spoiler,
    COALESCE(c.certify_count, 0) AS certify_count,
    CASE
      WHEN COALESCE(cardinality(me.hidden), 0) = 0 THEN COALESCE(c.critique_count, 0)
      ELSE (SELECT count(*)::integer FROM log_comments x
             WHERE x.log_id = l.id AND NOT COALESCE(x.user_id = ANY (me.hidden), false)
               AND x.withheld_at IS NULL)
    END AS critique_count,
    (auth.uid() IS NOT NULL AND EXISTS (
      SELECT 1 FROM interactions im
       WHERE im.target_log_id = l.id AND im.user_id = (SELECT auth.uid()) AND im.type = 'endorse_log'
    )) AS certified,
    l.alt_poster, l.physical_media
  FROM logs l
  JOIN profiles p ON p.id = l.user_id
  LEFT JOIN log_counts c ON c.log_id = l.id
  CROSS JOIN me
  WHERE l.review IS NOT NULL
    AND l.review <> ''
    -- a log the house withholds is in no feed, its author's own included (H-B10)
    AND l.withheld_at IS NULL
    AND NOT COALESCE(l.user_id = ANY ((SELECT private.hidden_authors())::uuid[]), false)
    AND (
      p_cursor_created_at IS NULL
      OR (l.created_at, l.id) < (p_cursor_created_at, p_cursor_id)
    )
  ORDER BY l.created_at DESC, l.id DESC
  LIMIT p_limit;
$$;


--
-- Name: get_email_by_username(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_email_by_username(lookup_username text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  found_email TEXT;
BEGIN
  SELECT au.email INTO found_email
  FROM auth.users au
  INNER JOIN public.profiles p ON p.id = au.id
  WHERE LOWER(p.username) = LOWER(lookup_username)
  LIMIT 1;
  
  RETURN found_email;
END;
$$;


--
-- Name: get_filtered_stacks_auth_cursor_v2(text, boolean, integer, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_filtered_stacks_auth_cursor_v2(p_search text DEFAULT ''::text, p_filter_following boolean DEFAULT false, p_limit integer DEFAULT 60, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_poster_count integer DEFAULT 4) RETURNS TABLE(id uuid, title text, description text, username text, user_id uuid, created_at timestamp with time zone, films jsonb, film_count bigint, certify_count bigint, is_ranked boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH
  -- A search's one- and two-letter pieces, when it has no three letters or digits in a row; none when it
  -- is all wildcards (then it walks). Read by them, the words' own test is asked inside COALESCE, so no
  -- plan reads a trigram index for them whole (it holds nothing to find them by).
  short AS MATERIALIZED (
    SELECT CASE WHEN p_search !~ '[[:alnum:]]{3}'
                THEN private.pattern_grams('%' || like_escape(COALESCE(p_search, '')) || '%') END AS grams
  ),
  -- A search that matches many stacks walks them newest first, as with no search, and stops
  -- at its page; one that matches few is read by its matches. Counted by the trigram indexes,
  -- to 1,000 at most (load 43284739569: the walk 6.5 ms for a word every stack has and 292.7
  -- for a handle; the matches 94.7 and 4.4).
  -- Without three letters or digits in a row no trigram index can find a word (it is made of three-
  -- letter pieces; "m1" counted by them took 506.9 ms, load 43292798767): such a search is counted by
  -- its one- and two-letter pieces instead (lists_short_grams, profiles_short_grams), and walks only
  -- when it has none (all wildcards).
  -- Asked first of the newest 300 public stacks, each asked the words by its title and its author's
  -- handle: when three in twenty of a page's worth hold them (9 for 60), the words are held by one stack
  -- in about 33 or more, so the walk meets its page within some 2,000 stacks, and no index that gathers
  -- every holder is read ("m1" gathered 11,112 members of 100,000 from the short pieces, in
  -- proportion to the house).
  -- How many of the newest 300 hold the words (to 9 for 60), and so how far the walk would go for its page:
  -- a page in 300 / hits stacks. The matches are counted to that reach at most (1,000 when none of the 300
  -- holds them), and walked only when they are as many: a word one stack in 75 holds ("stack 12", 1,110
  -- stacks at 500,000 members, load 45122008179) is read by its matches, never walked through 4,500 stacks
  -- (13,406 rows, 109.8 ms). Either way a search reads at most its reach, whatever the house's size.
  sampled AS MATERIALIZED (
    SELECT s.hits, CASE WHEN s.hits > 0 THEN GREATEST(1000, p_limit * 300 / s.hits) ELSE 1000 END AS reach
      FROM (SELECT count(*)::integer AS hits FROM (
              SELECT 1 FROM (SELECT l.title, l.user_id FROM lists l
                              WHERE l.is_private = false
                              ORDER BY l.created_at DESC, l.id DESC
                              LIMIT 300) w
               WHERE COALESCE(w.title ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\', false)
                  OR COALESCE((SELECT pu.username FROM profiles pu WHERE pu.id = w.user_id)
                                ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\', false)
               LIMIT GREATEST(p_limit * 3 / 20, 1)) newest) s
  ),
  many AS MATERIALIZED (
    SELECT CASE WHEN COALESCE(p_search, '') = '' OR (p_search !~ '[[:alnum:]]{3}' AND (SELECT grams FROM short) IS NULL) THEN true
                WHEN (SELECT hits FROM sampled) >= GREATEST(p_limit * 3 / 20, 1) THEN true
                WHEN p_search !~ '[[:alnum:]]{3}' THEN (
      SELECT count(*) >= (SELECT reach FROM sampled) FROM (
        SELECT l.id FROM lists l
         WHERE l.is_private = false
           AND private.search_grams(l.title, l.description) @> (SELECT grams FROM short)
           AND COALESCE(l.title ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\', false)
        UNION ALL
        SELECT l.id FROM profiles pu
         CROSS JOIN LATERAL (SELECT l.id FROM lists l WHERE l.user_id = pu.id AND l.is_private = false OFFSET 0) l
         WHERE private.search_grams(pu.username, pu.display_name) @> (SELECT grams FROM short)
           AND COALESCE(pu.username ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\', false)
        LIMIT (SELECT reach FROM sampled)
      ) counted_short)
                ELSE (
      SELECT count(*) >= (SELECT reach FROM sampled) FROM (
        SELECT l.id FROM lists l
         WHERE l.is_private = false
           AND l.title ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\'
        UNION ALL
        -- Each member whose handle holds the words, then their stacks by their own index (OFFSET 0
        -- keeps it a lookup per member): never every stack of the house read to be joined.
        SELECT l.id FROM profiles pu
         CROSS JOIN LATERAL (SELECT l.id FROM lists l WHERE l.user_id = pu.id AND l.is_private = false OFFSET 0) l
         WHERE pu.username ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\'
        LIMIT (SELECT reach FROM sampled)
      ) counted) END AS walk
  ),
  -- The matches of a few, newest first, before anything is asked of them.
  matched AS MATERIALIZED (
    SELECT m.id, m.created_at, m.user_id FROM (
      SELECT l.id, l.created_at, l.user_id
        FROM lists l
       WHERE COALESCE(p_search, '') <> '' AND NOT (SELECT walk FROM many) AND l.is_private = false
         AND p_search ~ '[[:alnum:]]{3}'
         AND l.withheld_at IS NULL
         AND l.title ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\'
      UNION
      SELECT l.id, l.created_at, l.user_id
        FROM lists l
       WHERE COALESCE(p_search, '') <> '' AND NOT (SELECT walk FROM many) AND l.is_private = false
         AND p_search !~ '[[:alnum:]]{3}'
         AND private.search_grams(l.title, l.description) @> (SELECT grams FROM short)
         AND l.withheld_at IS NULL
         AND COALESCE(l.title ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\', false)
      UNION
      SELECT l.id, l.created_at, l.user_id
        FROM profiles pu
       CROSS JOIN LATERAL (SELECT l.id, l.created_at, l.user_id FROM lists l
                            WHERE l.user_id = pu.id AND l.is_private = false AND l.withheld_at IS NULL OFFSET 0) l
       WHERE COALESCE(p_search, '') <> '' AND NOT (SELECT walk FROM many)
         AND p_search ~ '[[:alnum:]]{3}'
         AND pu.username ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\'
      UNION
      SELECT l.id, l.created_at, l.user_id
        FROM profiles pu
       CROSS JOIN LATERAL (SELECT l.id, l.created_at, l.user_id FROM lists l
                            WHERE l.user_id = pu.id AND l.is_private = false AND l.withheld_at IS NULL OFFSET 0) l
       WHERE COALESCE(p_search, '') <> '' AND NOT (SELECT walk FROM many)
         AND p_search !~ '[[:alnum:]]{3}'
         AND private.search_grams(pu.username, pu.display_name) @> (SELECT grams FROM short)
         AND COALESCE(pu.username ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\', false)
    ) m
     WHERE p_cursor_created_at IS NULL OR (m.created_at, m.id) < (p_cursor_created_at, p_cursor_id)
     ORDER BY m.created_at DESC, m.id DESC
  ),
  page AS (
    -- No search, or a search of many: today's walk, today's test of each stack.
    (SELECT l.id, l.created_at
       FROM lists l
      WHERE (COALESCE(p_search, '') = '' OR (SELECT walk FROM many))
        AND (
          COALESCE(p_search, '') = ''
          OR l.title ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\'
          -- The author's handle, looked up as the walk reaches each stack (a scalar subquery is
          -- never folded into a join): the walk stops at its page, never reading every member
          -- whose handle holds the word (today's IN (...) did, 219.4 ms for "m1").
          OR (SELECT pu.username FROM profiles pu WHERE pu.id = l.user_id)
               ILIKE '%' || like_escape(p_search) || '%' ESCAPE '\'
        )
        AND l.is_private = false
        -- a stack the house withholds is on no shelf (H-B10)
        AND l.withheld_at IS NULL
        AND NOT COALESCE(l.user_id = ANY ((SELECT private.hidden_authors())::uuid[]), false)
        AND private.can_view_user_data(l.user_id)
        AND (p_filter_following = false OR EXISTS (
              SELECT 1 FROM interactions i
               WHERE i.target_user_id = l.user_id AND i.user_id = auth.uid() AND i.type = 'follow'))
        AND (p_cursor_created_at IS NULL OR (l.created_at, l.id) < (p_cursor_created_at, p_cursor_id))
      ORDER BY l.created_at DESC, l.id DESC
      LIMIT p_limit)
    UNION ALL
    -- Read in the order it was kept (newest first), each asked only as it is reached.
    (SELECT m.id, m.created_at
       FROM matched m
      WHERE NOT COALESCE(m.user_id = ANY ((SELECT private.hidden_authors())::uuid[]), false)
        AND private.can_view_user_data(m.user_id)
        AND (p_filter_following = false OR EXISTS (
              SELECT 1 FROM interactions i
               WHERE i.target_user_id = m.user_id AND i.user_id = auth.uid() AND i.type = 'follow'))
      LIMIT p_limit)
  )
  SELECT
    l.id, l.title, l.description,
    p.username, l.user_id, l.created_at,
    COALESCE(
      (SELECT jsonb_agg(f ORDER BY f_created_at ASC)
       FROM (
         SELECT jsonb_build_object('id', li.film_id, 'title', li.film_title,
                                   'poster_path', li.poster_path) AS f,
                li.created_at AS f_created_at
         FROM list_items li
         WHERE li.list_id = l.id AND li.poster_path IS NOT NULL
         ORDER BY li.created_at ASC
         LIMIT LEAST(GREATEST(p_poster_count, 0), 10)
       ) top_films),
      '[]'::jsonb
    ) AS films,
    (SELECT COUNT(*) FROM list_items li WHERE li.list_id = l.id) AS film_count,
    public.list_certify_count(l.id) AS certify_count,
    l.is_ranked
  FROM page pg
  -- Each stack of the page read by its id (OFFSET 0 keeps it a lookup per stack): never every stack of
  -- the house hashed to be joined to a page of sixty.
  CROSS JOIN LATERAL (SELECT l.id, l.title, l.description, l.user_id, l.created_at, l.is_ranked
                        FROM lists l WHERE l.id = pg.id OFFSET 0) l
  JOIN profiles p ON p.id = l.user_id
  ORDER BY l.created_at DESC, l.id DESC;
$$;


--
-- Name: get_following_feed_auth_cursor(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_following_feed_auth_cursor(p_limit integer DEFAULT 40, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, film_id integer, film_title text, poster_path text, rating numeric, review text, drop_cap boolean, status text, abandoned_reason text, created_at timestamp with time zone, year text, user_id uuid, username text, avatar_url text, role text, editorial_header text, pull_quote text, watched_with text, is_autopsied boolean, autopsy jsonb, is_spoiler boolean, certify_count integer, critique_count integer, certified boolean, alt_poster text, physical_media text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH me AS (SELECT (SELECT private.hidden_authors()) AS hidden),
  followed AS (
    SELECT i.target_user_id AS author
      FROM public.interactions i
     WHERE i.user_id = (SELECT auth.uid())
       AND i.type = 'follow'
       AND NOT COALESCE(i.target_user_id = ANY ((SELECT private.hidden_authors())::uuid[]), false)
       -- can_view_user_data of a member the reader follows, asked here as one join, not a call a
       -- follow: their profile is there (the follow itself opens a private file), and no block
       -- stands either way, which the test above already holds (hidden_authors() names every
       -- member the reader blocked and every member who blocked them).
       AND EXISTS (SELECT 1 FROM public.profiles fp WHERE fp.id = i.target_user_id)
  ),
  page AS (
    SELECT r.id, r.created_at
      FROM followed f
      CROSS JOIN LATERAL (
        SELECT l.id, l.created_at
          FROM public.logs l
         WHERE l.user_id = f.author
           AND l.review IS NOT NULL
           AND l.review <> ''
           -- a log the house withholds is in no feed (H-B10)
           AND l.withheld_at IS NULL
           AND (p_cursor_created_at IS NULL OR (l.created_at, l.id) < (p_cursor_created_at, p_cursor_id))
         ORDER BY l.created_at DESC, l.id DESC
         LIMIT p_limit
      ) r
     ORDER BY r.created_at DESC, r.id DESC
     LIMIT p_limit
  )
  SELECT
    l.id, l.film_id, l.film_title, l.poster_path, l.rating, l.review,
    l.drop_cap, l.status, l.abandoned_reason, l.created_at, l.year,
    l.user_id,
    p.username, p.avatar_url, p.role,
    l.editorial_header, l.pull_quote, l.watched_with,
    l.is_autopsied, l.autopsy, l.is_spoiler,
    COALESCE(c.certify_count, 0) AS certify_count,
    CASE
      WHEN COALESCE(cardinality(me.hidden), 0) = 0 THEN COALESCE(c.critique_count, 0)
      ELSE (SELECT count(*)::integer FROM public.log_comments x
             WHERE x.log_id = l.id AND NOT COALESCE(x.user_id = ANY (me.hidden), false)
               AND x.withheld_at IS NULL)
    END AS critique_count,
    EXISTS (
      SELECT 1 FROM public.interactions im
       WHERE im.target_log_id = l.id AND im.user_id = (SELECT auth.uid()) AND im.type = 'endorse_log'
    ) AS certified,
    l.alt_poster, l.physical_media
  FROM page pg
  JOIN public.logs l ON l.id = pg.id
  JOIN public.profiles p ON p.id = l.user_id
  LEFT JOIN public.log_counts c ON c.log_id = l.id
  CROSS JOIN me
  ORDER BY pg.created_at DESC, pg.id DESC;
$$;


--
-- Name: get_lobby(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lobby() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH ed AS (
    SELECT max(edition) AS edition FROM public.lobby_editions
     WHERE edition <= (now() AT TIME ZONE 'UTC')::date
  ),
  the_log AS (
    SELECT l.id, l.review, l.rating, l.film_id, l.film_title, l.poster_path,
           p.id AS author_id, p.username, p.avatar_url, p.role, p.tier, p.is_founding
      FROM ed
      JOIN public.lobby_editions e ON e.edition = ed.edition AND e.slot = 'log'
      JOIN public.logs l ON l.id = e.target_id
      JOIN public.profiles p ON p.id = l.user_id
     WHERE btrim(coalesce(l.review, '')) <> '' AND NOT coalesce(l.is_spoiler, false)
       AND l.withheld_at IS NULL  -- a piece the house withholds hangs for no one, its author included (H-B10)
       AND NOT coalesce(p.is_banned, false)
       AND NOT private.is_hidden_by(auth.uid(), l.user_id)
     ORDER BY e.place
     LIMIT 1
  ),
  the_stack AS (
    SELECT s.id, s.title, s.description,
           p.id AS author_id, p.username, p.avatar_url, p.role, p.tier, p.is_founding
      FROM ed
      JOIN public.lobby_editions e ON e.edition = ed.edition AND e.slot = 'list'
      JOIN public.lists s ON s.id = e.target_id
      JOIN public.profiles p ON p.id = s.user_id
     WHERE NOT coalesce(s.is_private, false)
       AND s.withheld_at IS NULL  -- a piece the house withholds hangs for no one (H-B10)
       AND (SELECT count(*) FROM public.list_items i WHERE i.list_id = s.id) >= 4
       AND NOT coalesce(p.is_banned, false)
       AND NOT private.is_hidden_by(auth.uid(), s.user_id)
     ORDER BY (s.user_id = (SELECT author_id FROM the_log)) IS TRUE, e.place
     LIMIT 1
  ),
  the_filings AS (
    SELECT f.* FROM (
      SELECT d.id, d.kind, d.title,
             left(coalesce(nullif(d.full_content, ''), d.body, ''), 1500) AS text,
             coalesce(array_length(regexp_split_to_array(btrim(coalesce(nullif(d.full_content, ''), d.body, '')), '\s+'), 1), 0) AS words,
             p.id AS author_id, p.username, p.avatar_url, p.role, p.tier, p.is_founding,
             e.place,
             row_number() OVER (PARTITION BY d.user_id ORDER BY e.place) AS nth
        FROM ed
        JOIN public.lobby_editions e ON e.edition = ed.edition AND e.slot = 'post'
        JOIN public.dispatch_posts d ON d.id = e.target_id
        JOIN public.profiles p ON p.id = d.user_id
       -- asked here, not left to the rules: an author reads their own withheld or drawn-back filing
       WHERE coalesce(d.is_published, false) AND d.withheld_at IS NULL
         AND d.ended_at IS NULL AND d.spoiler_label IS NULL
         AND NOT coalesce(p.is_banned, false)
    ) f
    ORDER BY f.nth > 1, f.place
    LIMIT 3
  )
  SELECT jsonb_build_object(
    'edition', (SELECT edition FROM ed),
    'log', (SELECT jsonb_build_object(
              'id', l.id, 'words', l.review, 'rating', l.rating,
              'film', jsonb_build_object('id', l.film_id, 'title', l.film_title, 'poster_path', l.poster_path),
              'author', jsonb_build_object('id', l.author_id, 'username', l.username, 'avatar_url', l.avatar_url,
                                           'role', l.role, 'tier', l.tier, 'is_founding', l.is_founding))
              FROM the_log l),
    'stack', (SELECT jsonb_build_object(
              'id', s.id, 'title', s.title, 'description', s.description,
              'films', (SELECT count(*) FROM public.list_items i WHERE i.list_id = s.id),
              'posters', coalesce((SELECT jsonb_agg(jsonb_build_object('film_id', f.film_id, 'title', f.film_title, 'poster_path', f.poster_path)
                                                    ORDER BY f.rank_position)
                                     FROM (SELECT film_id, film_title, poster_path, rank_position FROM public.list_items
                                            WHERE list_id = s.id ORDER BY rank_position LIMIT 3) f), '[]'::jsonb),
              'author', jsonb_build_object('id', s.author_id, 'username', s.username, 'avatar_url', s.avatar_url,
                                           'role', s.role, 'tier', s.tier, 'is_founding', s.is_founding))
              FROM the_stack s),
    'filings', coalesce((SELECT jsonb_agg(jsonb_build_object(
              'id', f.id, 'kind', f.kind, 'title', f.title, 'text', f.text, 'words', f.words,
              'author', jsonb_build_object('id', f.author_id, 'username', f.username, 'avatar_url', f.avatar_url,
                                           'role', f.role, 'tier', f.tier, 'is_founding', f.is_founding))
              ORDER BY f.nth > 1, f.place) FROM the_filings f), '[]'::jsonb)
  );
$$;


--
-- Name: FUNCTION get_lobby(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_lobby() IS 'The Lobby wall for the member asking: today''s edition, read under their own rules and blocks, one member one bill. No counts.';


--
-- Name: get_lounge_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lounge_list() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH me AS (SELECT auth.uid() AS id),
  memberships AS (
    SELECT lm.lounge_id, lm.last_read_at, lm.status
      FROM public.lounge_members lm, me WHERE lm.user_id = me.id LIMIT 100
  ),
  newest AS (
    SELECT l.id, l.name, l.description, l.is_private, l.creator_id, l.created_at, l.member_count, l.cover_image
      FROM public.lounges l ORDER BY l.created_at DESC LIMIT 50
  ),
  hosted AS (
    SELECT l.id, l.name, l.description, l.is_private, l.creator_id, l.created_at, l.member_count, l.cover_image
      FROM public.lounges l, me WHERE l.creator_id = me.id
  ),
  joined AS (
    SELECT l.id, l.name, l.description, l.is_private, l.creator_id, l.created_at, l.member_count, l.cover_image
      FROM public.lounges l WHERE l.id IN (SELECT lounge_id FROM memberships)
  ),
  -- The member's own: seated (a ban or a mute is no seat) or hosted.
  own AS (
    SELECT lounge_id AS id FROM memberships WHERE status IS NULL OR status NOT IN ('banned', 'muted')
    UNION SELECT id FROM hosted
  )
  SELECT jsonb_build_object(
    'memberships', coalesce((SELECT jsonb_agg(to_jsonb(m)) FROM memberships m), '[]'::jsonb),
    'newest', coalesce((SELECT jsonb_agg(to_jsonb(n) ORDER BY n.created_at DESC) FROM newest n), '[]'::jsonb),
    'hosted', coalesce((SELECT jsonb_agg(to_jsonb(h)) FROM hosted h), '[]'::jsonb),
    'joined', coalesce((SELECT jsonb_agg(to_jsonb(j)) FROM joined j), '[]'::jsonb),
    -- Asked only of a member who sits somewhere, as the client asks it; every piece a list.
    'unread', CASE WHEN EXISTS (SELECT 1 FROM memberships)
      THEN coalesce((SELECT jsonb_agg(to_jsonb(u)) FROM public.get_lounge_unread_counts() u), '[]'::jsonb)
      ELSE '[]'::jsonb END,
    -- Who waits at the doors the member hosts, each named: never one the host has blocked or
    -- muted (the room does not offer them to be admitted across it, nor counts them).
    'pending', coalesce((SELECT jsonb_agg(jsonb_build_object('lounge_id', p.lounge_id, 'user_id', p.user_id))
      FROM public.lounge_members p WHERE p.lounge_id IN (SELECT id FROM hosted) AND p.status = 'pending'
        AND NOT private.is_hidden_by((SELECT id FROM me), p.user_id)), '[]'::jsonb),
    'faces', coalesce((SELECT jsonb_agg(to_jsonb(f))
      FROM public.get_salon_member_faces(ARRAY(SELECT id FROM own)) f), '[]'::jsonb),
    'last_words', coalesce((SELECT jsonb_agg(to_jsonb(w))
      FROM public.get_salon_last_words(ARRAY(SELECT id FROM newest WHERE id NOT IN (SELECT id FROM own))) w), '[]'::jsonb)
  )
$$;


--
-- Name: get_lounge_unread_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_lounge_unread_counts() RETURNS TABLE(lounge_id uuid, unread_count bigint, last_message_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET enable_bitmapscan TO 'off'
    AS $$
  WITH me AS (SELECT auth.uid() AS id, (SELECT private.hidden_authors()) AS hidden),
  -- The members hidden, as a set: each word counted asks it once, by its hash, never the whole list
  -- (the whale of the load house hides 500: 26 ms of its count went to walking the list for each word).
  hidden AS MATERIALIZED (SELECT h.u FROM me, unnest(me.hidden) h(u) WHERE h.u IS NOT NULL),
  rooms AS (
    SELECT lm.lounge_id, lm.last_read_at, (NOT l.is_private OR lm.status IN ('approved', 'muted')) AS readable
      FROM me
      JOIN public.lounge_members lm ON lm.user_id = me.id
      JOIN public.lounges l ON l.id = lm.lounge_id
  )
  SELECT
    r.lounge_id,
    -- The newest hundred dispatches since the reading (a room never read: its newest hundred), read in
    -- the order of lounge_messages_room_newest, so the read stops at a hundred however many there are;
    -- then those the member may read and did not write counted. A room read before is read from that
    -- moment alone: one test asking "never read, or since" could start nowhere.
    CASE WHEN r.readable THEN (
      CASE WHEN r.last_read_at IS NULL THEN (
        SELECT count(*) FROM (
          SELECT m.user_id, m.carries_words_of FROM public.lounge_messages m
           WHERE m.lounge_id = r.lounge_id
           ORDER BY m.created_at DESC, m.id DESC
           LIMIT 100
        ) w
         WHERE w.user_id <> me.id
           AND w.user_id NOT IN (SELECT h.u FROM hidden h)
           AND NOT COALESCE(w.carries_words_of && me.hidden, false)
      ) ELSE (
        SELECT count(*) FROM (
          SELECT m.user_id, m.carries_words_of FROM public.lounge_messages m
           WHERE m.lounge_id = r.lounge_id
             AND m.created_at > r.last_read_at
           ORDER BY m.created_at DESC, m.id DESC
           LIMIT 100
        ) w
         WHERE w.user_id <> me.id
           AND w.user_id NOT IN (SELECT h.u FROM hidden h)
           AND NOT COALESCE(w.carries_words_of && me.hidden, false)
      ) END
    ) ELSE 0 END AS unread_count,
    -- The last word the member can read: one from a member they hid moved the card to the front
    -- and said "LAST WORD 1M AGO" over a room with nothing new in it (review round 8); one carrying
    -- a hidden member's words is not one they can read either (review round 14).
    CASE WHEN r.readable THEN (
      SELECT m.created_at FROM public.lounge_messages m
       WHERE m.lounge_id = r.lounge_id
         AND NOT COALESCE(m.user_id = ANY (me.hidden), false)
         AND (m.user_id = me.id OR NOT COALESCE(m.carries_words_of && me.hidden, false))
       ORDER BY m.created_at DESC, m.id DESC
       LIMIT 1
    ) END AS last_message_at
  FROM rooms r CROSS JOIN me;
$$;


--
-- Name: get_marks_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_marks_ledger() RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH me AS MATERIALIZED (
    -- The member asking, and whether the logs' read rule would hide their own rows from them.
    SELECT (SELECT auth.uid()) AS id,
           COALESCE((SELECT auth.uid()) = ANY ((SELECT private.hidden_authors())::uuid[]), false) AS hidden
  )
  SELECT json_build_object(
    -- One pass over the member's logs; every column is gathered in the same order, so the i-th of each
    -- is the same log.
    'logs', (SELECT json_build_object(
               'id', COALESCE(array_agg(l.id), '{}'),
               'film_id', COALESCE(array_agg(l.film_id), '{}'),
               'film_title', COALESCE(array_agg(l.film_title), '{}'),
               'poster_path', COALESCE(array_agg(l.poster_path), '{}'),
               'year', COALESCE(array_agg(l.year), '{}'),
               'status', COALESCE(array_agg(l.status), '{}'),
               'rating', COALESCE(array_agg(l.rating), '{}'),
               'view_count', COALESCE(array_agg(l.view_count), '{}'),
               'watched_date', COALESCE(array_agg(l.watched_date), '{}'))
               FROM public.logs l
              WHERE l.user_id = me.id AND NOT me.hidden),
    'saved', (SELECT to_json(COALESCE(array_agg(w.film_id), '{}'))
                FROM public.watchlists w
               WHERE w.user_id = me.id AND NOT me.hidden))
    FROM me
   WHERE me.id IS NOT NULL;
$$;


--
-- Name: get_moderation_history_for_users(uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_moderation_history_for_users(p_user_ids uuid[], p_per_user integer DEFAULT 5) RETURNS TABLE(id uuid, report_id uuid, target_user_id uuid, admin_id uuid, action text, reason text, duration_hours integer, expires_at timestamp with time zone, created_at timestamp with time zone, lifted_at timestamp with time zone, appeal_status text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Each member named once, then read alone: their newest verdicts from the front of
  -- idx_mod_actions_target, to their page and no further.
  SELECT m.id, m.report_id, m.target_user_id, m.admin_id, m.action, m.reason,
         m.duration_hours, m.expires_at, m.created_at, m.lifted_at, m.appeal_status
    FROM (SELECT DISTINCT u FROM unnest(COALESCE(p_user_ids, ARRAY[]::uuid[])) u WHERE u IS NOT NULL) who
   CROSS JOIN LATERAL (
     SELECT a.id, a.report_id, a.target_user_id, a.admin_id, a.action, a.reason,
            a.duration_hours, a.expires_at, a.created_at, a.lifted_at, a.appeal_status
       FROM public.mod_actions a
      WHERE a.target_user_id = who.u
      ORDER BY a.created_at DESC, a.id DESC
      LIMIT LEAST(GREATEST(COALESCE(p_per_user, 5), 0), 20)
   ) m
   WHERE EXISTS (
     SELECT 1 FROM public.profiles p
      WHERE p.id = (SELECT auth.uid()) AND p.role = 'admin'
   )
   ORDER BY m.target_user_id, m.created_at DESC, m.id DESC;
$$;


--
-- Name: get_my_follows(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_follows() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- One pass over the member's own follows and requests, each with its handle; both lists in the
  -- order the follows were made.
  SELECT jsonb_build_object(
    'following', COALESCE(jsonb_agg(p.username ORDER BY i.created_at, i.id) FILTER (WHERE i.type = 'follow'), '[]'::jsonb),
    'requested', COALESCE(jsonb_agg(p.username ORDER BY i.created_at, i.id) FILTER (WHERE i.type = 'follow_request'), '[]'::jsonb))
    FROM public.interactions i
    JOIN public.profiles p ON p.id = i.target_user_id
   WHERE i.user_id = (SELECT auth.uid())
     AND i.type IN ('follow', 'follow_request');
$$;


--
-- Name: FUNCTION get_my_follows(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_my_follows() IS 'The caller''s follow list in one read, for the phone at launch: the handles they follow and the handles they asked to follow, each in the order made. Runs as the caller, under the interactions'' and profiles'' own rules.';


--
-- Name: get_my_verdict(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_verdict(p_action_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  m    public.mod_actions%ROWTYPE;
BEGIN
  IF v_me IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  -- One's own verdicts alone; a dismissal of a report about one is no verdict on one.
  SELECT * INTO m FROM public.mod_actions
   WHERE id = p_action_id AND target_user_id = v_me AND action <> 'dismiss';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'VERDICT_GONE' USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'id', m.id,
    'action', m.action,
    'reason', m.reason,
    'created_at', m.created_at,
    'duration_hours', m.duration_hours,
    'expires_at', m.expires_at,
    -- What a removal took: the member's own words, kept with the verdict.
    'removed', CASE WHEN m.action = 'delete_content' AND m.content_snapshot IS NOT NULL
                    THEN jsonb_strip_nulls(jsonb_build_object('title', m.content_snapshot ->> 'title', 'body', m.content_snapshot ->> 'body')) END,
    -- Whether an overturned removal puts the piece back where it stood, or only hands back its words:
    -- a piece withheld (H-B10) is given back whole, its critiques and marks with it.
    'restorable', (m.content_snapshot ? 'kept') OR EXISTS (SELECT 1 FROM public.withheld_pieces w WHERE w.mod_action_id = m.id),
    -- Withheld, not yet deleted: seen by the member alone, and kept whole until (appeal_by) unappealed,
    -- or until its appeal is heard (no end once one is filed).
    'withheld', EXISTS (SELECT 1 FROM public.withheld_pieces w WHERE w.mod_action_id = m.id),
    'appeal_by', (SELECT w.delete_after FROM public.withheld_pieces w WHERE w.mod_action_id = m.id),
    -- Overturned: whether it was put back where it stood (whole, for a piece withheld), as the hearing
    -- wrote it on the verdict (the register goes when the piece is given back).
    'put_back', coalesce(m.appeal_put_back, false),
    'lifted_at', m.lifted_at,
    'lift_reason', m.lift_reason,
    'appeal', CASE WHEN m.appeal IS NULL THEN NULL ELSE jsonb_build_object(
                'text', m.appeal, 'filed_at', m.appeal_filed_at, 'status', m.appeal_status,
                'judged_at', m.appeal_judged_at, 'note', m.appeal_note) END,
    'can_appeal', m.appeal IS NULL,
    -- An appeal no moderator may hear yet (the house's one moderator ruled it, or it is about them): it
    -- waits for another, and the member is told so (the owner's decision, 2026-11-19).
    'no_moderator_yet', m.appeal_status = 'pending' AND NOT private.an_appeal_may_be_heard(m.admin_id, m.target_user_id));
END;
$$;


--
-- Name: get_my_verdicts(timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_verdicts(p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me uuid := auth.uid();
BEGIN
  IF v_me IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  -- One's own verdicts alone; a dismissal of a report about one is no verdict on one.
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'id', m.id,
             'action', m.action,
             'reason', m.reason,
             'created_at', m.created_at,
             'duration_hours', m.duration_hours,
             'expires_at', m.expires_at,
             'lifted_at', m.lifted_at,
             'appeal_status', m.appeal_status,
             'content_type', (SELECT r.content_type FROM public.reports r WHERE r.id = m.report_id))
           ORDER BY m.created_at DESC, m.id DESC)
      FROM (
        SELECT * FROM public.mod_actions q
         WHERE q.target_user_id = v_me AND q.action <> 'dismiss'
           AND (p_cursor_at IS NULL OR (q.created_at, q.id) < (p_cursor_at, p_cursor_id))
         ORDER BY q.created_at DESC, q.id DESC
         LIMIT LEAST(GREATEST(coalesce(p_limit, 30), 1), 50)
      ) m
  ), '[]'::jsonb);
END;
$$;


--
-- Name: get_my_withheld_pieces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_withheld_pieces() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The member's own pieces the house withholds, so every page of theirs marks each as withheld, never
  -- as if it stood public: which piece, the verdict that withholds it (its sheet opens from the mark),
  -- until when it is kept unappealed (none once an appeal is filed), and whether an appeal is filed.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'kind', w.kind, 'piece_id', w.piece_id, 'verdict_id', w.mod_action_id,
           'appeal_by', w.delete_after, 'appealed', m.appeal IS NOT NULL)
           ORDER BY w.withheld_at, w.mod_action_id), '[]'::jsonb)
    FROM public.withheld_pieces w
    JOIN public.mod_actions m ON m.id = w.mod_action_id
   WHERE w.author_id = (SELECT auth.uid()) AND (SELECT auth.uid()) IS NOT NULL
$$;


--
-- Name: get_pending_appeals(timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_appeals(p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;

  -- Oldest first, as a court hears them: a page at a time, keyset on the moment filed and the verdict.
  -- Asked of the partial index mod_actions_appeals_waiting (H-B6.index), never every verdict.
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'id', m.id,
             'action', m.action,
             'reason', m.reason,
             'created_at', m.created_at,
             'duration_hours', m.duration_hours,
             'expires_at', m.expires_at,
             'lifted_at', m.lifted_at,
             'appeal', m.appeal,
             'appeal_filed_at', m.appeal_filed_at,
             -- The one who ruled may not hear it: the screen says so, and the house refuses it.
             'ruled_by_you', m.admin_id IS NOT DISTINCT FROM v_admin_id,
             -- Why this moderator may not hear it (the one who ruled, or the member it is about), or none.
             'refused', private.a_judge_is_refused(v_admin_id, m.admin_id, m.target_user_id),
             -- No moderator of the house may hear it yet: it waits for another to be appointed.
             'no_moderator_yet', NOT private.an_appeal_may_be_heard(m.admin_id, m.target_user_id),
             'ruled_by', (SELECT a.username FROM public.profiles a WHERE a.id = m.admin_id),
             'member', jsonb_build_object('id', t.id, 'username', t.username, 'avatar_url', t.avatar_url,
                         'is_banned', coalesce(t.is_banned, false),
                         'exiled', coalesce(t.is_banned, false) AND coalesce(t.suspension_reason, '') LIKE 'PERMANENT EXILE:%',
                         'suspended_until', CASE WHEN t.suspended_until > now() THEN t.suspended_until END),
             'case', (SELECT jsonb_build_object('content_type', r.content_type, 'reason', r.reason, 'details', r.details)
                        FROM public.reports r WHERE r.id = m.report_id),
             'removed', CASE WHEN m.action = 'delete_content' AND m.content_snapshot IS NOT NULL
                             THEN jsonb_strip_nulls(jsonb_build_object('title', m.content_snapshot ->> 'title', 'body', m.content_snapshot ->> 'body')) END,
             'restorable', (m.content_snapshot ? 'kept') OR EXISTS (SELECT 1 FROM public.withheld_pieces w WHERE w.mod_action_id = m.id),
             -- the piece withheld, kept whole until this hearing (H-B10)
             'withheld', EXISTS (SELECT 1 FROM public.withheld_pieces w WHERE w.mod_action_id = m.id))
           ORDER BY m.appeal_filed_at, m.id)
      FROM (
        SELECT * FROM public.mod_actions q
         WHERE q.appeal_status = 'pending'
           AND (p_cursor_at IS NULL OR (q.appeal_filed_at, q.id) > (p_cursor_at, p_cursor_id))
         ORDER BY q.appeal_filed_at, q.id
         LIMIT LEAST(GREATEST(coalesce(p_limit, 20), 1), 50)
      ) m
      LEFT JOIN public.profiles t ON t.id = m.target_user_id
  ), '[]'::jsonb);
END;
$$;


--
-- Name: get_priority_reports(integer, bigint, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_priority_reports(p_limit integer DEFAULT 20, p_cursor_count bigint DEFAULT NULL::bigint, p_cursor_created timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, content_id text, content_type text, reason text, details text, reporter_id uuid, target_user_id uuid, created_at timestamp with time zone, report_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH scored AS (
    SELECT
      r.id, r.content_id, r.content_type, r.reason, r.details,
      r.reporter_id, r.target_user_id, r.created_at,
      COUNT(*) OVER (PARTITION BY r.content_id) AS report_count
    FROM reports r
    WHERE r.status = 'pending'
  )
  SELECT
    s.id, s.content_id, s.content_type, s.reason, s.details,
    s.reporter_id, s.target_user_id, s.created_at, s.report_count
  FROM scored s
  WHERE
    p_cursor_count IS NULL
    OR s.report_count < p_cursor_count
    OR (s.report_count = p_cursor_count AND s.created_at > p_cursor_created)
    OR (s.report_count = p_cursor_count AND s.created_at = p_cursor_created
        AND s.id > p_cursor_id)
  ORDER BY s.report_count DESC, s.created_at ASC, s.id ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
END;
$$;


--
-- Name: get_profile_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_profile_counts(p_user_id uuid) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT json_build_object(
    -- A piece the house withholds is counted for its author alone (H-B10). The member's records are
    -- read once for both of their counts, and each question of the caller is asked once a call (an
    -- InitPlan each), never once a row.
    'logs_count',      CASE WHEN me.open THEN mine.logs ELSE 0 END,
    'ledger_count',    CASE WHEN me.open THEN mine.ledger ELSE 0 END,
    'watchlist_count', CASE WHEN me.open
                            THEN (SELECT COUNT(*) FROM watchlists WHERE user_id = p_user_id) ELSE 0 END,
    'vault_count',     CASE WHEN me.open
                            THEN (SELECT COUNT(*) FROM physical_archive WHERE user_id = p_user_id) ELSE 0 END,
    'lists_count',     CASE WHEN me.open
                            THEN (SELECT COUNT(*) FROM lists WHERE user_id = p_user_id
                                    AND ((is_private = false AND withheld_at IS NULL) OR user_id = me.id)) ELSE 0 END,
    -- Across a block the follows rule shows none of the member's follows, so none are counted.
    'followers_count', CASE WHEN me.across THEN 0 ELSE
                         (SELECT COUNT(*) FROM interactions i WHERE i.target_user_id = p_user_id AND i.type = 'follow'
                            AND NOT COALESCE(i.user_id = ANY (me.hidden), false)) END,
    'following_count', CASE WHEN me.across THEN 0 ELSE
                         (SELECT COUNT(*) FROM interactions i WHERE i.user_id = p_user_id AND i.type = 'follow'
                            AND NOT COALESCE(i.target_user_id = ANY (me.hidden), false)) END
  )
  FROM (SELECT (SELECT auth.uid()) AS id,
               (SELECT private.hidden_authors()) AS hidden,
               (SELECT private.can_view_user_data(p_user_id)) AS open,
               (SELECT COALESCE(auth.uid() IS DISTINCT FROM p_user_id
                        AND public.a_block_stands_between(auth.uid(), p_user_id), false)) AS across) me
  CROSS JOIN LATERAL (
    SELECT count(*) AS logs, count(*) FILTER (WHERE rating > 0 OR COALESCE(review, '') <> '') AS ledger
      FROM logs WHERE me.open AND user_id = p_user_id AND (withheld_at IS NULL OR user_id = me.id)
  ) mine;
$$;


--
-- Name: get_public_profile_analytics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_profile_analytics(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT CASE
    WHEN auth.uid() IS NULL OR NOT private.can_view_user_data(p_user_id)
      THEN '{"error": "forbidden"}'::jsonb
    ELSE (
      WITH user_logs AS MATERIALIZED (
        SELECT film_id, rating, status, view_count,
          physical_media IS NOT NULL AS on_media,
          length(review) > 20 AS reviewed,
          coalesce(watched_date, (created_at AT TIME ZONE 'UTC')::date) AS on_day,
          -- A year of one to four digits; anything else is not a year.
          CASE WHEN year ~ '^\d{1,4}$' THEN year::int END AS year_int,
          CASE WHEN is_autopsied = true THEN autopsy END AS autopsy
        FROM public.logs WHERE user_id = p_user_id
          -- a log the house withholds counts for its author alone (H-B10)
          AND (withheld_at IS NULL OR user_id = auth.uid())
      ),
      -- The films this member logged, each once, joined once.
      films_read AS MATERIALIZED (
        SELECT f.popularity, f.genres
        FROM (SELECT DISTINCT film_id FROM user_logs WHERE film_id > 0) mine
        JOIN public.films f ON f.id = mine.film_id
      ),
      stamps AS (
        SELECT
          COUNT(*) AS total_logs,
          COUNT(*) FILTER (WHERE year_int < 1960) AS pre_1960_count,
          COUNT(*) FILTER (WHERE rating = 5) AS perfect_ratings_count,
          bool_or(on_media) AS has_physical_media,
          bool_or(status = 'abandoned') AS has_abandoned,
          COUNT(DISTINCT (year_int / 10) * 10) FILTER (WHERE year_int IS NOT NULL) AS decades_logged_count,
          -- A rewatch is kept on its log; two logs of one film count too.
          -- (coalesce: a member with no logs has rewatched nothing, not "unknown".)
          (coalesce(bool_or(status = 'rewatched' OR coalesce(view_count, 1) > 1), false)
            OR EXISTS (SELECT 1 FROM user_logs GROUP BY film_id HAVING COUNT(*) > 1)) AS has_rewatched,
          COUNT(*) FILTER (WHERE reviewed) AS reviews_count,
          COUNT(*) FILTER (WHERE coalesce(rating, 0) <= 0) AS unrated_count,
          (SELECT coalesce(max(n), 0) FROM (
             SELECT COUNT(*) AS n FROM user_logs GROUP BY on_day
           ) days) AS busiest_day_count,
          -- Grouped, not sorted: COUNT(DISTINCT) sorted the whale's 20,000 genre names to find ~20.
          (SELECT COUNT(*) FROM (
             SELECT g FROM films_read, LATERAL unnest(films_read.genres) AS g
             WHERE g IS NOT NULL GROUP BY g
           ) kinds) AS genres_count
        FROM user_logs
      ),
      decades AS (
        SELECT (year_int / 10) * 10 AS decade, COUNT(*) AS c
        FROM user_logs WHERE year_int IS NOT NULL
        GROUP BY decade ORDER BY c DESC LIMIT 3
      ),
      -- The film page's obscurity mark (obscurityScore), for each film read.
      obscurity AS (
        SELECT
          round(avg(CASE WHEN popularity <= 0 THEN 99
                         ELSE greatest(2, least(99, round(100 - (log(greatest(popularity, 1)) / log(5000)) * 98)))
                    END)) AS obscurity_index,
          COUNT(*) AS obscurity_films
        FROM films_read
        WHERE popularity IS NOT NULL
      ),
      dna AS (
        SELECT
          AVG(rating) FILTER (WHERE rating > 0) AS avg_rating,
          (SELECT jsonb_agg(jsonb_build_object(d.decade::text || 's', d.c)) FROM decades d) AS top_decades,
          (SELECT o.obscurity_index FROM obscurity o) AS obscurity_index,
          (SELECT o.obscurity_films FROM obscurity o) AS obscurity_films
        FROM user_logs
      ),
      autopsies AS (
        SELECT
          AVG(CASE WHEN autopsy ? '_v'
                THEN COALESCE((autopsy->>'story')::numeric, (autopsy->>'screenplay')::numeric, (autopsy->>'script')::numeric)
                ELSE NULLIF(COALESCE(autopsy->>'story', autopsy->>'screenplay', autopsy->>'script')::numeric, 0)
              END) AS avg_story,
          AVG(CASE WHEN autopsy ? '_v'
                THEN COALESCE((autopsy->>'cinematography')::numeric, (autopsy->>'visuals')::numeric, (autopsy->>'acting')::numeric)
                ELSE NULLIF(COALESCE(autopsy->>'cinematography', autopsy->>'visuals', autopsy->>'acting')::numeric, 0)
              END) AS avg_cinematography,
          AVG(CASE WHEN autopsy ? '_v'
                THEN COALESCE((autopsy->>'sound')::numeric, (autopsy->>'score')::numeric, (autopsy->>'editing')::numeric)
                ELSE NULLIF(COALESCE(autopsy->>'sound', autopsy->>'score', autopsy->>'editing')::numeric, 0)
              END) AS avg_sound
        FROM user_logs WHERE autopsy IS NOT NULL
      )
      SELECT jsonb_build_object(
        'stamps', (SELECT to_jsonb(s.*) FROM stamps s),
        'dna', (SELECT to_jsonb(d.*) FROM dna d),
        'autopsy_math', (SELECT to_jsonb(a.*) FROM autopsies a)
      )
    )
  END;
$_$;


--
-- Name: get_report_evidence(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_report_evidence(p_report_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_id   uuid := auth.uid();
  v_type       text;
  v_content_id uuid;
  v_now        jsonb;
  v_reported   jsonb;
BEGIN
  -- ── Admin gate: identical to resolve_moderation_report_v2 ──
  -- Uses auth.uid() (canonical identity), never a caller-supplied param.
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- ── Resolve the report ──
  SELECT content_type, content_id
    INTO v_type, v_content_id
  FROM reports
  WHERE id = p_report_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  -- The piece as it stands now: destroyed when it is gone, as the verdict asks it.
  v_now := public.piece_as_it_stands(v_type, v_content_id);

  -- The words as they stood when the report was filed, kept by submit_report (none for a report
  -- filed before the house kept them: the evidence reads as it always did).
  SELECT words INTO v_reported FROM public.reported_words WHERE report_id = p_report_id;
  IF v_reported IS NULL THEN
    RETURN v_now;
  END IF;

  -- Changed: the piece still stands and its words (its name, picture, cover) are not those reported.
  -- Its address is left out: a page renamed is changed by its name already.
  RETURN v_now || jsonb_build_object(
    'reported', v_reported - 'route',
    'changed', coalesce((v_now ->> 'found')::boolean, false)
               AND (v_now - 'found' - 'route') IS DISTINCT FROM (v_reported - 'route'));
END;
$$;


--
-- Name: get_salon_last_words(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_salon_last_words(p_lounge_ids uuid[]) RETURNS TABLE(lounge_id uuid, last_message_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH me AS (SELECT auth.uid() AS id, (SELECT private.hidden_authors()) AS hidden)
  SELECT l.id, newest.created_at
    FROM me
    JOIN public.lounges l ON l.id = ANY (p_lounge_ids[1:100])
    CROSS JOIN LATERAL (
      SELECT m.created_at
        FROM public.lounge_messages m
       WHERE m.lounge_id = l.id
         AND NOT COALESCE(m.user_id = ANY (me.hidden), false)
         AND (m.user_id = me.id OR NOT COALESCE(m.carries_words_of && me.hidden, false))
       ORDER BY m.created_at DESC, m.id DESC
       LIMIT 1
    ) newest
   WHERE me.id IS NOT NULL;
$$;


--
-- Name: get_salon_member_faces(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_salon_member_faces(p_lounge_ids uuid[]) RETURNS TABLE(lounge_id uuid, username text, avatar_url text, rn integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH reader AS (SELECT (SELECT private.hidden_authors()) AS hidden)
  SELECT r.id, f.username, f.avatar_url, f.rn::integer
  FROM reader
  CROSS JOIN (SELECT DISTINCT x.id FROM unnest(p_lounge_ids) AS x(id)) r
  CROSS JOIN LATERAL (
    SELECT first3.username, first3.avatar_url,
           row_number() OVER (ORDER BY first3.joined_at, first3.user_id) AS rn
    FROM (
      SELECT lm.user_id, lm.joined_at, p.username, p.avatar_url
      FROM public.lounge_members lm
      JOIN public.profiles p ON p.id = lm.user_id
      WHERE lm.lounge_id = r.id
        AND lm.status = 'approved'
        AND p.username IS NOT NULL
        AND NOT COALESCE(lm.user_id = ANY (reader.hidden), false)
      ORDER BY lm.joined_at ASC, lm.user_id ASC
      LIMIT 3
    ) first3
  ) f
  WHERE EXISTS (SELECT 1 FROM public.lounge_members me
                WHERE me.lounge_id = r.id AND me.user_id = auth.uid() AND me.status = 'approved')
     OR auth.uid() = (SELECT l.creator_id FROM public.lounges l WHERE l.id = r.id)
  ORDER BY r.id, f.rn;
$$;


--
-- Name: get_sanctioned_members(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sanctioned_members(p_cursor_name text DEFAULT NULL::text, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;

  -- By handle, a page at a time (keyset on the handle and the id): the list an admin reads to lift.
  -- Asked of the partial index profiles_under_sanction (H-B2.index), never every member.
  RETURN coalesce((
    SELECT jsonb_agg(jsonb_build_object(
             'id', p.id, 'username', p.username, 'avatar_url', p.avatar_url,
             'is_banned', coalesce(p.is_banned, false),
             'exiled', coalesce(p.is_banned, false) AND coalesce(p.suspension_reason, '') LIKE 'PERMANENT EXILE:%',
             'suspended_until', CASE WHEN p.suspended_until > now() THEN p.suspended_until END,
             'reason', p.suspension_reason,
             'since', p.banned_at)
           ORDER BY lower(coalesce(p.username, '')), p.id)
      FROM (
        SELECT * FROM public.profiles q
         WHERE (q.is_banned OR q.suspended_until IS NOT NULL)
           AND (coalesce(q.is_banned, false) OR q.suspended_until > now())
           AND (p_cursor_name IS NULL OR (lower(coalesce(q.username, '')), q.id) > (lower(p_cursor_name), p_cursor_id))
         ORDER BY lower(coalesce(q.username, '')), q.id
         LIMIT LEAST(GREATEST(coalesce(p_limit, 30), 1), 50)
      ) p
  ), '[]'::jsonb);
END;
$$;


--
-- Name: get_taste_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_taste_match(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN auth.uid() IS NULL OR NOT private.can_view_user_data(p_user_id)
      THEN '{"error": "forbidden"}'::jsonb
    ELSE jsonb_build_object('mine', public.taste_shape(auth.uid()), 'theirs', public.taste_shape(p_user_id))
  END;
$$;


--
-- Name: get_taste_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_taste_profile(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  result JSON;
BEGIN
  IF NOT private.can_view_user_data(p_user_id) THEN
    RETURN json_build_object('error', 'forbidden');
  END IF;

  WITH mine AS (
    SELECT DISTINCT l.film_id
      FROM public.logs l
     WHERE l.user_id = p_user_id AND l.film_id > 0
       -- a log the house withholds counts for its author alone (H-B10)
       AND (l.withheld_at IS NULL OR l.user_id = auth.uid())
  ),
  known AS (
    SELECT f.*
      FROM public.films f
      JOIN mine m ON m.film_id = f.id
     WHERE f.synced_at IS NOT NULL
  )
  SELECT json_build_object(
    'films_total', (SELECT COUNT(*) FROM mine),
    -- Known once read with its details (genres, director, cast), or read once it had settled after
    -- its release; read before the house counted, settled when its year is before 2026. Unknown:
    -- read only before it settled, so its details may still come.
    'films_known', (SELECT COUNT(*) FROM known
                     WHERE (cardinality(known.genres) > 0 AND known.director_id IS NOT NULL AND cardinality(known.cast_ids) > 0)
                        OR known.sync_reads >= 1
                        OR (known.sync_reads IS NULL AND known.year < 2026)),

    'genres', (
      SELECT COALESCE(json_agg(row_to_json(g)), '[]'::json) FROM (
        SELECT genre AS name, COUNT(*) AS count
          FROM known, LATERAL unnest(known.genres) AS genre
         GROUP BY genre
         ORDER BY count DESC, genre
         LIMIT 12
      ) g
    ),

    'actors', (
      SELECT COALESCE(json_agg(row_to_json(a)), '[]'::json) FROM (
        SELECT p.id,
               MAX(p.name) AS name,
               MAX(p.profile) AS profile_path,
               COUNT(*) AS count
          FROM known,
               LATERAL unnest(known.cast_ids, known.cast_names, known.cast_profiles)
                    AS p(id, name, profile)
         WHERE p.id IS NOT NULL AND p.name IS NOT NULL AND p.name <> ''
         GROUP BY p.id
         ORDER BY count DESC, name
         LIMIT 10
      ) a
    ),

    'directors', (
      SELECT COALESCE(json_agg(row_to_json(d)), '[]'::json) FROM (
        SELECT director_id AS id,
               MAX(director) AS name,
               MAX(director_profile) AS profile_path,
               COUNT(*) AS count
          FROM known
         WHERE director_id IS NOT NULL AND director IS NOT NULL AND director <> ''
         GROUP BY director_id
         ORDER BY count DESC, name
         LIMIT 10
      ) d
    ),

    'countries', (
      SELECT COALESCE(json_agg(row_to_json(c)), '[]'::json) FROM (
        SELECT code, COUNT(*) AS count
          FROM known, LATERAL unnest(known.country_codes) AS code
         GROUP BY code
         ORDER BY count DESC, code
         LIMIT 20
      ) c
    ),

    'total_runtime', (SELECT COALESCE(SUM(runtime), 0) FROM known WHERE runtime > 0)
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_user_analytics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_analytics(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  result JSON;
  v_vault JSON := '[]'::json;
  v_decades JSON := '[]'::json;
BEGIN
  -- The check the other two functions already had. This one had none.
  IF NOT private.can_view_user_data(p_user_id) THEN
    RETURN json_build_object('error', 'forbidden');
  END IF;

  -- The two NEW fields, where a failure cannot reach the rest of the payload.
  BEGIN
    SELECT COALESCE(json_agg(row_to_json(vf)), '[]'::json) INTO v_vault
    FROM (
      SELECT COALESCE(f, 'unfiled') AS format, COUNT(*) AS count
      FROM physical_archive pa
      LEFT JOIN LATERAL unnest(NULLIF(pa.formats, '{}')) AS f ON TRUE
      WHERE pa.user_id = p_user_id
      GROUP BY 1 ORDER BY count DESC
    ) vf;
  EXCEPTION WHEN OTHERS THEN v_vault := '[]'::json;
  END;

  BEGIN
    SELECT COALESCE(json_agg(row_to_json(wd)), '[]'::json) INTO v_decades
    FROM (
      -- {1,4} not + : an unbounded pattern accepts a 20-digit string and the
      -- int cast then raises 22003, aborting everything.
      SELECT ((year::text)::int / 10) * 10 AS decade, COUNT(*) AS count
      FROM watchlists
      WHERE user_id = p_user_id
        AND year::text ~ '^\d{1,4}$'
        AND (year::text)::int > 0
      GROUP BY 1 ORDER BY 1 DESC
    ) wd;
  EXCEPTION WHEN OTHERS THEN v_decades := '[]'::json;
  END;

  -- The member's records, read once (a withheld one its author's alone): every figure below is
  -- counted from this one read, never from the records read again.
  WITH mine AS MATERIALIZED (
    SELECT l.rating, l.format, l.watched_date, l.created_at, l.viewing_history
      FROM logs l
     WHERE l.user_id = p_user_id AND (l.withheld_at IS NULL OR l.user_id = auth.uid())
  ),
  -- The nights a member saw a film, as member_viewings reads them: every viewing's day, a rewatched
  -- film's earlier viewings among them. A run is consecutive days; date - row_number holds still
  -- along one, read ascending.
  --   current_streak: the run reaching the house's today or yesterday, as before, for the builds
  --     that read it.
  --   current_run: the newest run whole, its length and its last day, for the phone to judge on
  --     its own calendar (the house's day is not the member's). A day past the house's tomorrow
  --     is today nowhere, so a run ending after it is not the newest one.
  --   monthly_viewings: the viewings of each month, `YYYY-MM`.
  viewed AS (
    SELECT m.watched_date AS day FROM mine m
    UNION ALL
    SELECT COALESCE(CASE WHEN e->>'date' ~ '^\d{4}-\d{2}-\d{2}' AND pg_input_is_valid(left(e->>'date', 10), 'date')
                         THEN left(e->>'date', 10)::date END,
                    m.created_at::date)
      FROM mine m
     CROSS JOIN LATERAL jsonb_array_elements(
             CASE WHEN jsonb_typeof(m.viewing_history) = 'array' THEN m.viewing_history ELSE '[]'::jsonb END) AS e
     WHERE jsonb_typeof(e) = 'object'
  ),
  streak AS (
    SELECT d.day, d.day - (ROW_NUMBER() OVER (ORDER BY d.day))::int AS grp
    FROM (SELECT DISTINCT day FROM viewed) d
  ),
  runs AS (
    SELECT COUNT(*)::int AS len, MAX(day) AS ends_on FROM streak GROUP BY grp
  )
  SELECT json_build_object(
    'total_logs', (SELECT COUNT(*) FROM mine),
    'avg_rating', (SELECT COALESCE(ROUND(AVG(rating)::numeric, 2), 0) FROM mine WHERE rating > 0),
    'rating_distribution', (
      SELECT COALESCE(json_agg(row_to_json(rd)), '[]'::json) FROM (
        SELECT rating, COUNT(*) as count FROM mine
        WHERE rating > 0
        GROUP BY rating ORDER BY rating) rd),

    -- The Archive's records by the month each is filed under, as its headings count the posters
    -- beneath them.
    'monthly_activity', (
      SELECT COALESCE(json_agg(row_to_json(ma)), '[]'::json) FROM (
        SELECT TO_CHAR(COALESCE(watched_date::date, created_at::date), 'YYYY-MM') as month,
               COUNT(*) as count
        FROM mine
        GROUP BY month ORDER BY month DESC) ma),

    'current_streak', COALESCE((SELECT r.len FROM runs r WHERE r.ends_on >= CURRENT_DATE - 1 ORDER BY r.ends_on DESC LIMIT 1), 0),
    'longest_streak', COALESCE((SELECT MAX(r.len) FROM runs r), 0),
    'current_run', (SELECT json_build_object('length', r.len, 'ends_on', r.ends_on)
                      FROM runs r WHERE r.ends_on <= CURRENT_DATE + 1 ORDER BY r.ends_on DESC LIMIT 1),
    'monthly_viewings', (SELECT COALESCE(json_agg(row_to_json(mv)), '[]'::json) FROM (
                           SELECT TO_CHAR(day, 'YYYY-MM') AS month, COUNT(*) AS count
                           FROM viewed GROUP BY 1 ORDER BY 1 DESC) mv),

    -- this is logs.format, how a film was watched — NOT the Vault
    'format_breakdown', (
      SELECT COALESCE(json_agg(row_to_json(fb)), '[]'::json) FROM (
        SELECT format, COUNT(*) as count FROM mine
        WHERE format IS NOT NULL AND format != ''
        GROUP BY format ORDER BY count DESC) fb),

    'vault_formats', v_vault,
    'watchlist_decades', v_decades
  ) INTO result
  FROM (SELECT 1) one;

  RETURN result;
END;
$_$;


--
-- Name: get_user_blocks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_blocks(p_user_id uuid) RETURNS TABLE(blocked_id uuid, type text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- p_user_id is deliberately ignored; a member may only sync their own list.
  SELECT ub.blocked_id, ub.type, ub.created_at
  FROM public.user_blocks ub
  WHERE ub.blocker_id = auth.uid()
  ORDER BY ub.created_at DESC;
$$;


--
-- Name: give_back_withheld_piece(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_back_withheld_piece(p_action_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  w      public.withheld_pieces%ROWTYPE;
  v_film integer;
  v_parent uuid;
  v_rows integer := 0;
BEGIN
  SELECT * INTO w FROM public.withheld_pieces WHERE mod_action_id = p_action_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- The withholding lifted; everything never touched (its critiques, films, marks, cards) returns with it.
  IF w.kind = 'log' THEN
    UPDATE public.logs SET withheld_at = NULL WHERE id = w.piece_id AND withheld_at IS NOT NULL RETURNING film_id INTO v_film;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows > 0 THEN PERFORM public.refresh_film_verdict(v_film); END IF;
  ELSIF w.kind = 'list' THEN
    UPDATE public.lists SET withheld_at = NULL WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
  ELSIF w.kind = 'log_comment' THEN
    UPDATE public.log_comments SET withheld_at = NULL WHERE id = w.piece_id AND withheld_at IS NOT NULL RETURNING log_id INTO v_parent;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows > 0 THEN
      INSERT INTO public.log_counts AS c (log_id, critique_count) VALUES (v_parent, 1)
        ON CONFLICT (log_id) DO UPDATE SET critique_count = c.critique_count + 1;
    END IF;
  ELSIF w.kind = 'list_comment' THEN
    UPDATE public.list_comments SET withheld_at = NULL WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
  ELSIF w.kind = 'dispatch_comment' THEN
    UPDATE public.dispatch_comments SET withheld_at = NULL WHERE id = w.piece_id AND withheld_at IS NOT NULL RETURNING post_id INTO v_parent;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows > 0 THEN UPDATE public.dispatch_posts SET comment_count = comment_count + 1 WHERE id = v_parent; END IF;
  ELSIF w.kind = 'dispatch_post' THEN
    UPDATE public.dispatch_posts SET withheld_at = NULL WHERE id = w.piece_id AND withheld_at IS NOT NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
  END IF;

  -- The notices set aside, written back as they were: their moment, whether read, and as already pushed
  -- (the push service claims only a fresh notice not yet pushed), so no phone is told of it twice. One
  -- whose member has gone, or now hides its sender, is not written (the notices' own gate refuses it).
  IF v_rows > 0 THEN
    -- Its cards, made again from it as it stands now.
    PERFORM private.a_withheld_piece_turns_its_cards(w.kind, w.piece_id, false);
    INSERT INTO public.notifications
    SELECT (jsonb_populate_record(NULL::public.notifications,
              x.notice || jsonb_build_object('pushed_at', coalesce(x.notice ->> 'pushed_at', now()::text)))).*
      FROM jsonb_array_elements(w.notices) AS x(notice)
     WHERE EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = (x.notice ->> 'user_id')::uuid)
    ON CONFLICT (id) DO NOTHING;
  END IF;

  DELETE FROM public.withheld_pieces WHERE mod_action_id = p_action_id;
  RETURN v_rows > 0;
END;
$$;


--
-- Name: grant_entitlement(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_entitlement(p_user_id uuid, p_tier text, p_source text) RETURNS TABLE(out_role text, out_tier text, out_source text, out_applied boolean, out_reason text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_grant text; v_before text; v_founding boolean;
  v_top_tier text; v_top_src text; v_in_force text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'grant_entitlement: user id is required' USING ERRCODE = '22023';
  END IF;
  IF p_tier IS NULL OR p_tier NOT IN ('cinephile','archivist','auteur','founding') THEN
    RAISE EXCEPTION 'grant_entitlement: unknown tier %', coalesce(p_tier,'<null>') USING ERRCODE = '22023';
  END IF;
  IF p_source IS NULL OR p_source NOT IN ('revenuecat','paytabs','manual') THEN
    RAISE EXCEPTION 'grant_entitlement: unknown source %', coalesce(p_source,'<null>') USING ERRCODE = '22023';
  END IF;

  -- One writer at a time per member: the profile row is the lock.
  SELECT coalesce(p.is_founding, false) INTO v_founding
    FROM public.profiles p WHERE p.id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'grant_entitlement: no profile with id %', p_user_id USING ERRCODE = 'P0002';
  END IF;

  -- This source's grant; 'cinephile' means it grants nothing. 'founding' says the
  -- source bought a seat; the seat itself is claim_founding_seat's.
  v_grant := CASE p_tier WHEN 'cinephile' THEN NULL ELSE p_tier END;
  SELECT g.tier INTO v_before FROM public.rank_grants g WHERE g.user_id = p_user_id AND g.source = p_source;
  IF v_grant IS NULL THEN
    DELETE FROM public.rank_grants WHERE user_id = p_user_id AND source = p_source;
  ELSE
    INSERT INTO public.rank_grants (user_id, source, tier) VALUES (p_user_id, p_source, v_grant)
    ON CONFLICT (user_id, source) DO UPDATE SET tier = EXCLUDED.tier, granted_at = now()
      WHERE public.rank_grants.tier IS DISTINCT FROM EXCLUDED.tier;
  END IF;

  -- The seat this source bought, held by no source any longer, goes back to the hundred.
  IF v_founding AND v_before = 'founding' AND v_grant IS DISTINCT FROM 'founding'
     AND NOT EXISTS (SELECT 1 FROM public.rank_grants g WHERE g.user_id = p_user_id AND g.tier = 'founding') THEN
    UPDATE public.founding_seat_counter SET seats_claimed = GREATEST(seats_claimed - 1, 0) WHERE id = 1;
    UPDATE public.profiles SET is_founding = false WHERE id = p_user_id;
    v_founding := false;
  END IF;

  -- The rank in force: the highest grant, the house's own hand first among equals.
  -- The column holds a founding grant as the Auteur; the seat is is_founding's to show.
  SELECT g.tier, g.source INTO v_top_tier, v_top_src
    FROM public.rank_grants g WHERE g.user_id = p_user_id
   ORDER BY public.tier_weight(g.tier) DESC,
            CASE g.source WHEN 'manual' THEN 0 WHEN 'revenuecat' THEN 1 ELSE 2 END
   LIMIT 1;
  v_in_force := CASE
    WHEN v_top_tier = 'founding' THEN 'auteur'
    WHEN v_founding AND public.tier_weight(v_top_tier) < 2 THEN 'auteur'
    ELSE coalesce(v_top_tier, 'cinephile') END;


  -- A store's grant that rose is a rank bought, one that ended a rank given up: counted by the house,
  -- from its own record (round 14). A renewal or a retried webhook (the grant unchanged) and a rank
  -- given by hand count nothing. Counted at no door: the door is the phone's alone to know.
  IF p_source IN ('revenuecat', 'paytabs') THEN
    IF v_grant IS NOT NULL AND public.tier_weight(v_grant) > public.tier_weight(coalesce(v_before, 'cinephile')) THEN
      PERFORM public.a_rank_is_counted('rank_purchased', CASE WHEN v_grant IN ('auteur', 'founding') THEN 'auteur' ELSE 'archivist' END);
    ELSIF v_grant IS NULL AND v_before IS NOT NULL THEN
      PERFORM public.a_rank_is_counted('rank_relinquished', '');
    END IF;
  END IF;
  RETURN QUERY
  UPDATE public.profiles p
     SET role = CASE WHEN p.role = 'admin' THEN p.role ELSE v_in_force END,
         tier = v_in_force,
         -- A rank that has ended keeps the name of the source that held it last:
         -- that is how the app knows a member as "lapsed", not a stranger.
         entitlement_source = coalesce(v_top_src, p.entitlement_source, CASE WHEN v_before IS NOT NULL THEN p_source END)
   WHERE p.id = p_user_id
  RETURNING p.role, p.tier, p.entitlement_source, v_before IS DISTINCT FROM v_grant,
            format('%s: %s -> %s; in force %s', p_source, coalesce(v_before, 'none'), coalesce(v_grant, 'none'), v_in_force);
END;
$$;


--
-- Name: handle_follow_count_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_follow_count_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ BEGIN IF TG_OP = 'INSERT' AND NEW.type = 'follow' THEN UPDATE public.profiles SET following_count = following_count + 1 WHERE id = NEW.user_id; UPDATE public.profiles SET followers_count = followers_count + 1 WHERE id = NEW.target_user_id; ELSIF TG_OP = 'DELETE' AND OLD.type = 'follow' THEN UPDATE public.profiles SET following_count = GREATEST(0, following_count - 1) WHERE id = OLD.user_id; UPDATE public.profiles SET followers_count = GREATEST(0, followers_count - 1) WHERE id = OLD.target_user_id; END IF; RETURN COALESCE(NEW, OLD); END; $$;


--
-- Name: handle_is_unwelcome(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_is_unwelcome(p_handle text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  WITH r AS (SELECT translate(lower(coalesce(p_handle, '')), '013457', 'oieast') AS s)
  SELECT r.s ~ 'n+i+g+g+(e+r|a+|u+h)|f+a+g+g*o+t|w+e+t+b+a+c+k|f+u+c+k|b+i+t+c+h|w+h+o+r+e|a+s+s+h+o+l+e'
      OR EXISTS (
           SELECT 1 FROM regexp_split_to_table(r.s, '[^a-z]+') AS w(word)
            WHERE w.word = ANY (ARRAY['pussy', 'pussies', 'slut', 'sluts', 'slutty', 'retard', 'retards', 'retarded', 'kike', 'kikes', 'spic', 'spics', 'chink', 'chinks', 'tranny', 'trannies'])
               OR w.word ~ '^(shit|cunt)'
               OR w.word ~ '(shit|cunt)$')
  FROM r;
$_$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, username, role, email, preferences)
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1)),
    CASE WHEN NEW.raw_user_meta_data->>'role' = 'venue_owner' THEN 'venue_owner' ELSE 'cinephile' END,
    NEW.email,
    '{}'::JSONB
  )
  ON CONFLICT (id) DO UPDATE SET email = EXCLUDED.email, updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: handle_privacy_switch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_privacy_switch() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_updated_user_ids UUID[];
    v_count INT;
BEGIN
    -- If switching from Private (true) to Public (false)
    IF OLD.is_social_private = true AND NEW.is_social_private = false THEN
        
        -- 1. Bulk update interactions and capture the affected user_ids
        WITH updated AS (
            UPDATE public.interactions 
            SET type = 'follow' 
            WHERE target_user_id = NEW.id AND type = 'follow_request'
            RETURNING user_id
        )
        SELECT array_agg(user_id), count(*) INTO v_updated_user_ids, v_count
        FROM updated;

        IF v_count > 0 THEN
            -- 2. Increment target user's followers_count atomically in memory
            NEW.followers_count := COALESCE(NEW.followers_count, 0) + v_count;
            
            -- 3. Bulk increment following_count for all requesters
            UPDATE public.profiles 
            SET following_count = COALESCE(following_count, 0) + 1 
            WHERE id = ANY(v_updated_user_ids);
            
            -- 4. Bulk insert acceptance notifications
            INSERT INTO public.notifications (user_id, type, from_username, from_user_id, message)
            SELECT u_id, 'follow_accept', NEW.username, NEW.id, 'accepted your follow request. You can now view their archive.'
            FROM unnest(v_updated_user_ids) AS u_id;
            
            -- 5. Bulk delete the pending request notifications for the target user
            DELETE FROM public.notifications 
            WHERE user_id = NEW.id AND type = 'follow_request' AND from_user_id = ANY(v_updated_user_ids);
        END IF;
        
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: handle_user_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_user_deletion() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  DELETE FROM public.logs WHERE user_id = OLD.id;
  DELETE FROM public.watchlists WHERE user_id = OLD.id;
  DELETE FROM public.lists WHERE user_id = OLD.id;
  DELETE FROM public.interactions WHERE user_id = OLD.id;
  DELETE FROM public.notifications WHERE user_id = OLD.id;
  DELETE FROM public.profiles WHERE id = OLD.id;
  RETURN OLD;
END;
$$;


