--
-- Name: is_lounge_member_or_host(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_lounge_member_or_host(_lounge_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.lounges
    WHERE id = _lounge_id AND creator_id = auth.uid()
  ) OR EXISTS (
    SELECT 1 FROM public.lounge_members
    WHERE lounge_id = _lounge_id AND user_id = auth.uid() AND status IN ('approved', 'muted')
  );
$$;


--
-- Name: is_user_not_banned(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_user_not_banned() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT NOT EXISTS (
    SELECT 1 FROM public.profiles
     WHERE id = auth.uid()
       AND (is_banned = true
            OR (suspended_until IS NOT NULL AND suspended_until > now()))
  );
$$;


--
-- Name: FUNCTION is_user_not_banned(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_user_not_banned() IS 'TRUE when the caller may write. FALSE if banned OR serving an unexpired suspension. Named for the ten policies that reference it; the meaning is "not restricted". Widening this made Tribunal suspend/mute enforceable at all.';


--
-- Name: join_public_lounge(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_public_lounge(p_lounge_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_private boolean; v_sanction text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT is_private INTO v_private FROM public.lounges WHERE id = p_lounge_id;
  -- Gone (dissolved by its host): said as gone, never as a failure of the member's signal.
  IF v_private IS NULL THEN RAISE EXCEPTION 'SALON_GONE' USING ERRCODE = 'P0002'; END IF;
  IF v_private THEN RAISE EXCEPTION 'This lounge is private — request to join'; END IF;
  SELECT status INTO v_sanction FROM public.lounge_sanctions WHERE lounge_id = p_lounge_id AND user_id = auth.uid();
  IF v_sanction = 'banned' THEN RAISE EXCEPTION 'You cannot join this lounge'; END IF;
  INSERT INTO public.lounge_members (lounge_id, user_id, status)
  VALUES (p_lounge_id, auth.uid(), COALESCE(v_sanction, 'approved'))
  ON CONFLICT (user_id, lounge_id) DO UPDATE SET status = EXCLUDED.status
    WHERE public.lounge_members.status <> 'banned';
END $$;


--
-- Name: judge_appeal(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.judge_appeal(p_action_id uuid, p_outcome text, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_admin_id uuid := auth.uid();
  -- The Tribunal's word, cleaned as a member's words are (clean_member_text): kept on the verdict and
  -- told to the member in their notice.
  v_note     text := btrim(coalesce(public.clean_member_text(p_note), ''));
  m          public.mod_actions%ROWTYPE;
  v_snap     jsonb;
  v_kept     jsonb;
  v_type     text;
  v_id       uuid;
  v_rows     integer := 0;
  v_effect   text := '';
  v_notice   text;
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;
  IF p_outcome IS NULL OR p_outcome NOT IN ('upheld', 'overturned') THEN
    RAISE EXCEPTION 'An appeal is upheld or overturned.' USING ERRCODE = 'P0001';
  END IF;
  IF char_length(v_note) = 0 OR char_length(v_note) > 500 THEN
    RAISE EXCEPTION 'A word for the member of up to 500 characters is required.' USING ERRCODE = 'P0001';
  END IF;

  -- Held while it is heard: a second moderator hearing it at the same moment waits, then is refused.
  SELECT * INTO m FROM public.mod_actions WHERE id = p_action_id FOR UPDATE;
  IF NOT FOUND OR m.appeal IS NULL THEN
    RAISE EXCEPTION 'VERDICT_GONE' USING ERRCODE = 'P0002';
  END IF;
  IF m.appeal_status IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'ALREADY_JUDGED' USING ERRCODE = 'P0002';
  END IF;
  -- The owner's rule (a_judge_is_refused, the house's one rule of who may judge a case): the one who
  -- ruled never hears the appeal of their own verdict, nor does the member the verdict is about.
  IF private.a_judge_is_refused(v_admin_id, m.admin_id, m.target_user_id) IS NOT NULL THEN
    RAISE EXCEPTION '%', private.a_judge_is_refused(v_admin_id, m.admin_id, m.target_user_id) USING ERRCODE = '42501';
  END IF;

  UPDATE public.mod_actions
     SET appeal_status = p_outcome, appeal_judged_by = v_admin_id, appeal_judged_at = now(), appeal_note = v_note
   WHERE id = p_action_id;

  IF p_outcome = 'overturned' THEN
    -- Struck: the verdict no longer holds the member's standing, and the record says so.
    UPDATE public.mod_actions
       SET lifted_at = now(), lifted_by = v_admin_id, lift_reason = 'Overturned on appeal: ' || v_note
     WHERE id = p_action_id AND lifted_at IS NULL;

    IF m.action = 'warn' AND m.target_user_id IS NOT NULL THEN
      -- The warning it wrote (in the verdict's own moment) is withdrawn, and the count with it.
      DELETE FROM public.warnings
       WHERE id = (SELECT w.id FROM public.warnings w
                    WHERE w.user_id = m.target_user_id AND w.reason = m.reason AND w.created_at = m.created_at
                    ORDER BY w.id LIMIT 1);
      UPDATE public.profiles SET warning_count = GREATEST(coalesce(warning_count, 0) - 1, 0) WHERE id = m.target_user_id;
      v_effect := 'The warning is withdrawn.';

    ELSIF m.action IN ('suspend', 'mute_user') AND m.target_user_id IS NOT NULL THEN
      PERFORM public.standing_from_verdicts(m.target_user_id, 'suspension');
      v_effect := 'The pause it set no longer holds.';

    ELSIF m.action IN ('ban', 'permanent_exile') AND m.target_user_id IS NOT NULL THEN
      PERFORM public.standing_from_verdicts(m.target_user_id, 'ban');
      v_effect := 'The closing it set no longer holds.';

    ELSIF m.action = 'delete_content' AND EXISTS (SELECT 1 FROM public.withheld_pieces w WHERE w.mod_action_id = m.id) THEN
      -- Withheld (H-B10): given back whole, its critiques, marks, cards, counts and notices with it.
      -- Deleted meanwhile by its own author, there is nothing left to give back.
      IF public.give_back_withheld_piece(m.id) THEN
        v_rows := 1;
        v_effect := 'What it removed stands again where it was, whole, as it stood.';
      ELSE
        v_effect := 'What it removed is no longer in the house: you deleted it meanwhile.';
      END IF;

    ELSIF m.action = 'delete_content' THEN
      -- Put back where its row still stands, and only as the house left it (never over what its
      -- author has written since).
      v_snap := coalesce(m.content_snapshot, '{}'::jsonb);
      v_kept := v_snap -> 'kept';
      v_type := coalesce(v_snap ->> 'type', (SELECT r.content_type FROM public.reports r WHERE r.id = m.report_id));
      v_id := coalesce(
        CASE WHEN (v_snap ->> 'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (v_snap ->> 'id')::uuid END,
        (SELECT CASE WHEN r.content_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN r.content_id::uuid END
           FROM public.reports r WHERE r.id = m.report_id));
      IF v_type = 'lounge_message' AND coalesce(v_kept ->> 'content', v_snap ->> 'body') IS NOT NULL THEN
        UPDATE public.lounge_messages
           SET content = coalesce(v_kept ->> 'content', v_snap ->> 'body'), deleted_at = NULL
         WHERE id = v_id AND deleted_at IS NOT NULL AND content = '';
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        -- Whole: the replies that quoted it have their quotes back, as the withdrawal took them.
        IF v_rows > 0 THEN
          UPDATE public.lounge_messages r SET reply_to_content = coalesce(v_kept ->> 'content', v_snap ->> 'body')
           WHERE r.reply_to_id = v_id AND r.reply_to_content IS NULL;
        END IF;
      ELSIF v_type IN ('dispatch_post', 'dossier') AND v_kept IS NOT NULL THEN
        UPDATE public.dispatch_posts
           SET body = coalesce(v_kept ->> 'body', ''), full_content = v_kept ->> 'full_content', title = v_kept ->> 'title',
               subject_image = v_kept ->> 'subject_image', subject_backdrop = v_kept ->> 'subject_backdrop',
               source = v_kept ->> 'source', source_url = v_kept ->> 'source_url', spoiler_label = v_kept ->> 'spoiler_label',
               ended_at = NULL, ended_by = NULL
         WHERE id = v_id AND ended_by = 'house';
        GET DIAGNOSTICS v_rows = ROW_COUNT;
      ELSIF v_type = 'profile' AND v_kept IS NOT NULL THEN
        UPDATE public.profiles
           SET bio = coalesce(bio, v_kept ->> 'bio'),
               display_name = coalesce(display_name, v_kept ->> 'display_name'),
               avatar_url = coalesce(avatar_url, v_kept ->> 'avatar_url'),
               social_links = CASE WHEN social_links IS NULL OR social_links = '{}'::jsonb THEN coalesce(v_kept -> 'social_links', '{}'::jsonb) ELSE social_links END
         WHERE id = v_id;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
      ELSIF v_type = 'lounge' AND v_kept IS NOT NULL THEN
        UPDATE public.lounges
           SET name = CASE WHEN name = 'An Unnamed Salon' THEN coalesce(v_kept ->> 'name', name) ELSE name END,
               description = CASE WHEN coalesce(description, '') = '' THEN coalesce(v_kept ->> 'description', '') ELSE description END,
               cover_image = coalesce(cover_image, v_kept ->> 'cover_image')
         WHERE id = v_id;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
      END IF;
      v_effect := CASE WHEN v_rows > 0 THEN 'What it removed stands again where it was.'
                       ELSE 'What it removed is kept for you with the verdict, to file again.' END;
    END IF;
    -- What the overturn did, kept on the verdict for the member's sheet: put back where it stood, or not.
    IF m.action = 'delete_content' THEN
      UPDATE public.mod_actions SET appeal_put_back = (v_rows > 0) WHERE id = p_action_id;
    END IF;
  ELSIF m.action = 'delete_content' THEN
    -- Upheld: a piece withheld for this hearing is deleted now, as REMOVE CONTENT deleted it before (H-B10).
    IF public.delete_withheld_piece(m.id) THEN
      v_effect := 'The piece it withheld is now deleted.';
    END IF;
  END IF;

  IF m.target_user_id IS NOT NULL THEN
    v_notice := CASE p_outcome
      WHEN 'upheld' THEN 'The Tribunal has heard your appeal and upholds the verdict.' || CASE WHEN v_effect <> '' THEN ' ' || v_effect ELSE '' END
      ELSE 'The Tribunal has heard your appeal and overturns the verdict: it is struck from your record. ' || v_effect
    END || ' The Tribunal''s word: ' || v_note;
    INSERT INTO public.notifications (user_id, type, title, body, message, metadata)
    VALUES (m.target_user_id, 'moderation', 'Your Appeal Was Heard', v_notice, v_notice,
            jsonb_build_object('action', 'appeal', 'outcome', p_outcome, 'mod_action_id', m.id));
  END IF;
END;
$_$;


--
-- Name: lift_sanction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lift_sanction(p_user_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
  -- The reason, cleaned as a member's words are (clean_member_text): kept on the verdict and told to
  -- the member in their notice.
  v_reason   text := btrim(coalesce(public.clean_member_text(p_reason), ''));
  v_banned   boolean;
  v_until    timestamptz;
  v_said     text;
  v_lifted   uuid;
  v_what     text;
  v_notice   text;
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;
  IF char_length(v_reason) = 0 OR char_length(v_reason) > 500 THEN
    RAISE EXCEPTION 'A reason of up to 500 characters is required.' USING ERRCODE = 'P0001';
  END IF;
  -- No admin lifts their own sanction: the house's one rule of who may judge a case (a_judge_is_refused).
  IF private.a_judge_is_refused(v_admin_id, NULL, p_user_id) IS NOT NULL THEN
    RAISE EXCEPTION '%', private.a_judge_is_refused(v_admin_id, NULL, p_user_id) USING ERRCODE = '42501';
  END IF;

  -- The member's standing, held while it is lifted: a verdict given at the same moment waits.
  SELECT coalesce(is_banned, false), suspended_until, suspension_reason INTO v_banned, v_until, v_said
    FROM public.profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MEMBER_GONE' USING ERRCODE = 'P0002';
  END IF;
  -- Exile is the house's last word: never lifted by hand, only overturned on its one appeal.
  IF EXISTS (SELECT 1 FROM public.mod_actions WHERE target_user_id = p_user_id AND action = 'permanent_exile' AND lifted_at IS NULL)
     OR (v_banned AND coalesce(v_said, '') LIKE 'PERMANENT EXILE:%') THEN
    RAISE EXCEPTION 'EXILE_STANDS' USING ERRCODE = 'P0001';
  END IF;
  IF NOT v_banned AND (v_until IS NULL OR v_until <= now()) THEN
    -- Lifted meanwhile by another admin, or a suspension run out: nothing stands to lift.
    RAISE EXCEPTION 'NOT_SANCTIONED' USING ERRCODE = 'P0002';
  END IF;

  -- The verdict told in the member's notice: the ban standing, else the suspension that governs.
  SELECT id INTO v_lifted FROM public.mod_actions
   WHERE target_user_id = p_user_id AND lifted_at IS NULL
     AND (action = 'ban' OR (action IN ('suspend', 'mute_user') AND expires_at > now()))
   ORDER BY (action = 'ban') DESC, expires_at DESC NULLS LAST, created_at DESC LIMIT 1;

  -- Only what holds now is lifted: a sentence already served stays served on the record, never "lifted".
  UPDATE public.mod_actions
     SET lifted_at = now(), lifted_by = v_admin_id, lift_reason = v_reason
   WHERE target_user_id = p_user_id AND lifted_at IS NULL
     AND (action = 'ban' OR (action IN ('suspend', 'mute_user') AND expires_at > now()));

  UPDATE public.profiles
     SET is_banned = false, banned_at = NULL, suspended_until = NULL, suspension_reason = NULL
   WHERE id = p_user_id;

  v_what := CASE WHEN v_banned THEN 'the closing of your membership' ELSE 'the pause on your membership' END;
  v_notice := 'The house has lifted ' || v_what || '. You may write again. Reason: ' || v_reason;
  INSERT INTO public.notifications (user_id, type, title, body, message, metadata)
  VALUES (p_user_id, 'moderation', 'A Notice from the House', v_notice, v_notice,
          jsonb_build_object('action', 'lift', 'reason', v_reason)
          || CASE WHEN v_lifted IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('mod_action_id', v_lifted) END);
END;
$$;


--
-- Name: like_escape(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.like_escape(p_term text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT replace(replace(replace(COALESCE(p_term, ''), '\', '\\'), '%', '\%'), '_', '\_');
$$;


--
-- Name: list_certify_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_certify_count(p_list_id uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT count(*)::bigint
  FROM public.interactions i
  WHERE i.target_list_id = p_list_id
    AND i.type = 'endorse_list'
    AND EXISTS (
      SELECT 1 FROM public.lists l
      WHERE l.id = p_list_id
        AND (l.user_id = (SELECT auth.uid())
             OR (l.is_private = false AND l.withheld_at IS NULL
                 AND NOT COALESCE(l.user_id = ANY ((SELECT private.hidden_authors())::uuid[]), false)
                 AND private.can_view_user_data(l.user_id)))
    );
$$;


--
-- Name: FUNCTION list_certify_count(p_list_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_certify_count(p_list_id uuid) IS 'True endorsement count for a stack, independent of the viewer. SECURITY DEFINER because RLS on interactions hides a sealed member''s endorsement from non-followers. Gated on the STACK''s visibility so a private stack answers only to its owner. Returns an aggregate only.';


--
-- Name: list_certify_counts(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_certify_counts(p_list_ids uuid[]) RETURNS TABLE(list_id uuid, certify_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT t.id, (
    SELECT count(*)::bigint
    FROM public.interactions i
    WHERE i.target_list_id = t.id
      AND i.type = 'endorse_list'
      AND EXISTS (
        SELECT 1 FROM public.lists l
        WHERE l.id = t.id
          AND (l.user_id = (SELECT auth.uid())
               OR (l.is_private = false AND l.withheld_at IS NULL
                   AND NOT COALESCE(l.user_id = ANY ((SELECT private.hidden_authors())::uuid[]), false)
                   AND private.can_view_user_data(l.user_id)))
      )
  )
  FROM unnest(p_list_ids) AS t(id);
$$;


--
-- Name: FUNCTION list_certify_counts(p_list_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_certify_counts(p_list_ids uuid[]) IS 'Batch form of list_certify_count, for a page of stacks. Same guarantees. Returns a row for every id given, including stacks the caller cannot see (as 0).';


--
-- Name: list_items_touch_the_stack(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_items_touch_the_stack() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- A silenced or suspended member may still take out what is theirs, and may edit nothing: no edit
  -- of theirs can follow to need the stack's time, and touching the stack would be refused as their
  -- write (enforce_not_restricted, tr_ban_gate_update), taking the withdrawal down with it.
  IF EXISTS (SELECT 1 FROM public.profiles
              WHERE id = auth.uid() AND (is_banned OR suspended_until > now())) THEN
    RETURN NULL;
  END IF;
  -- The stack's own time, set by set_lists_updated_at to the house's now().
  UPDATE public.lists SET updated_at = now()
   WHERE id IN (SELECT DISTINCT list_id FROM changed);
  RETURN NULL;
END $$;


--
-- Name: lobby_choose_edition(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lobby_choose_edition(p_edition date DEFAULT ((now() AT TIME ZONE 'UTC'::text))::date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_said text;
BEGIN
  -- One chooser at a time; and an edition, once chosen, is never chosen again.
  PERFORM pg_advisory_xact_lock(hashtext('public.lobby_choose_edition'));
  IF EXISTS (SELECT 1 FROM public.lobby_editions WHERE edition = p_edition) THEN
    RETURN 0;
  END IF;
  INSERT INTO private.lobby_drafts (edition) VALUES (p_edition) ON CONFLICT (edition) DO NOTHING;
  LOOP
    v_said := private.lobby_edition_step(p_edition, 1000000);
    EXIT WHEN v_said LIKE 'chosen %';
  END LOOP;
  RETURN substr(v_said, 8)::integer;
END;
$$;


--
-- Name: FUNCTION lobby_choose_edition(p_edition date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lobby_choose_edition(p_edition date) IS 'Chooses the Lobby''s edition for a day, once: the never-honoured first, by the day''s regard, the honour spread round the house. Run by the lobby-edition job; no role may call it.';


--
-- Name: log_counts_keep_certify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_counts_keep_certify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP IN ('DELETE', 'UPDATE') AND OLD.type = 'endorse_log' AND OLD.target_log_id IS NOT NULL THEN
    UPDATE public.log_counts SET certify_count = GREATEST(0, certify_count - 1) WHERE log_id = OLD.target_log_id;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.type = 'endorse_log' AND NEW.target_log_id IS NOT NULL THEN
    INSERT INTO public.log_counts AS c (log_id, certify_count) VALUES (NEW.target_log_id, 1)
      ON CONFLICT (log_id) DO UPDATE SET certify_count = c.certify_count + 1;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: log_counts_keep_critique(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_counts_keep_critique() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- A critique the house withheld was taken off its log's count when it was withheld (H-B10).
  IF TG_OP IN ('DELETE', 'UPDATE') AND OLD.withheld_at IS NULL THEN
    UPDATE public.log_counts SET critique_count = GREATEST(0, critique_count - 1) WHERE log_id = OLD.log_id;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.withheld_at IS NULL THEN
    INSERT INTO public.log_counts AS c (log_id, critique_count) VALUES (NEW.log_id, 1)
      ON CONFLICT (log_id) DO UPDATE SET critique_count = c.critique_count + 1;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: log_viewing_add(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_viewing_add(p_log_id uuid, p_viewing_id uuid, p_fields jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  l public.logs%ROWTYPE;
  r public.logs%ROWTYPE;
  f jsonb := COALESCE(p_fields, '{}'::jsonb);
  a jsonb := public.viewing_fields()->'archived';
  v_entry   jsonb;
  v_payload jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_viewing_id IS NULL THEN
    RAISE EXCEPTION 'A viewing needs an identity.' USING ERRCODE = '22004';
  END IF;

  SELECT * INTO l FROM public.logs WHERE id = p_log_id AND user_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Log not found' USING ERRCODE = 'P0002';
  END IF;

  IF l.viewing_id = p_viewing_id
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(l.viewing_history) x WHERE x->>'viewingId' = p_viewing_id::text) THEN
    RETURN p_viewing_id;
  END IF;

  SELECT jsonb_object_agg(m->>'key', to_jsonb(l)->col) INTO v_entry
    FROM jsonb_each(a) AS x(col, m);
  v_entry := v_entry || jsonb_build_object('viewingId', l.viewing_id);

  SELECT COALESCE(jsonb_object_agg(col, f->col), '{}'::jsonb) INTO v_payload
    FROM jsonb_each(a) AS x(col, m) WHERE f ? col;
  BEGIN
    r := jsonb_populate_record(l, v_payload);
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'A viewing was given a value of the wrong kind.' USING ERRCODE = '22023';
  END;
  IF NOT (f ? 'watched_date') THEN r.watched_date := current_date; END IF;
  IF NOT (f ? 'status')       THEN r.status       := 'rewatched';  END IF;

  BEGIN
    EXECUTE format('UPDATE public.logs SET viewing_id = $1, viewing_history = $2, %s WHERE id = $3',
                   public.viewing_set_list())
      USING p_viewing_id,
            jsonb_build_array(v_entry) || COALESCE(l.viewing_history, '[]'::jsonb),
            p_log_id,
            r;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'That viewing belongs to another log.'
      USING ERRCODE = '23505', HINT = 'A new viewing needs a new identity.';
  END;

  RETURN p_viewing_id;
END $_$;


--
-- Name: log_viewing_remove(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_viewing_remove(p_log_id uuid, p_viewing_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  l public.logs%ROWTYPE;
  r public.logs%ROWTYPE;
  a jsonb := public.viewing_fields()->'archived';
  e jsonb;
  v_payload jsonb := '{}'::jsonb;
  v_col  text;
  v_map  jsonb;
  v_val  jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO l FROM public.logs WHERE id = p_log_id AND user_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF l.viewing_id <> p_viewing_id THEN
    RETURN l.viewing_id;
  END IF;
  IF jsonb_array_length(l.viewing_history) = 0 THEN
    RAISE EXCEPTION 'The only viewing of a log is removed by deleting the log.'
      USING ERRCODE = 'P0001', HINT = 'Delete the log instead.';
  END IF;

  e := l.viewing_history->0;

  -- Read the viewing back field by field. Histories written by older builds
  -- hold whatever those builds wrote, so a value that is not the kind its
  -- column takes is replaced by the declared fallback rather than failing a
  -- member's removal.
  FOR v_col, v_map IN SELECT key, value FROM jsonb_each(a) LOOP
    v_val := COALESCE(e->(v_map->>'key'), v_map->'fallback');
    -- Ask the COLUMN itself whether it can take this value, by trying it.
    -- Asking by type NAME cannot be done here: pg_input_is_valid keeps the type
    -- of its first call at a given place in the code and answers about THAT
    -- type ever after — so a loop over columns of different types gets nonsense.
    BEGIN
      PERFORM jsonb_populate_record(NULL::public.logs, jsonb_build_object(v_col, v_val));
    EXCEPTION WHEN others THEN
      v_val := v_map->'fallback';
    END;
    v_payload := v_payload || jsonb_build_object(v_col, v_val);
  END LOOP;

  -- Every viewing has a date. One that never recorded its own keeps the log's.
  IF v_payload->'watched_date' IS NULL OR jsonb_typeof(v_payload->'watched_date') = 'null' THEN
    v_payload := v_payload || jsonb_build_object('watched_date', to_jsonb(l.watched_date));
  END IF;

  r := jsonb_populate_record(NULL::public.logs, v_payload);
  -- Older builds wrote "None" for no disc and "" for nobody; both mean nothing.
  IF r.physical_media IN ('None', '') THEN r.physical_media := NULL; END IF;
  IF r.watched_with = ''              THEN r.watched_with   := NULL; END IF;

  EXECUTE format('UPDATE public.logs SET viewing_id = $1, viewing_history = $2, %s WHERE id = $3',
                 public.viewing_set_list())
    USING (e->>'viewingId')::uuid, l.viewing_history - 0, p_log_id, r;

  RETURN (e->>'viewingId')::uuid;
END $_$;


--
-- Name: logs_keep_viewings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.logs_keep_viewings() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old       jsonb;
  v_old_ids   text[];
  v_new_ids   text[];
  v_moved     boolean;
  v_is_add    boolean := false;
  v_is_remove boolean := false;
BEGIN
  NEW.viewing_history := public.normalize_viewing_history(NEW.viewing_history);

  IF TG_OP = 'UPDATE' THEN
    -- The stored history as it really is. A row from before the repair carries
    -- no identities, so nothing about it can be read as a loss.
    v_old := CASE WHEN jsonb_typeof(OLD.viewing_history) = 'array' THEN OLD.viewing_history ELSE '[]'::jsonb END;
    SELECT array_agg(x->>'viewingId') INTO v_old_ids
      FROM jsonb_array_elements(v_old) x
     WHERE jsonb_typeof(x) = 'object' AND x ? 'viewingId';

    v_moved := NEW.viewing_id <> OLD.viewing_id;

    IF v_moved THEN
      v_is_add := jsonb_array_length(NEW.viewing_history) = jsonb_array_length(v_old) + 1
              AND NEW.viewing_history->0->>'viewingId' = OLD.viewing_id::text
              AND (NEW.viewing_history - 0) = v_old;

      v_is_remove := jsonb_array_length(v_old) > 0
              AND NEW.viewing_id::text = v_old->0->>'viewingId'
              AND NEW.viewing_history = (v_old - 0);

      IF NOT (v_is_add OR v_is_remove) THEN
        RAISE EXCEPTION 'A log moves to another viewing by adding one or removing one.'
          USING ERRCODE = 'P0001', HINT = 'Use log_viewing_add or log_viewing_remove.';
      END IF;
    END IF;

    -- Outside a removal, no past viewing may be lost.
    IF NOT v_is_remove AND v_old_ids IS NOT NULL THEN
      SELECT array_agg(x->>'viewingId') INTO v_new_ids FROM jsonb_array_elements(NEW.viewing_history) x;
      IF NOT (v_old_ids <@ COALESCE(v_new_ids, '{}'::text[])) THEN
        RAISE EXCEPTION 'A past viewing can only be removed by removing it.'
          USING ERRCODE = 'P0001', HINT = 'Use log_viewing_remove.';
      END IF;
    END IF;
  END IF;

  -- The count is the history's, never a client's arithmetic.
  NEW.view_count := jsonb_array_length(NEW.viewing_history) + 1;
  RETURN NEW;
END $$;


--
-- Name: logs_register_viewings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.logs_register_viewings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ids uuid[];
BEGIN
  SELECT array_agg(DISTINCT id) INTO v_ids FROM (
    SELECT NEW.viewing_id AS id
    UNION ALL
    SELECT (e->>'viewingId')::uuid FROM jsonb_array_elements(NEW.viewing_history) e
  ) s;

  BEGIN
    INSERT INTO public.viewings (viewing_id, log_id)
    SELECT id, NEW.id FROM unnest(v_ids) AS id
     WHERE NOT EXISTS (SELECT 1 FROM public.viewings v WHERE v.viewing_id = id AND v.log_id = NEW.id);
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'That viewing belongs to another log.'
      USING ERRCODE = '23505', HINT = 'A new viewing needs a new identity.';
  END;

  IF TG_OP = 'UPDATE' THEN
    DELETE FROM public.viewings WHERE log_id = NEW.id AND viewing_id <> ALL (v_ids);
  END IF;

  RETURN NULL;
END $$;


--
-- Name: lounge_members_read_by_the_house(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lounge_members_read_by_the_house() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Whatever time the phone sent, the member read the salon now.
  IF NEW.last_read_at IS DISTINCT FROM OLD.last_read_at THEN
    NEW.last_read_at := now();
  END IF;
  RETURN NEW;
END $$;


--
-- Name: lounge_messages_daily_ceiling(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lounge_messages_daily_ceiling() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me  uuid := auth.uid();
  v_day date := (now() AT TIME ZONE 'UTC')::date;
  v_n   integer;
BEGIN
  -- The house's own writes are not counted: a member's request always carries the member.
  IF v_me IS NULL THEN
    RETURN NEW;
  END IF;
  -- Sent again, its first send landed: no new message.
  IF EXISTS (SELECT 1 FROM public.lounge_messages WHERE id = NEW.id) THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.salon_budget AS b (user_id, day, n)
  VALUES (v_me, v_day, 1)
  ON CONFLICT (user_id) DO UPDATE SET
    day = v_day,
    n   = (CASE WHEN b.day = v_day THEN b.n ELSE 0 END) + 1
  RETURNING n INTO v_n;
  IF v_n > 1000 THEN
    RAISE EXCEPTION 'RATE_LIMITED' USING ERRCODE = 'RH429', DETAIL = 'day',
      HINT = GREATEST(1, ceil(extract(epoch FROM ((v_day + 1)::timestamp AT TIME ZONE 'UTC') - now())))::integer::text;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: lpn_belongs_to_its_viewing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lpn_belongs_to_its_viewing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.viewing_id <> OLD.viewing_id OR NEW.log_id <> OLD.log_id OR NEW.user_id <> OLD.user_id) THEN
    RAISE EXCEPTION 'A note stays with the viewing it was written about.' USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.viewings v JOIN public.logs l ON l.id = v.log_id
     WHERE v.viewing_id = NEW.viewing_id AND v.log_id = NEW.log_id AND l.user_id = NEW.user_id
  ) THEN
    RAISE EXCEPTION 'That note has no viewing of its writer to belong to.' USING ERRCODE = '23503';
  END IF;

  NEW.notes := btrim(NEW.notes);
  RETURN NEW;
END $$;


--
-- Name: mark_film_sync_failed(integer); Type: FUNCTION; Schema: public; Owner: -
