--
-- Name: normalize_viewing_history(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_viewing_history(p_history jsonb, p_depth integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_out   jsonb := '[]'::jsonb;
  v_run   text  := '';
  v_seen  text[] := '{}';
  v_e     jsonb;
  v_entry jsonb;
  v_part  jsonb;
  v_id    text;
BEGIN
  -- A string of a string of a string is still recoverable; beyond this it is noise.
  IF p_depth > 6 OR p_history IS NULL OR jsonb_typeof(p_history) = 'null' THEN
    RETURN '[]'::jsonb;
  END IF;

  -- Stored as a JSON string (the web's JSON.stringify): decode it.
  IF jsonb_typeof(p_history) = 'string' THEN
    IF pg_input_is_valid(p_history #>> '{}', 'jsonb') THEN
      RETURN public.normalize_viewing_history((p_history #>> '{}')::jsonb, p_depth + 1);
    END IF;
    RETURN '[]'::jsonb;
  END IF;

  IF jsonb_typeof(p_history) = 'object' THEN
    p_history := jsonb_build_array(p_history);
  ELSIF jsonb_typeof(p_history) <> 'array' THEN
    RETURN '[]'::jsonb;
  END IF;

  FOR v_e IN SELECT x.value FROM jsonb_array_elements(p_history) WITH ORDINALITY AS x(value, ord) ORDER BY x.ord
  LOOP
    -- The web's rewatch spread a string into single characters. Consecutive
    -- string elements are joined back together and decoded in place.
    IF jsonb_typeof(v_e) = 'string' THEN
      v_run := v_run || (v_e #>> '{}');
      CONTINUE;
    END IF;
    IF v_run <> '' THEN
      v_part := public.normalize_viewing_history(to_jsonb(v_run), p_depth + 1);
      v_run := '';
      FOR v_entry IN SELECT y.value FROM jsonb_array_elements(v_part) WITH ORDINALITY AS y(value, ord) ORDER BY y.ord LOOP
        v_id := v_entry->>'viewingId';
        IF v_id = ANY (v_seen) THEN
          v_entry := v_entry || jsonb_build_object('viewingId', gen_random_uuid());
          v_id := v_entry->>'viewingId';
        END IF;
        v_seen := v_seen || v_id;
        v_out := v_out || jsonb_build_array(v_entry);
      END LOOP;
    END IF;

    IF jsonb_typeof(v_e) = 'object' THEN
      -- A note never lives in a history anybody else can read.
      v_entry := v_e - 'privateNotes' - 'private_notes';
      v_id := v_entry->>'viewingId';
      IF v_id IS NULL OR NOT pg_input_is_valid(v_id, 'uuid') OR v_id = ANY (v_seen) THEN
        v_entry := v_entry || jsonb_build_object('viewingId', gen_random_uuid());
        v_id := v_entry->>'viewingId';
      END IF;
      v_seen := v_seen || v_id;
      v_out := v_out || jsonb_build_array(v_entry);
    END IF;
    -- Numbers, booleans and nulls are not viewings: dropped.
  END LOOP;

  IF v_run <> '' THEN
    v_part := public.normalize_viewing_history(to_jsonb(v_run), p_depth + 1);
    FOR v_entry IN SELECT y.value FROM jsonb_array_elements(v_part) WITH ORDINALITY AS y(value, ord) ORDER BY y.ord LOOP
      v_id := v_entry->>'viewingId';
      IF v_id = ANY (v_seen) THEN
        v_entry := v_entry || jsonb_build_object('viewingId', gen_random_uuid());
        v_id := v_entry->>'viewingId';
      END IF;
      v_seen := v_seen || v_id;
      v_out := v_out || jsonb_build_array(v_entry);
    END LOOP;
  END IF;

  RETURN v_out;
END $$;


--
-- Name: note_film(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_film() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.film_id IS NULL OR NEW.film_id <= 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.films (id, title)
  VALUES (NEW.film_id, NULLIF(NEW.film_title, ''))
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: note_film_verdict(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_film_verdict() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  m record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    FOR m IN
      SELECT n.film_id, count(*)::integer AS logs, (count(*) FILTER (WHERE n.rating > 0))::integer AS rated,
             COALESCE(sum(n.rating) FILTER (WHERE n.rating > 0), 0) AS rating_sum
        FROM moved_in n
       WHERE n.withheld_at IS NULL AND n.film_id > 0
       GROUP BY n.film_id
       ORDER BY n.film_id
    LOOP
      PERFORM private.a_films_verdict_moves(m.film_id, m.logs, m.rated, m.rating_sum);
    END LOOP;
  ELSIF TG_OP = 'DELETE' THEN
    FOR m IN
      SELECT o.film_id, -count(*)::integer AS logs, -(count(*) FILTER (WHERE o.rating > 0))::integer AS rated,
             -COALESCE(sum(o.rating) FILTER (WHERE o.rating > 0), 0) AS rating_sum
        FROM moved_out o
       WHERE o.withheld_at IS NULL AND o.film_id > 0
       GROUP BY o.film_id
       ORDER BY o.film_id
    LOOP
      PERFORM private.a_films_verdict_moves(m.film_id, m.logs, m.rated, m.rating_sum);
    END LOOP;
  ELSE
    FOR m IN
      SELECT x.film_id, sum(x.s)::integer AS logs, COALESCE(sum(x.s) FILTER (WHERE x.rating > 0), 0)::integer AS rated,
             COALESCE(sum(x.s * x.rating) FILTER (WHERE x.rating > 0), 0) AS rating_sum
        FROM (SELECT n.film_id, n.rating, 1 AS s FROM moved_in n WHERE n.withheld_at IS NULL
              UNION ALL
              SELECT o.film_id, o.rating, -1 AS s FROM moved_out o WHERE o.withheld_at IS NULL) x
       WHERE x.film_id > 0
       GROUP BY x.film_id
      HAVING sum(x.s) <> 0
          OR COALESCE(sum(x.s) FILTER (WHERE x.rating > 0), 0) <> 0
          OR COALESCE(sum(x.s * x.rating) FILTER (WHERE x.rating > 0), 0) <> 0
       ORDER BY x.film_id
    LOOP
      PERFORM private.a_films_verdict_moves(m.film_id, m.logs, m.rated, m.rating_sum);
    END LOOP;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: notices_page(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notices_page(p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    SET enable_bitmapscan TO 'off'
    AS $$
  WITH counted AS (
    SELECT count(*) AS n
      FROM (SELECT 1 FROM public.notifications
             WHERE user_id = (SELECT auth.uid()) AND is_read = false
             LIMIT 1001) u
  )
  SELECT jsonb_build_object(
    'rows', COALESCE((
      SELECT jsonb_agg(to_jsonb(n) ORDER BY n.created_at DESC, n.id DESC)
        FROM (SELECT id, user_id, type, from_username, from_user_id, message, is_read, created_at, film_id,
                     poster_path, group_key, title, related_lounge_id, metadata
                FROM public.notifications
               WHERE user_id = (SELECT auth.uid())
               ORDER BY created_at DESC, id DESC
               LIMIT LEAST(GREATEST(COALESCE(p_limit, 30), 1), 100)) n), '[]'::jsonb),
    'unread', (SELECT LEAST(n, 1000) FROM counted),
    'unread_more', (SELECT n > 1000 FROM counted));
$$;


--
-- Name: notify_on_dossier_certify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_on_dossier_certify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    target_user UUID;
    sender_user TEXT;
    v_title TEXT;
BEGIN
    SELECT username INTO sender_user FROM public.profiles WHERE id = NEW.user_id;
    SELECT user_id, title INTO target_user, v_title FROM public.dispatch_dossiers WHERE id = NEW.dossier_id;

    IF target_user IS NOT NULL AND target_user != NEW.user_id THEN
        INSERT INTO public.notifications (user_id, type, from_username, from_user_id, message,
                                          group_key, title)
        VALUES (target_user, 'endorse', sender_user, NEW.user_id,
                'certified your dossier “' || COALESCE(v_title, 'Untitled') || '”.',
                'endorse:dossier:' || NEW.dossier_id, v_title);
    END IF;

    RETURN NEW;
END;
$$;


