END;
$$;


--
-- Name: register_push_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_push_token(p_token text, p_platform text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  -- The session this call is made under: a token is sent to only while it stands (push_tokens_of).
  v_claim   text := auth.jwt() ->> 'session_id';
  v_session uuid := CASE WHEN v_claim ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                         THEN v_claim::uuid END;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- The device is the token: claimed by the member signed in on it now, from
  -- whoever held it before (never two owners, never a stale one).
  INSERT INTO public.push_tokens (user_id, token, platform, session_id, updated_at)
  VALUES (auth.uid(), p_token, p_platform, v_session, now())
  ON CONFLICT (token)
  DO UPDATE SET user_id = EXCLUDED.user_id, platform = EXCLUDED.platform,
                session_id = EXCLUDED.session_id, updated_at = now();

  -- A member's ten most recently seen devices; older ones go.
  DELETE FROM public.push_tokens
   WHERE user_id = auth.uid()
     AND id NOT IN (
       SELECT id FROM public.push_tokens
        WHERE user_id = auth.uid()
        ORDER BY updated_at DESC, id DESC
        LIMIT 10);
END;
$_$;


--
-- Name: relinquish_rank(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relinquish_rank() RETURNS TABLE(out_tier text, out_applied boolean, out_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'relinquish_rank: not authenticated' USING ERRCODE = '42501';
  END IF;

  -- A seat is one of a hundred: it ends only on the store's own record, read by
  -- the house, never on the app's word that the store holds nothing.
  IF EXISTS (SELECT 1 FROM public.rank_grants
              WHERE user_id = v_uid AND source = 'revenuecat' AND tier = 'founding') THEN
    RETURN QUERY SELECT p.tier, false, 'a founding seat ends only on the store''s own record'::text
      FROM public.profiles p WHERE p.id = v_uid;
    RETURN;
  END IF;

  -- 'revenuecat' as the source: only the store's own grant is ended.
  RETURN QUERY
  SELECT g.out_tier, g.out_applied, g.out_reason
  FROM public.grant_entitlement(v_uid, 'cinephile', 'revenuecat') AS g;
END $$;


--
-- Name: FUNCTION relinquish_rank(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.relinquish_rank() IS 'Ends the store''s grant of the CALLER''S OWN rank and nothing else (a rank given on the web or by hand stands, and a founding seat ends only on the store''s own record, read by the house). Safe for authenticated: the worst abuse is self-removal, which the next store sync restores. Called by the client when the store reports no active entitlement.';


--
-- Name: remove_lounge_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_lounge_member(p_lounge_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_creator uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT creator_id INTO v_creator FROM public.lounges WHERE id = p_lounge_id;
  IF v_creator IS NULL THEN RAISE EXCEPTION 'Lounge not found'; END IF;
  IF auth.uid() IS DISTINCT FROM v_creator THEN RAISE EXCEPTION 'Only the host can remove members'; END IF;
  IF p_user_id IS NOT DISTINCT FROM v_creator THEN RAISE EXCEPTION 'The host cannot be removed'; END IF;
  -- A banned member holds no seat to remove; their row stays, for the ban to be lifted.
  DELETE FROM public.lounge_members
   WHERE lounge_id = p_lounge_id AND user_id = p_user_id AND status <> 'banned';
END $$;


--
-- Name: rename_my_handle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_my_handle(p_new text) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_me    uuid := auth.uid();
  v_kept  text;
  v_found boolean;
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501'; END IF;

  PERFORM pg_catalog.set_config('reelhouse.deliberate_rename', 'on', true);
  UPDATE public.profiles SET username = p_new WHERE id = v_me RETURNING username INTO v_kept;
  v_found := FOUND;
  PERFORM pg_catalog.set_config('reelhouse.deliberate_rename', '', true);

  IF NOT v_found THEN
    RAISE EXCEPTION 'Your handle could not be changed.' USING ERRCODE = '42501';
  END IF;
  RETURN v_kept;
END;
$$;


--
-- Name: request_account_deletion(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_deletion(p_erase_writing boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  uid      uuid := auth.uid();
  v_handle text;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT username INTO v_handle FROM public.profiles WHERE id = uid;

  -- The member has asked; what follows is the house's own act.
  PERFORM set_config('request.jwt.claims', '', true);
  PERFORM set_config('request.jwt.claim.sub', '', true);

  UPDATE public.lounges l
     SET creator_id = (
           SELECT m.user_id FROM public.lounge_members m
            WHERE m.lounge_id = l.id AND m.user_id <> uid AND m.status = 'approved'
            ORDER BY m.joined_at ASC NULLS LAST
            LIMIT 1)
   WHERE l.creator_id = uid
     AND EXISTS (SELECT 1 FROM public.lounge_members m
                  WHERE m.lounge_id = l.id AND m.user_id <> uid AND m.status = 'approved');

  -- The member chose to take their words with them: each piece comes down in the form a member's own
  -- withdrawal gives it, before the name is taken off what stays.
  IF coalesce(p_erase_writing, false) THEN
    -- Critiques and notes: deleted, as WITHDRAW deletes one. The counters settle by their triggers.
    DELETE FROM public.log_comments      WHERE user_id = uid;
    DELETE FROM public.list_comments     WHERE user_id = uid;
    DELETE FROM public.dispatch_comments WHERE user_id = uid;

    -- A closed ballot's notice quoted its question to every voter: the notice stays, the question goes.
    -- (written before round 12 it names no author; since, it names this member)
    UPDATE public.notifications n
       SET message = 'A ballot you voted in has closed.', metadata = n.metadata - 'title'
      FROM public.dispatch_posts p
     WHERE p.user_id = uid AND p.kind = 'ballot'
       AND (n.from_user_id IS NULL OR n.from_user_id = uid)
       AND n.metadata @> jsonb_build_object('dispatch_post_id', p.id, 'kind', 'ballot');

    -- Filings: withdrawn by their author. The critiques others wrote under them stay.
    PERFORM public.dispatch_empty_filing(p.id, 'author')
       FROM public.dispatch_posts p
      WHERE p.user_id = uid AND p.ended_at IS NULL;
    UPDATE public.dispatch_posts
       SET series_id = NULL, series_title = NULL, part_number = NULL
     WHERE user_id = uid AND series_id IS NOT NULL;

    -- Salon messages: withdrawn, with the card, the film and the quote they carried.
    UPDATE public.lounge_messages
       SET content = '', metadata = '{}'::jsonb, film_id = NULL, film_title = NULL, film_poster = NULL,
           reply_to_content = NULL, deleted_at = coalesce(deleted_at, now())
     WHERE user_id = uid;

    -- The old Dispatch tables, still open to read.
    DELETE FROM public.dossier_comments_legacy WHERE user_id = uid;
    UPDATE public.dispatch_dossiers_legacy
       SET title = '', excerpt = NULL, full_content = NULL
     WHERE user_id = uid;
  END IF;

  UPDATE public.log_comments
     SET user_id = NULL, username = '[deleted]'
   WHERE user_id = uid;

  UPDATE public.dossier_comments
     SET user_id = NULL, username = '[deleted]'
   WHERE user_id = uid;

  UPDATE public.dispatch_dossiers
     SET user_id = NULL, author_username = '[deleted]'
   WHERE user_id = uid;

  -- The old Dispatch tables kept the handle on what stays: the name comes off there too.
  UPDATE public.dossier_comments_legacy
     SET user_id = NULL, username = '[deleted]'
   WHERE user_id = uid;

  UPDATE public.dispatch_dossiers_legacy
     SET user_id = NULL, author_username = '[deleted]'
   WHERE user_id = uid;

  UPDATE public.lounge_messages
     SET reply_to_username = '[deleted]'
   WHERE reply_to_id IN (SELECT id FROM public.lounge_messages WHERE user_id = uid);

  -- A closed ballot's notice names its author since round 12, so a block or a mute hides it: it stays
  -- with each voter, unsigned as the ballot itself stays, as it did before it named anyone.
  UPDATE public.notifications SET from_user_id = NULL WHERE from_user_id = uid AND type = 'ballot';

  DELETE FROM public.notifications WHERE from_user_id = uid;

  IF v_handle IS NOT NULL THEN
    -- Asked as containment, so the cards' own index (lounge_messages_card_names, 20261022_02) finds them.
    -- A stack's card names its curator: that name comes off as a record's and an essay's do.
    UPDATE public.lounge_messages
       SET metadata = ((metadata - 'owner_username') - 'author_username')
                      - CASE WHEN type = 'list_share' AND metadata @> jsonb_build_object('curator', v_handle)
                             THEN 'curator' ELSE '' END
     WHERE metadata <> '{}'::jsonb
       AND (metadata @> jsonb_build_object('owner_username', v_handle)
         OR metadata @> jsonb_build_object('author_username', v_handle)
         OR (type = 'list_share' AND metadata @> jsonb_build_object('curator', v_handle)));
  END IF;

  UPDATE public.list_comments   SET user_id = NULL WHERE user_id = uid;
  UPDATE public.lounge_messages SET user_id = NULL WHERE user_id = uid;

  PERFORM set_config('storage.allow_delete_query', 'true', true);
  DELETE FROM storage.objects WHERE owner = uid;

  DELETE FROM auth.users WHERE id = uid;
END
$$;


--
-- Name: request_lounge_membership(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_lounge_membership(p_lounge_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_private boolean; v_creator uuid; v_status text; v_uname text; v_lname text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT is_private, creator_id, name INTO v_private, v_creator, v_lname FROM public.lounges WHERE id = p_lounge_id;
  -- Gone (dissolved by its host): said as gone, never as a failure of the member's signal.
  IF v_private IS NULL THEN RAISE EXCEPTION 'SALON_GONE' USING ERRCODE = 'P0002'; END IF;
  IF EXISTS (SELECT 1 FROM public.lounge_sanctions
              WHERE lounge_id = p_lounge_id AND user_id = auth.uid() AND status = 'banned') THEN
    RAISE EXCEPTION 'You cannot request this lounge';
  END IF;
  SELECT status INTO v_status FROM public.lounge_members WHERE lounge_id = p_lounge_id AND user_id = auth.uid();
  IF v_status = 'banned' THEN RAISE EXCEPTION 'You cannot request this lounge'; END IF;
  IF v_status IN ('approved','pending','muted') THEN RETURN; END IF;
  INSERT INTO public.lounge_members (lounge_id, user_id, status) VALUES (p_lounge_id, auth.uid(), 'pending')
  ON CONFLICT (user_id, lounge_id) DO UPDATE SET status = 'pending'
    WHERE public.lounge_members.status NOT IN ('banned','approved','muted');
  SELECT username INTO v_uname FROM public.profiles WHERE id = auth.uid();
  IF v_creator IS NOT NULL AND v_creator <> auth.uid() THEN
    -- the sender is from_username; every reader prints it before the message
    INSERT INTO public.notifications (user_id, type, from_username, from_user_id, message, related_lounge_id)
    VALUES (v_creator, 'salon', v_uname, auth.uid(),
            CASE WHEN v_uname IS NULL THEN 'A member is asking' ELSE 'is asking' END
              || ' to enter ' || COALESCE(v_lname,'your lounge') || '.',
            p_lounge_id);
  END IF;
END $$;


--
-- Name: resolve_moderation_report_v2(uuid, text, uuid, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_moderation_report_v2(p_report_id uuid, p_action text, p_admin_id uuid, p_reason text, p_duration_hours integer DEFAULT NULL::integer, p_notify_user boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_id       uuid := auth.uid();
  v_target_user_id uuid;
  v_reporter_id    uuid;
  v_content_id     uuid;
  v_content_type   text;
  v_expires_at     timestamptz;
  v_notice         text;
  v_snapshot       jsonb;
  v_kept           jsonb;
  v_rows           integer;
  v_held_until     timestamptz;
  v_held_banned    boolean;
  v_action_id      uuid;
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;

  -- Read pending and locked: a second verdict given at the same moment waits here for the first,
  -- then reads the case again as the first left it, no longer pending, and is refused.
  SELECT target_user_id, reporter_id, content_id, content_type
  INTO v_target_user_id, v_reporter_id, v_content_id, v_content_type
  FROM reports
  WHERE id = p_report_id AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ALREADY_JUDGED' USING ERRCODE = 'P0002';
  END IF;

  -- A moderator never rules on a case about themselves: another moderator judges it, by the one rule
  -- of who may judge a case (as an appeal or a lift is refused).
  IF private.a_judge_is_refused(v_admin_id, NULL, v_target_user_id) IS NOT NULL THEN
    RAISE EXCEPTION '%', private.a_judge_is_refused(v_admin_id, NULL, v_target_user_id) USING ERRCODE = '42501';
  END IF;

  IF v_target_user_id IS NULL AND p_action NOT IN ('dismiss', 'delete_content') THEN
    RAISE EXCEPTION 'That member has deleted their account. Only dismiss or delete_content remain.'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_action IN ('suspend', 'mute_user') AND (p_duration_hours IS NULL OR p_duration_hours <= 0) THEN
    RAISE EXCEPTION 'A duration in hours is required for %', p_action USING ERRCODE = 'P0001';
  END IF;

  IF p_duration_hours IS NOT NULL THEN
    v_expires_at := now() + (p_duration_hours || ' hours')::interval;
  END IF;

  -- The copy of what a removal takes: the piece as it stands (piece_as_it_stands), and, where its row
  -- stays to be put back (a salon message struck through, a filing emptied, a page's or a salon's words
  -- cleared), the fields that put it back, should the removal be overturned on appeal.
  IF p_action = 'delete_content' THEN
    v_snapshot := public.piece_as_it_stands(v_content_type, v_content_id);
    -- A log, a stack, a critique and a filing are withheld whole (H-B10), so need nothing kept to put them back.
    v_kept := CASE v_content_type
      WHEN 'lounge_message' THEN (SELECT jsonb_build_object('content', content) FROM lounge_messages WHERE id = v_content_id)
      WHEN 'profile' THEN (SELECT jsonb_build_object('bio', bio, 'display_name', display_name, 'avatar_url', avatar_url,
                                   'social_links', social_links) FROM profiles WHERE id = v_content_id)
      WHEN 'lounge' THEN (SELECT jsonb_build_object('name', name, 'description', description, 'cover_image', cover_image)
                            FROM lounges WHERE id = v_content_id)
    END;
    v_snapshot := v_snapshot || jsonb_build_object('type', v_content_type, 'id', v_content_id)
               || CASE WHEN v_kept IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('kept', v_kept) END;
  END IF;

  -- Closed only while still pending: the lock above holds it so, and this says so as well.
  UPDATE reports
  SET status = 'resolved',
      resolved_at = now(),
      resolved_by = v_admin_id,
      resolution_action = p_action
  WHERE id = p_report_id AND status = 'pending';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'ALREADY_JUDGED' USING ERRCODE = 'P0002';
  END IF;

  CASE p_action
    WHEN 'warn' THEN
      INSERT INTO warnings (user_id, admin_id, reason)
      VALUES (v_target_user_id, v_admin_id, p_reason);
      UPDATE profiles SET warning_count = warning_count + 1
      WHERE id = v_target_user_id;

    WHEN 'suspend', 'mute_user' THEN
      -- The later end stands: a shorter sentence given after a longer one never cuts it short. The
      -- member's page carries the reason of the sentence that governs (a ban's, while one stands).
      SELECT suspended_until, coalesce(is_banned, false) INTO v_held_until, v_held_banned
        FROM profiles WHERE id = v_target_user_id FOR UPDATE;
      UPDATE profiles
      SET suspended_until = GREATEST(suspended_until, v_expires_at),
          suspension_reason = CASE
            WHEN v_held_banned OR (v_held_until IS NOT NULL AND v_held_until >= v_expires_at) THEN suspension_reason
            WHEN p_action = 'mute_user' THEN 'Muted: ' || p_reason
            ELSE p_reason END
      WHERE id = v_target_user_id;

    WHEN 'ban' THEN
      UPDATE profiles
      SET is_banned = true, banned_at = now(), suspension_reason = p_reason
      WHERE id = v_target_user_id;

    WHEN 'permanent_exile' THEN
      UPDATE profiles
      SET is_banned = true, banned_at = now(), suspension_reason = 'PERMANENT EXILE: ' || p_reason
      WHERE id = v_target_user_id;

    WHEN 'delete_content' THEN
      -- Whether the piece still stands, asked of the tables that hold it before anything is taken:
      -- a filing is never deleted, only emptied (dispatch_no_hard_delete answers its DELETE with no
      -- row), and a legacy essay or critique is removed through a view, so a removal's own row
      -- count cannot say. A piece already gone took nothing: nothing is recorded or told, and the
      -- case stays pending (the raise undoes the close above).
      IF NOT public.piece_stands(v_content_type, v_content_id) THEN
        RAISE EXCEPTION 'PIECE_GONE' USING ERRCODE = 'P0002';
      END IF;
      -- A log, a stack, a critique or a filing is withheld whole, once the verdict's row names it (below):
      -- read by its author and the Tribunal alone until its appeal is upheld or 30 days pass unappealed,
      -- and only then deleted as before; given back whole if the verdict is overturned (H-B10).
      CASE
        WHEN public.withheld_kind(v_content_type) IS NOT NULL THEN
          NULL;
        WHEN v_content_type = 'lounge_message' THEN
          UPDATE lounge_messages
             SET content = '', deleted_at = now()
           WHERE id = v_content_id AND deleted_at IS NULL;
        -- A page is a member's, not a piece: what is taken is what they wrote on it, never the page.
        -- Its words, the name it shows, its picture and its links; its handle stays (a ban answers that).
        WHEN v_content_type = 'profile' THEN
          UPDATE profiles
             SET bio = NULL, display_name = NULL, avatar_url = NULL, social_links = '{}'::jsonb
           WHERE id = v_content_id;
        -- A salon is a place: what is taken is what it is called and shows, never its rooms or the
        -- words members left in it.
        WHEN v_content_type = 'lounge' THEN
          UPDATE lounges
             SET name = 'An Unnamed Salon', description = '', cover_image = NULL
           WHERE id = v_content_id;
        ELSE
          RAISE EXCEPTION 'Cannot remove content of type %', COALESCE(v_content_type, 'unknown')
            USING ERRCODE = 'P0001';
      END CASE;

    WHEN 'dismiss' THEN
      NULL;

    ELSE
      RAISE EXCEPTION 'Unknown moderation action: %', p_action USING ERRCODE = 'P0001';
  END CASE;

  INSERT INTO mod_actions (report_id, target_user_id, admin_id, action, reason,
                           duration_hours, expires_at, content_snapshot)
  VALUES (p_report_id, v_target_user_id, v_admin_id, p_action, p_reason,
          p_duration_hours, v_expires_at, v_snapshot)
  RETURNING id INTO v_action_id;

  -- Withheld under the verdict that names it, which keys its register (H-B10).
  IF p_action = 'delete_content' AND public.withheld_kind(v_content_type) IS NOT NULL THEN
    PERFORM public.withhold_piece(v_action_id, public.withheld_kind(v_content_type), v_content_id);
  END IF;

  IF p_notify_user THEN
    IF v_reporter_id IS NOT NULL THEN
      INSERT INTO notifications (user_id, type, title, body, message, metadata)
      VALUES (
        v_reporter_id,
        'moderation',
        'Your Report Was Reviewed',
        'Thank you for looking after the house. Your report was reviewed, and the matter is settled.',
        'Thank you for looking after the house. Your report was reviewed, and the matter is settled.',
        jsonb_build_object('report_id', p_report_id, 'action', p_action)
      );
    END IF;

    IF p_action != 'dismiss' AND v_target_user_id IS NOT NULL THEN
      v_notice := CASE p_action
        WHEN 'warn' THEN 'After reviewing a report, the house has issued a formal warning.'
        WHEN 'suspend' THEN 'After reviewing a report, the house has paused your membership for ' || COALESCE(p_duration_hours::text, 'a number of') || ' hours.'
        WHEN 'mute_user' THEN 'After reviewing a report, the house has muted your account for a time.'
        WHEN 'ban' THEN 'After reviewing a report, the house has closed your membership until further notice.'
        WHEN 'permanent_exile' THEN 'After reviewing a report, the house has permanently closed your membership.'
        WHEN 'delete_content' THEN CASE v_content_type
          WHEN 'profile' THEN 'After reviewing a report, the house has cleared the words and picture on your page.'
          WHEN 'lounge' THEN 'After reviewing a report, the house has cleared the name, description and cover of your salon.'
          WHEN 'lounge_message' THEN 'After reviewing a report, the house has removed a piece of your content.'
          ELSE 'After reviewing a report, the house has withheld a piece of your content: no one but you can see it. '
               || 'It is kept whole for 30 days, and until your appeal is heard if you appeal; unappealed, it is deleted then. '
               || 'Open this notice in the current app to read the verdict whole, the day and hour it is kept until, and to appeal.' END
        ELSE 'The house has reviewed a report concerning your account.'
      END
      -- A shorter sentence than the one standing: the member is told the longer one stands, and to when.
      || CASE WHEN p_action IN ('suspend', 'mute_user') AND NOT v_held_banned
                   AND v_held_until IS NOT NULL AND v_held_until >= v_expires_at
              THEN ' The longer pause already in place stands, to '
                   || to_char(v_held_until AT TIME ZONE 'UTC', 'DD Mon YYYY HH24:MI "UTC"') || '.'
              ELSE '' END
      || ' Reason: ' || p_reason;

      INSERT INTO notifications (user_id, type, title, body, message, metadata)
      VALUES (
        v_target_user_id,
        'moderation',
        'A Notice from the House',
        v_notice,
        v_notice,
        jsonb_build_object('action', p_action, 'reason', p_reason, 'expires_at', v_expires_at, 'mod_action_id', v_action_id)
      );
    END IF;
  END IF;
END;
$$;


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


--
-- Name: salon_channel_readable(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salon_channel_readable(p_topic text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT CASE
    WHEN p_topic ~ '^lounge-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN EXISTS (
      SELECT 1 FROM public.lounges l
       WHERE l.id = substr(p_topic, 8)::uuid
         AND (l.is_private = false OR EXISTS (
           SELECT 1 FROM public.lounge_members m
            WHERE m.lounge_id = l.id AND m.user_id = auth.uid() AND m.status IN ('approved', 'muted'))))
    ELSE false
  END
$_$;


--
-- Name: salon_channel_seated(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salon_channel_seated(p_topic text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT CASE
    WHEN p_topic ~ '^lounge-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN EXISTS (
      SELECT 1 FROM public.lounge_members m
       WHERE m.lounge_id = substr(p_topic, 8)::uuid AND m.user_id = auth.uid() AND m.status = 'approved')
    ELSE false
  END
$_$;


--
-- Name: lists; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lists (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    is_ranked boolean DEFAULT false,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT now(),
    is_private boolean DEFAULT false,
    withheld_at timestamp with time zone,
    CONSTRAINT lists_description_len CHECK ((char_length(description) <= 1000)),
    CONSTRAINT lists_title_len CHECK ((char_length(title) <= 100))
);


--
-- Name: COLUMN lists.withheld_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lists.withheld_at IS 'Withheld by the house (withheld_pieces): read by its author alone until deleted or given back. Written by the house alone.';


--
-- Name: save_stack(uuid, text, text, boolean, boolean, jsonb, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_stack(p_id uuid, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_is_private boolean DEFAULT NULL::boolean, p_is_ranked boolean DEFAULT NULL::boolean, p_films jsonb DEFAULT NULL::jsonb, p_create boolean DEFAULT false, p_read_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.lists
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.lists;
  v_at timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;

  -- An edit of a stack changed since the phone read it is refused, never laid over the change.
  IF NOT p_create AND p_read_at IS NOT NULL THEN
    SELECT updated_at INTO v_at FROM public.lists WHERE id = p_id AND user_id = v_uid FOR UPDATE;
    IF FOUND AND v_at > p_read_at THEN
      RAISE EXCEPTION 'This stack was changed after this phone read it.' USING ERRCODE = 'PT412';
    END IF;
  END IF;

  IF p_create THEN
    INSERT INTO public.lists (id, user_id, title, description, is_private, is_ranked)
    VALUES (p_id, v_uid, COALESCE(p_title, ''), COALESCE(p_description, ''),
            COALESCE(p_is_private, false), COALESCE(p_is_ranked, false))
    ON CONFLICT (id) DO NOTHING;
  ELSE
    UPDATE public.lists
       SET title       = COALESCE(p_title, title),
           description = COALESCE(p_description, description),
           is_private  = COALESCE(p_is_private, is_private),
           is_ranked   = COALESCE(p_is_ranked, is_ranked)
     WHERE id = p_id AND user_id = v_uid;
  END IF;

  SELECT * INTO v_row FROM public.lists WHERE id = p_id AND user_id = v_uid;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No such stack of yours' USING ERRCODE = 'P0002';
  END IF;

  IF p_films IS NOT NULL THEN
    -- Exactly these films, in this order.
    INSERT INTO public.list_items (list_id, film_id, film_title, poster_path, rank_position)
    SELECT p_id, (f->>'film_id')::int, COALESCE(f->>'film_title', 'Unknown'), f->>'poster_path', (f->>'rank_position')::int
      FROM jsonb_array_elements(p_films) AS f
    ON CONFLICT (list_id, film_id) DO UPDATE
       SET film_title = EXCLUDED.film_title,
           poster_path = EXCLUDED.poster_path,
           rank_position = EXCLUDED.rank_position;

    DELETE FROM public.list_items
     WHERE list_id = p_id
       AND film_id NOT IN (SELECT (f->>'film_id')::int FROM jsonb_array_elements(p_films) AS f);
  END IF;

  -- Read again: the films' triggers have moved its time, which the phone keeps for its next edit.
  SELECT * INTO v_row FROM public.lists WHERE id = p_id AND user_id = v_uid;
  RETURN v_row;
END;
$$;


--
-- Name: search_logs(text, text, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_logs(p_pattern text, p_handle text DEFAULT NULL::text, p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, user_id uuid, film_title text, review text, rating numeric, poster_path text, status text, abandoned_reason text, is_spoiler boolean, created_at timestamp with time zone, username text, role text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
DECLARE
  v_me      uuid := auth.uid();
  v_hidden  uuid[];
  v_limit   integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 51);
  v_words   text := '%' || p_pattern || '%';
  v_handle  text := CASE WHEN COALESCE(p_handle, '') <> '' THEN '%' || p_handle || '%' END;
  -- The cursor as one bound on (created_at, id), newest first: none is the newest record.
  v_at      timestamp with time zone := COALESCE(p_cursor_at, 'infinity'::timestamp with time zone);
  v_id      uuid := CASE WHEN p_cursor_at IS NULL THEN 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid ELSE p_cursor_id END;
  -- A trigram is three letters or digits in a row: without one, no index can find the words.
  v_pieces  boolean := p_pattern ~ '[[:alnum:]]{3}';
  v_authors uuid[] := '{}'::uuid[];
  v_many    boolean := false;
  v_page    uuid[];
BEGIN
  IF COALESCE(p_pattern, '') = '' THEN
    RETURN;
  END IF;
  v_hidden := COALESCE((SELECT private.hidden_authors()), '{}'::uuid[]);

  -- 1. The members the handle finds.
  IF v_handle IS NOT NULL THEN
    SELECT COALESCE(array_agg(a.id), '{}'::uuid[]) INTO v_authors
      FROM (SELECT pa.id FROM public.profiles pa WHERE pa.username ILIKE v_handle ESCAPE '\' LIMIT 1001) a;
    v_many := cardinality(v_authors) > 1000;
  END IF;

  -- 2. The newest 5,000 reviewed records after the cursor, each asked the words; the rule asked of
  -- the records found.
  SELECT array_agg(w.id ORDER BY w.created_at DESC, w.id DESC) INTO v_page
    FROM (SELECT r.id, r.created_at
            FROM (SELECT l.id, l.created_at, l.user_id, l.film_title, l.review
                    FROM public.logs l
                   WHERE l.review IS NOT NULL AND l.review <> '' AND l.withheld_at IS NULL
                     AND (l.created_at, l.id) < (v_at, v_id)
                   ORDER BY l.created_at DESC, l.id DESC
                   LIMIT 5000) r
            JOIN public.profiles p ON p.id = r.user_id
           WHERE (r.film_title ILIKE v_words ESCAPE '\' OR r.review ILIKE v_words ESCAPE '\'
                  OR r.user_id = ANY (v_authors)
                  OR (v_many AND EXISTS (SELECT 1 FROM public.profiles pa
                                          WHERE pa.id = r.user_id AND pa.username ILIKE v_handle ESCAPE '\')))
             AND NOT (r.user_id = ANY (v_hidden))
             AND (r.user_id = v_me OR NOT COALESCE(p.is_social_private, false) OR private.can_view_user_data(r.user_id))
           ORDER BY r.created_at DESC, r.id DESC
           LIMIT v_limit) w;
  IF COALESCE(cardinality(v_page), 0) >= v_limit THEN
    NULL;
  ELSIF v_pieces THEN
    -- 3. Not full within the walk: the words are rare, and every record holding them is read by its pieces.
    SELECT array_agg(w.id ORDER BY w.created_at DESC, w.id DESC) INTO v_page
      FROM (SELECT m.id, m.created_at
              FROM (SELECT l.id, l.created_at, l.user_id
                      FROM public.logs l
                     WHERE l.review IS NOT NULL AND l.review <> '' AND l.withheld_at IS NULL
                       AND (l.film_title ILIKE v_words ESCAPE '\' OR l.review ILIKE v_words ESCAPE '\')
                    UNION
                    SELECT l.id, l.created_at, l.user_id
                      FROM public.logs l
                     WHERE NOT v_many AND l.user_id = ANY (v_authors)
                       AND l.review IS NOT NULL AND l.review <> '' AND l.withheld_at IS NULL
                    UNION
                    SELECT l.id, l.created_at, l.user_id
                      FROM public.profiles pa
                      JOIN public.logs l ON l.user_id = pa.id
                     WHERE v_many AND pa.username ILIKE v_handle ESCAPE '\'
                       AND l.review IS NOT NULL AND l.review <> '' AND l.withheld_at IS NULL) m
              JOIN public.profiles p ON p.id = m.user_id
             WHERE (m.created_at, m.id) < (v_at, v_id)
               AND NOT (m.user_id = ANY (v_hidden))
               AND (m.user_id = v_me OR NOT COALESCE(p.is_social_private, false) OR private.can_view_user_data(m.user_id))
             ORDER BY m.created_at DESC, m.id DESC
             LIMIT v_limit) w;
  ELSE
    -- 4. No trigram, and not full within the walk: every reviewed record is read once, in the table's
    -- own order (no index can find the words, and walking them newest first reads each by its index,
    -- some seven times slower), and the newest found make the page. The words and the order are said
    -- so no index answers either.
    SELECT array_agg(w.id ORDER BY w.created_at DESC, w.id DESC) INTO v_page
      FROM (SELECT l.id, l.created_at
              FROM public.logs l
              JOIN public.profiles p ON p.id = l.user_id
             WHERE l.review IS NOT NULL AND l.review <> '' AND l.withheld_at IS NULL
               AND (l.created_at, l.id) < (v_at, v_id)
               AND ((l.film_title || '') ILIKE v_words ESCAPE '\' OR (l.review || '') ILIKE v_words ESCAPE '\'
                    OR l.user_id = ANY (v_authors)
                    OR (v_many AND p.username ILIKE v_handle ESCAPE '\'))
               AND NOT (l.user_id = ANY (v_hidden))
               AND (l.user_id = v_me OR NOT COALESCE(p.is_social_private, false) OR private.can_view_user_data(l.user_id))
             ORDER BY (l.created_at + interval '0 seconds') DESC, l.id DESC
             LIMIT v_limit) w;
  END IF;

  RETURN QUERY
  SELECT l.id, l.user_id, l.film_title, l.review, l.rating, l.poster_path, l.status, l.abandoned_reason,
         COALESCE(l.is_spoiler, false), l.created_at, p.username, p.role
    FROM unnest(v_page) WITH ORDINALITY AS g(log_id, n)
    JOIN public.logs l ON l.id = g.log_id
    JOIN public.profiles p ON p.id = l.user_id
   ORDER BY g.n;
END $$;


--
-- Name: search_members(text, boolean, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_members(p_pattern text, p_handles_only boolean DEFAULT false, p_cursor_closeness integer DEFAULT NULL::integer, p_cursor_username text DEFAULT NULL::text, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, username text, avatar_url text, role text, closeness integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 51);
  v_names  boolean := NOT COALESCE(p_handles_only, false);
  v_hidden uuid[];
  v_tests  text[];
  v_few    uuid[];
  v_past   text;
  v_tier   integer;
  v_not    text := '';
  v_got    integer := 0;
  v_n      integer;
  v_short  text := '';
  v_many   boolean;
  v_walk   boolean;
  v_bitmap text := current_setting('enable_bitmapscan');
  v_sort   text := current_setting('enable_sort');
  v_seq    text := current_setting('enable_seqscan');
  v_index  text := current_setting('enable_indexscan');
  -- The words' letters before their first wildcard, their escapes read: where a handle beginning with them starts.
  v_lead   text := regexp_replace(substring(COALESCE(p_pattern, '') from '^((?:[^%_\\]|\\.)*)'), '\\(.)', '\1', 'g');
  -- The words' pieces of three (private.member_pattern_grams): every holder of the words holds each,
  -- anywhere ("a") or, for a search of handles alone, in the handle ("h"). Only once the job has listed
  -- every member (private.member_grams_filled), and the reader's own transaction has no member's write
  -- waiting to be settled (settled as it commits, so the lists do not hold them yet): until then,
  -- searched as before.
  v_grams  text[] := CASE WHEN COALESCE(current_setting('reelhouse.member_grams_queued', true), '')
                               = COALESCE(current_setting('reelhouse.member_grams_settled', true), '')
                           AND (SELECT f.complete FROM private.member_grams_filled f)
                          THEN (SELECT array_agg((CASE WHEN COALESCE(p_handles_only, false) THEN 'h' ELSE 'a' END || g) COLLATE "C")
                                  FROM unnest(private.member_pattern_grams(COALESCE(p_pattern, ''))) g) END;
  v_known  integer;
  v_rare   integer;
  v_gram   text;
  v_upto   text;
  v_listed boolean := false;
  -- How many a gathering keeps before the handles are walked instead (a thousand); with a list, its cap
  -- (a thousand): the list is walked instead.
  v_wide   integer := 1000;
BEGIN
  IF COALESCE(p_pattern, '') = '' THEN
    RETURN;
  END IF;
  v_hidden := COALESCE((SELECT private.hidden_authors())::uuid[], '{}'::uuid[]);
  -- Each closeness's own test, as the one read's CASE asked it. Plain, so the planner reads the words
  -- and their indexes: a WHERE drops a test that is unknown (a name not given), as the CASE did.
  -- The handle that is the words: words with no wildcard left once their escapes are read are one
  -- handle, any case, so the case-blind unique index (profiles_username_lower_unique) finds it at once
  -- (ILIKE is that same lower() on both sides: the equality adds no member and takes none away).
  -- A handle or a name that begins with the words is asked the same of its lower case (ILIKE is lower()
  -- LIKE lower()), so its beginning is found in profiles_username_beginning (20261122_22) or
  -- profiles_display_name_beginning (20261122_17), never by the trigram of a word's start that every
  -- handle or name holding such a word anywhere also holds.
  v_tests := ARRAY[
    format('p.username ILIKE %L ESCAPE %L', p_pattern, '\')
      || CASE WHEN regexp_replace(p_pattern, '\\.', '', 'g') !~ '[%_\\]'
              THEN format(' AND lower(p.username) = lower(%L)', regexp_replace(p_pattern, '\\(.)', '\1', 'g')) ELSE '' END,
    -- A beginning is asked as one range of its lower case alone: the ILIKE inside COALESCE, which no index
    -- reads, so the planner never gathers by the trigram of a word's start (a handle beginning with "m1"
    -- gathered all 11,112 of 100,000 before the first thousand were kept). Unknown only where the column
    -- is, so a member with no name is ruled in or out as before.
    format('COALESCE(p.username ILIKE %L ESCAPE %L, false) AND lower(p.username) LIKE %L ESCAPE %L', p_pattern || '%', '\', lower(p_pattern) || '%', '\'),
    CASE WHEN v_names THEN format('COALESCE(p.display_name ILIKE %L ESCAPE %L, false) AND lower(p.display_name) LIKE %L ESCAPE %L', p_pattern || '%', '\', lower(p_pattern) || '%', '\') ELSE 'false' END,
    format('(p.username ILIKE %L ESCAPE %L', '%' || p_pattern || '%', '\')
      || CASE WHEN v_names THEN format(' OR p.display_name ILIKE %L ESCAPE %L)', '%' || p_pattern || '%', '\') ELSE ')' END
  ];
  IF v_grams IS NOT NULL THEN
    -- Words with a piece of three: the pieces' heads say who could hold them. A piece no member holds:
    -- no member holds the words, in any closeness.
    SELECT count(*), min(h.holders) FILTER (WHERE substr(h.gram, 2) ~ '^[[:alnum:]]{3}$') INTO v_known, v_rare
      FROM private.member_gram_heads h WHERE h.gram = ANY (v_grams) AND h.holders > 0;
    IF v_known < cardinality(v_grams) THEN
      RETURN;
    END IF;
    -- The list read: the smallest of those that list every holder; else the one listing furthest into
    -- the handles (its holders of the words are exact up to its last, and a page is likeliest met there).
    SELECT h.gram, h.upto INTO v_gram, v_upto
      FROM private.member_gram_heads h WHERE h.gram = ANY (v_grams)
     ORDER BY h.upto IS NOT NULL, CASE WHEN h.upto IS NULL THEN h.holders END, h.upto DESC
     LIMIT 1;
    v_listed := true;
    v_many := false;
    SELECT f.cap INTO v_wide FROM private.member_grams_filled f;
    IF v_upto IS NULL THEN
      -- It lists every holder: whoever holds the words is among them, a thousand at most.
      EXECUTE format('SELECT array_agg(p.id) FROM private.member_grams g JOIN public.profiles p ON p.id = g.id WHERE g.gram = $2 AND COALESCE(%s, false) AND NOT COALESCE(p.id = ANY ($1), false)',
                     v_tests[4])
        INTO v_few USING v_hidden, v_gram;
    ELSIF v_rare <= 5 * v_wide THEN
      -- Its rarest piece of three letters or digits is held by 5,000 or fewer: the trigram indexes gather
      -- no more than they hold of it (a bitmap of all the words' trigrams, never a walk or a scan).
      PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_indexscan', 'off', true);
      EXECUTE format('SELECT array_agg(p.id) FROM (SELECT p.id FROM public.profiles p WHERE %s AND NOT COALESCE(p.id = ANY ($1), false) LIMIT %s) p',
                     v_tests[4], v_wide + 1)
        INTO v_few USING v_hidden;
      PERFORM set_config('enable_seqscan', v_seq, true); PERFORM set_config('enable_indexscan', v_index, true);
    ELSE
      -- Held by more: who holds the words anywhere is walked in the list at once, never gathered.
      v_many := true;
    END IF;
  ELSE
    -- Words without three letters or digits in a row hold no trigram inside a handle or a name: the
    -- gatherings of who holds them anywhere (the one read's own, and the last closeness) then read by
    -- their one- and two-letter pieces (profiles_short_grams), never member by member through the house,
    -- the words' own test asked inside COALESCE so no plan reads a trigram index for them whole. A handle
    -- or a name that begins with them is found by its trigrams as before (a beginning has its own).
    IF p_pattern !~ '[[:alnum:]]{3}' AND private.pattern_grams(p_pattern) IS NOT NULL THEN
      v_short := format(' AND private.search_grams(p.username, p.display_name) @> %L::text[]', private.pattern_grams(p_pattern));
    END IF;
    -- Many or few, first, by a walk that reads the same number of members at any size of the house: the
    -- first 2,000 handles in their own order (profiles_username_unique), each asked the words' own test.
    -- When 20 or more of them hold the words (one in a hundred), so many do that each closeness's page is
    -- met by walking the handles in order within a few thousand, and the indexes of the pieces and the
    -- trigrams, which gather every member who holds the words before the first is read (22,248 for "m1",
    -- 81,929 for "1" at 100,000 members), are not read for them.
    EXECUTE format('SELECT count(*) FROM (SELECT p.id, p.username, p.display_name FROM public.profiles p ORDER BY p.username LIMIT 2000) p WHERE COALESCE(%s, false) AND NOT COALESCE(p.id = ANY ($1), false)',
                   v_tests[4])
      INTO v_n USING v_hidden;
    v_many := v_n >= 20;
    -- Fewer: who holds the words at all (the one read's own WHERE), gathered once by the plan the words
    -- want, up to a thousand: when fewer hold them, the page is the one read's own over just those few, by id.
    IF NOT v_many THEN
      EXECUTE format('SELECT array_agg(p.id) FROM (SELECT p.id FROM public.profiles p WHERE %s%s AND NOT COALESCE(p.id = ANY ($1), false) LIMIT 1001) p',
                     CASE WHEN v_short = '' THEN v_tests[4] ELSE format('COALESCE(%s, false)', v_tests[4]) END, v_short)
        INTO v_few USING v_hidden;
    END IF;
  END IF;
  IF NOT v_many AND COALESCE(cardinality(v_few), 0) <= v_wide THEN
    RETURN QUERY
    SELECT m.id, m.username, m.avatar_url, m.role, m.closeness
      FROM (
        SELECT p.id, p.username, p.avatar_url, p.role,
               CASE WHEN p.username ILIKE p_pattern ESCAPE '\' THEN 0
                    WHEN p.username ILIKE p_pattern || '%' ESCAPE '\' THEN 1
                    WHEN v_names AND p.display_name ILIKE p_pattern || '%' ESCAPE '\' THEN 2
                    ELSE 3 END AS closeness
          FROM public.profiles p
         WHERE p.id = ANY (COALESCE(v_few, '{}'::uuid[]))
      ) m
     WHERE p_cursor_closeness IS NULL OR (m.closeness, m.username) > (p_cursor_closeness, p_cursor_username)
     ORDER BY m.closeness, m.username
     LIMIT v_limit;
    RETURN;
  END IF;
  -- More hold them: each closeness in turn, as far as the page needs. A member of a closeness meets its
  -- test and none of the closer ones; in the cursor's own closeness, it is past the cursor's handle (a
  -- member with no handle is never past it). Its members are gathered first, up to a thousand, by the
  -- plan the words want: fewer, and they are put in handle order themselves; more, and the closeness
  -- holds so many that its handles are walked in their own order (profiles_username_unique) and the
  -- page is met within the first few hundred. The walk asks its test as one the planner cannot weigh
  -- (COALESCE), so it is planned as a walk however few it guesses: its guess of a name's beginning
  -- once took 100,000 for 4, and sorted them all. When the first walk found many, the last closeness
  -- (who holds the words anywhere) is walked at once, never gathered.
  -- Words with a piece of three walk a name's beginning and the words anywhere in the piece's list
  -- instead (every member of those closenesses holds the piece), never the handles.
  FOR v_tier IN 0..3 LOOP
    IF (p_cursor_closeness IS NULL OR v_tier >= p_cursor_closeness) AND v_tests[v_tier + 1] <> 'false' THEN
      v_past := CASE WHEN v_tier = p_cursor_closeness THEN format(' AND p.username > %L', p_cursor_username) ELSE '' END;
      v_walk := v_many AND v_tier = 3;
      IF NOT v_walk THEN
        -- A beginning is gathered in its index's own order (USING ~<~, as text_pattern_ops holds it), so the
        -- range is read row by row and stops at its thousand and one, never gathered whole first: no bitmap
        -- for this one statement (a bitmap gathers the whole range before the first row is kept), set back
        -- as it was at once, so the trigram and short pieces' gatherings, which only a bitmap reads, are not touched.
        -- The words anywhere, when a list stands for them, are gathered by a bitmap alone (no more than the
        -- trigram indexes hold of a piece 5,000 or fewer hold).
        IF v_tier IN (1, 2) THEN PERFORM set_config('enable_bitmapscan', 'off', true); PERFORM set_config('enable_sort', 'off', true); END IF;
        IF v_tier = 3 AND v_listed THEN PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_indexscan', 'off', true); END IF;
        EXECUTE format('SELECT array_agg(p.id) FROM (SELECT p.id FROM public.profiles p WHERE %s%s%s%s AND NOT COALESCE(p.id = ANY ($1), false)%s LIMIT %s) p',
                       CASE WHEN v_short = '' OR v_tier < 3 THEN v_tests[v_tier + 1] ELSE format('COALESCE(%s, false)', v_tests[v_tier + 1]) END, v_not, v_past,
                       CASE WHEN v_tier = 3 THEN v_short ELSE '' END,
                       CASE v_tier WHEN 1 THEN ' ORDER BY lower(p.username) USING ~<~' WHEN 2 THEN ' ORDER BY lower(p.display_name) USING ~<~' ELSE '' END,
                       v_wide + 1)
          INTO v_few USING v_hidden;
        IF v_tier IN (1, 2) THEN PERFORM set_config('enable_bitmapscan', v_bitmap, true); PERFORM set_config('enable_sort', v_sort, true); END IF;
        IF v_tier = 3 AND v_listed THEN PERFORM set_config('enable_seqscan', v_seq, true); PERFORM set_config('enable_indexscan', v_index, true); END IF;
        v_walk := COALESCE(cardinality(v_few), 0) > v_wide;
      END IF;
      IF NOT v_walk THEN
        RETURN QUERY
        SELECT p.id, p.username, p.avatar_url, p.role, v_tier
          FROM public.profiles p
         WHERE p.id = ANY (COALESCE(v_few, '{}'::uuid[]))
         ORDER BY p.username
         LIMIT v_limit - v_got;
      ELSIF v_listed AND v_tier IN (2, 3) THEN
        -- Walked in the list, in handle order, from the cursor: exact up to the list's last handle. A page
        -- it cannot meet lies past it, where only more letters can narrow the search: said, never read.
        RETURN QUERY EXECUTE format(
          'SELECT p.id, p.username, p.avatar_url, p.role, %s
             FROM private.member_grams g JOIN public.profiles p ON p.id = g.id
            WHERE g.gram = $2%s
              AND COALESCE(%s, false)%s%s
              AND NOT COALESCE(p.id = ANY ($1), false)
            ORDER BY g.username
            LIMIT %s',
          v_tier, CASE WHEN v_tier = p_cursor_closeness THEN format(' AND g.username > %L', p_cursor_username) ELSE '' END,
          v_tests[v_tier + 1], v_not, v_past, v_limit - v_got)
        USING v_hidden, v_gram;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n < v_limit - v_got AND v_upto IS NOT NULL THEN
          RAISE EXCEPTION 'TOO_WIDE' USING ERRCODE = '54000', HINT = 'More letters narrow the search.';
        END IF;
      ELSE
        -- A handle that begins with the words is walked from where such handles start: every one sorts at
        -- or after the words' letters before any wildcard, in upper or lower case, whichever sorts first
        -- (in any collation a word sorts after its own beginning, and a case changes no letter's place
        -- among the others), so the walk never reads every handle before them ("m19" read 10,000 first).
        RETURN QUERY EXECUTE format(
          'SELECT p.id, p.username, p.avatar_url, p.role, %s
             FROM public.profiles p
            WHERE COALESCE(%s, false)%s%s%s
              AND NOT COALESCE(p.id = ANY ($1), false)
            ORDER BY p.username
            LIMIT %s',
          v_tier, v_tests[v_tier + 1], v_not, v_past,
          CASE WHEN v_tier = 1 AND v_lead <> '' THEN format(' AND p.username >= LEAST(upper(%L), lower(%L))', v_lead, v_lead) ELSE '' END,
          v_limit - v_got)
        USING v_hidden;
      END IF;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_got := v_got + v_n;
      EXIT WHEN v_got >= v_limit;
    END IF;
    -- A closer test ruled out: one that is unknown was not met, so it rules nothing out.
    v_not := v_not || ' AND NOT COALESCE(' || v_tests[v_tier + 1] || ', false)';
  END LOOP;
END;
$_$;


--
-- Name: search_stacks(text, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_stacks(p_pattern text, p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20) RETURNS TABLE(id uuid, user_id uuid, title text, description text, is_ranked boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    SET plan_cache_mode TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
DECLARE
  v_me     uuid := auth.uid();
  v_hidden uuid[];
  v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 51);
  v_words  text := '%' || p_pattern || '%';
  -- The cursor as one bound on (created_at, id), newest first: none is the newest stack.
  v_at     timestamp with time zone := COALESCE(p_cursor_at, 'infinity'::timestamp with time zone);
  v_id     uuid := CASE WHEN p_cursor_at IS NULL THEN 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid ELSE p_cursor_id END;
  -- A trigram is three letters or digits in a row: without one, no index can find the words.
  v_pieces boolean := p_pattern ~ '[[:alnum:]]{3}';
  -- Without one, the words' one- and two-letter pieces (lists_short_grams): none when all wildcards.
  -- Read by them, the words' own test is asked inside COALESCE, so no plan reads a trigram index whole.
  v_grams  text[] := CASE WHEN p_pattern !~ '[[:alnum:]]{3}' THEN private.pattern_grams('%' || p_pattern || '%') END;
  v_few    boolean := false;
  v_page   uuid[];
BEGIN
  IF COALESCE(p_pattern, '') = '' THEN
    RETURN;
  END IF;
  v_hidden := COALESCE((SELECT private.hidden_authors()), '{}'::uuid[]);

  -- 1. Counted by the trigram indexes, or by the short pieces, to 1,000.
  IF v_grams IS NOT NULL THEN
    SELECT count(*) < 1000 INTO v_few
      FROM (SELECT 1 FROM public.lists l
             WHERE l.is_private = false AND l.withheld_at IS NULL
               AND private.search_grams(l.title, l.description) @> v_grams
               AND COALESCE((l.title ILIKE v_words ESCAPE '\' OR l.description ILIKE v_words ESCAPE '\'), false)
             LIMIT 1000) c;
  ELSIF v_pieces THEN
    SELECT count(*) < 1000 INTO v_few
      FROM (SELECT 1 FROM public.lists l
             WHERE l.is_private = false AND l.withheld_at IS NULL
               AND (l.title ILIKE v_words ESCAPE '\' OR l.description ILIKE v_words ESCAPE '\')
             LIMIT 1000) c;
  END IF;

  IF v_few THEN
    -- 2. The few stacks that hold the words, newest first, the rule asked of each in that order.
    SELECT array_agg(w.id ORDER BY w.created_at DESC, w.id DESC) INTO v_page
      FROM (SELECT m.id, m.created_at
              FROM (SELECT l.id, l.created_at, l.user_id
                      FROM public.lists l
                     WHERE l.is_private = false AND l.withheld_at IS NULL
                       AND (v_grams IS NULL OR private.search_grams(l.title, l.description) @> v_grams)
                       AND CASE WHEN v_grams IS NULL THEN (l.title ILIKE v_words ESCAPE '\' OR l.description ILIKE v_words ESCAPE '\') ELSE COALESCE((l.title ILIKE v_words ESCAPE '\' OR l.description ILIKE v_words ESCAPE '\'), false) END
                       AND (l.created_at, l.id) < (v_at, v_id)
                    -- Read by the indexes and sorted before any stack is asked the rule.
                    OFFSET 0) m
              LEFT JOIN public.profiles p ON p.id = m.user_id
             WHERE NOT (m.user_id = ANY (v_hidden))
               AND (m.user_id = v_me
                    OR (p.id IS NOT NULL AND NOT COALESCE(p.is_social_private, false))
                    OR private.can_view_user_data(m.user_id))
             ORDER BY m.created_at DESC, m.id DESC
             LIMIT v_limit) w;
  ELSE
    -- 3. Many, or no piece at all: the public stacks newest first, each asked the words, then the rule.
    SELECT array_agg(w.id ORDER BY w.created_at DESC, w.id DESC) INTO v_page
      FROM (SELECT l.id, l.created_at
              FROM public.lists l
              LEFT JOIN public.profiles p ON p.id = l.user_id
             WHERE l.is_private = false AND l.withheld_at IS NULL
               AND (l.created_at, l.id) < (v_at, v_id)
               AND (l.title ILIKE v_words ESCAPE '\' OR l.description ILIKE v_words ESCAPE '\')
               AND NOT (l.user_id = ANY (v_hidden))
               AND (l.user_id = v_me
                    OR (p.id IS NOT NULL AND NOT COALESCE(p.is_social_private, false))
                    OR private.can_view_user_data(l.user_id))
             ORDER BY l.created_at DESC, l.id DESC
             LIMIT v_limit) w;
  END IF;

  RETURN QUERY
  SELECT l.id, l.user_id, l.title, l.description, l.is_ranked, l.created_at
    FROM unnest(v_page) WITH ORDINALITY AS g(list_id, n)
    JOIN public.lists l ON l.id = g.list_id
   ORDER BY g.n;
END $$;


--
-- Name: send_salon_typing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_salon_typing(p_lounge_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_handle text;
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.lounge_members m
     WHERE m.lounge_id = p_lounge_id AND m.user_id = v_uid AND m.status = 'approved'
  ) THEN
    RETURN false;
  END IF;

  INSERT INTO public.salon_typing_sent AS t (lounge_id, user_id, sent_at)
  VALUES (p_lounge_id, v_uid, clock_timestamp())
  ON CONFLICT (lounge_id, user_id) DO UPDATE SET sent_at = EXCLUDED.sent_at
   WHERE t.sent_at <= EXCLUDED.sent_at - interval '2 seconds';
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  SELECT p.username INTO v_handle FROM public.profiles p WHERE p.id = v_uid;
  PERFORM realtime.send(jsonb_build_object('user_id', v_uid, 'username', v_handle), 'typing',
                        'lounge-' || p_lounge_id::text, true);
  RETURN true;
END;
$$;


--
-- Name: set_lobby_withheld(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lobby_withheld(p_kind text, p_target uuid, p_keep_off boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;
  IF p_kind NOT IN ('log', 'list', 'post') OR p_target IS NULL THEN
    RAISE EXCEPTION 'Nothing to keep: a kind (log, list, post) and a piece' USING ERRCODE = '22023';
  END IF;

  IF p_keep_off THEN
    INSERT INTO public.lobby_withheld (kind, target_id, withheld_by)
    VALUES (p_kind, p_target, auth.uid())
    ON CONFLICT (kind, target_id) DO NOTHING;
    -- off every wall at once, the honour with it, and the notice that announced it
    DELETE FROM public.lobby_editions WHERE slot = p_kind AND target_id = p_target;
    DELETE FROM public.notifications WHERE type = 'featured' AND group_key = 'lobby:' || p_kind || ':' || p_target;
  ELSE
    -- it may be chosen again from the next edition; the days it lost are not restored
    DELETE FROM public.lobby_withheld WHERE kind = p_kind AND target_id = p_target;
  END IF;
END;
$$;


--
-- Name: FUNCTION set_lobby_withheld(p_kind text, p_target uuid, p_keep_off boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_lobby_withheld(p_kind text, p_target uuid, p_keep_off boolean) IS 'An admin keeps a piece off the Lobby (true) or lets it be chosen again (false).';


--
-- Name: set_lounge_cover(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lounge_cover(p_lounge_id uuid, p_cover_image text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM lounges WHERE id = p_lounge_id AND creator_id = v_uid) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_cover_image IS NOT NULL AND p_cover_image !~ '^/[A-Za-z0-9._-]+$' THEN
    RAISE EXCEPTION 'Invalid cover path';
  END IF;
  UPDATE lounges SET cover_image = p_cover_image WHERE id = p_lounge_id;
END;
$_$;


--
-- Name: set_lounge_member_status(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lounge_member_status(p_lounge_id uuid, p_user_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_creator uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT creator_id INTO v_creator FROM public.lounges WHERE id = p_lounge_id;
  IF v_creator IS NULL THEN RAISE EXCEPTION 'Lounge not found'; END IF;
  IF auth.uid() IS DISTINCT FROM v_creator THEN RAISE EXCEPTION 'Only the host can do this'; END IF;
  IF p_user_id IS NOT DISTINCT FROM v_creator THEN RAISE EXCEPTION 'The host cannot be changed'; END IF;
  IF p_status NOT IN ('approved','muted','banned') THEN RAISE EXCEPTION 'Invalid status'; END IF;
  UPDATE public.lounge_members SET status = p_status WHERE lounge_id = p_lounge_id AND user_id = p_user_id;
  -- The record outlasts the seat: a ban or mute stands though the member leave.
  IF p_status IN ('muted', 'banned') THEN
    INSERT INTO public.lounge_sanctions (lounge_id, user_id, status) VALUES (p_lounge_id, p_user_id, p_status)
    ON CONFLICT (lounge_id, user_id) DO UPDATE SET status = EXCLUDED.status, set_at = now();
  ELSE
    DELETE FROM public.lounge_sanctions WHERE lounge_id = p_lounge_id AND user_id = p_user_id;
  END IF;
END $$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: sever_follows_on_block(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sever_follows_on_block() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.type = 'block' THEN
    -- The follows and the requests, both ways: a request left waiting could be admitted later.
    DELETE FROM public.interactions
    WHERE type IN ('follow', 'follow_request')
      AND ((user_id = NEW.blocker_id AND target_user_id = NEW.blocked_id)
        OR (user_id = NEW.blocked_id AND target_user_id = NEW.blocker_id));
    -- Each one's seat in the other's salons, both ways (a ban stays the host's).
    DELETE FROM public.lounge_members m
     USING public.lounges l
     WHERE l.id = m.lounge_id
       AND m.status IN ('approved', 'muted', 'pending')
       AND ((m.user_id = NEW.blocked_id AND l.creator_id = NEW.blocker_id)
         OR (m.user_id = NEW.blocker_id AND l.creator_id = NEW.blocked_id));
  END IF;
  RETURN NEW;
END $$;


--
-- Name: sign_in_attempt(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_in_attempt(p_handle text, p_door text, p_device text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid    uuid;
  v_door   text := NULLIF(left(coalesce(p_door, ''), 64), '');
  v_known  boolean := false;
  v_row    public.sign_in_doors;
  v_pail   public.sign_in_handles;
  v_tokens real;
  v_free   constant integer := 5;     -- wrong passwords a door may try in a day before it rests
  v_cap    constant real := 20;       -- the shared pail: attempts at once
  v_every  constant integer := 300;   -- and one more every 300 seconds
BEGIN
  -- The member the handle names, as get_email_by_username finds them; none, nothing is counted.
  SELECT p.id INTO v_uid
    FROM public.profiles p JOIN auth.users au ON au.id = p.id
   WHERE lower(p.username) = lower(coalesce(p_handle, ''))
   LIMIT 1;
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('wait', 0, 'door', false, 'pail', false);
  END IF;

  -- Rows long quiet are let go, a few at a time, never waiting on one an attempt holds.
  DELETE FROM public.sign_in_doors
   WHERE (user_id, door) IN (SELECT d.user_id, d.door FROM public.sign_in_doors d
                              WHERE d.last_at < now() - interval '1 day'
                              ORDER BY d.last_at LIMIT 20 FOR UPDATE SKIP LOCKED);
  DELETE FROM public.sign_in_devices
   WHERE token_hash IN (SELECT v.token_hash FROM public.sign_in_devices v
                         WHERE v.used_at < now() - interval '90 days'
                         ORDER BY v.used_at LIMIT 20 FOR UPDATE SKIP LOCKED);

  -- A phone the member's right password signed in on before: not held by the shared pail.
  IF p_device IS NOT NULL AND char_length(p_device) BETWEEN 32 AND 128 THEN
    v_known := EXISTS (SELECT 1 FROM public.sign_in_devices
                        WHERE token_hash = sha256(convert_to(p_device, 'UTF8')) AND user_id = v_uid
                          AND used_at >= now() - interval '90 days');
  END IF;

  -- 1. The door: resting, refused uncounted.
  IF v_door IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.sign_in_doors WHERE user_id = v_uid AND door = v_door)
       AND (SELECT count(*) FROM public.sign_in_doors WHERE user_id = v_uid) >= 64 THEN
      -- At most 64 doors per member: the least recent is let go.
      DELETE FROM public.sign_in_doors
       WHERE (user_id, door) IN (SELECT d.user_id, d.door FROM public.sign_in_doors d WHERE d.user_id = v_uid
                                  ORDER BY d.last_at LIMIT 1);
    END IF;
    INSERT INTO public.sign_in_doors (user_id, door, misses, last_at) VALUES (v_uid, v_door, 0, now())
    ON CONFLICT (user_id, door) DO NOTHING;
    SELECT * INTO v_row FROM public.sign_in_doors WHERE user_id = v_uid AND door = v_door FOR UPDATE;
    IF v_row.paused_until IS NOT NULL AND v_row.paused_until > now() THEN
      RETURN jsonb_build_object('wait', GREATEST(1, ceil(extract(epoch FROM v_row.paused_until - now()))::integer),
                                'from', 'here', 'door', false, 'pail', false);
    END IF;
    IF v_row.last_at < now() - interval '1 day' THEN
      v_row.misses := 0;  -- a day with no attempt from this door: its count starts again
    END IF;
  END IF;

  -- 2. The pail every door not known to the member shares: empty, refused uncounted.
  IF NOT v_known THEN
    INSERT INTO public.sign_in_handles (user_id, tokens, refilled_at) VALUES (v_uid, v_cap, now())
    ON CONFLICT (user_id) DO NOTHING;
    SELECT * INTO v_pail FROM public.sign_in_handles WHERE user_id = v_uid FOR UPDATE;
    v_tokens := LEAST(v_cap, v_pail.tokens + extract(epoch FROM now() - v_pail.refilled_at)::real / v_every);
    IF v_tokens < 1 THEN
      UPDATE public.sign_in_handles SET tokens = v_tokens, refilled_at = now() WHERE user_id = v_uid;
      RETURN jsonb_build_object('wait', GREATEST(1, ceil((1 - v_tokens) * v_every))::integer,
                                'from', 'elsewhere', 'door', false, 'pail', false);
    END IF;
    UPDATE public.sign_in_handles SET tokens = v_tokens - 1, refilled_at = now() WHERE user_id = v_uid;
  END IF;

  -- Counted at the door: from the fifth on, each rests it after, 1, 2, 4 ... 60 minutes.
  IF v_door IS NOT NULL THEN
    UPDATE public.sign_in_doors
       SET misses = v_row.misses + 1,
           last_at = now(),
           paused_until = CASE WHEN v_row.misses + 1 >= v_free
                               THEN now() + make_interval(mins => LEAST(60, power(2, LEAST(v_row.misses + 1 - v_free, 6))::integer))
                               ELSE NULL END
     WHERE user_id = v_uid AND door = v_door;
  END IF;
  RETURN jsonb_build_object('wait', 0, 'door', v_door IS NOT NULL, 'pail', NOT v_known);
END;
$$;


--
-- Name: FUNCTION sign_in_attempt(p_handle text, p_door text, p_device text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sign_in_attempt(p_handle text, p_door text, p_device text) IS 'Counts one sign-in attempt on a member''s handle, per door (5 a day, then rests of 1 to 60 minutes) and in the pail every unknown door shares (20, one more every 5 minutes; a phone holding its key is not held by it). Answers {wait, from: here|elsewhere, door, pail}: what was counted, to give back if the house could not answer. Nothing for a handle no one holds. The service role''s alone.';


--
-- Name: sign_in_cleared(text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_in_cleared(p_handle text, p_door text, p_pail boolean, p_device text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid  uuid;
  v_key  text;
  v_hash bytea;
BEGIN
  -- The right password: this door's count goes, the member's own attempt is given back to the pail,
  -- and the phone is handed its key (the one it holds, if it is still theirs, or a new one).
  SELECT p.id INTO v_uid
    FROM public.profiles p JOIN auth.users au ON au.id = p.id
   WHERE lower(p.username) = lower(coalesce(p_handle, ''))
   LIMIT 1;
  IF v_uid IS NULL THEN
    RETURN NULL;
  END IF;
  IF NULLIF(p_door, '') IS NOT NULL THEN
    DELETE FROM public.sign_in_doors WHERE user_id = v_uid AND door = left(p_door, 64);
  END IF;
  IF coalesce(p_pail, false) THEN
    UPDATE public.sign_in_handles SET tokens = LEAST(20, tokens + 1) WHERE user_id = v_uid;
  END IF;

  IF p_device IS NOT NULL AND char_length(p_device) BETWEEN 32 AND 128 THEN
    v_hash := sha256(convert_to(p_device, 'UTF8'));
    UPDATE public.sign_in_devices SET used_at = now() WHERE token_hash = v_hash AND user_id = v_uid;
    IF FOUND THEN
      RETURN p_device;
    END IF;
  END IF;
  -- 244 random bits (two version-4 ids), kept only as its hash.
  v_key := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
  INSERT INTO public.sign_in_devices (token_hash, user_id, made_at, used_at)
  VALUES (sha256(convert_to(v_key, 'UTF8')), v_uid, now(), now());
  -- Ten phones per member at most: the least recently used is let go.
  DELETE FROM public.sign_in_devices
   WHERE user_id = v_uid
     AND token_hash NOT IN (SELECT v.token_hash FROM public.sign_in_devices v WHERE v.user_id = v_uid
                             ORDER BY v.used_at DESC LIMIT 10);
  RETURN v_key;
END;
$$;


--
-- Name: FUNCTION sign_in_cleared(p_handle text, p_door text, p_pail boolean, p_device text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sign_in_cleared(p_handle text, p_door text, p_pail boolean, p_device text) IS 'After the right password: lets the door''s count go, gives the attempt back to the pail, and answers the phone''s key (its own, still the member''s, or a new one; only hashes kept, ten per member). The service role''s alone.';


--
-- Name: sign_in_unasked(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_in_unasked(p_handle text, p_door text, p_pail boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid;
BEGIN
  -- An attempt the house or Auth could not answer: what it counted is given back, and any rest it
  -- earned with it (a rest earned before it had already ended, or the attempt would not have run).
  SELECT p.id INTO v_uid
    FROM public.profiles p JOIN auth.users au ON au.id = p.id
   WHERE lower(p.username) = lower(coalesce(p_handle, ''))
   LIMIT 1;
  IF v_uid IS NULL THEN
    RETURN;
  END IF;
  IF NULLIF(p_door, '') IS NOT NULL THEN
    UPDATE public.sign_in_doors SET misses = GREATEST(0, misses - 1), paused_until = NULL
     WHERE user_id = v_uid AND door = left(p_door, 64);
  END IF;
  IF coalesce(p_pail, false) THEN
    UPDATE public.sign_in_handles SET tokens = LEAST(20, tokens + 1) WHERE user_id = v_uid;
  END IF;
END;
$$;


--
-- Name: FUNCTION sign_in_unasked(p_handle text, p_door text, p_pail boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sign_in_unasked(p_handle text, p_door text, p_pail boolean) IS 'Gives back what sign_in_attempt counted for an attempt the house or Auth could not answer, and the rest it earned. The service role''s alone.';


--
-- Name: standing_from_verdicts(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.standing_from_verdicts(p_user uuid, p_what text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ban       public.mod_actions%ROWTYPE;
  v_susp      public.mod_actions%ROWTYPE;
  v_banned    boolean;
  v_banned_at timestamptz;
  v_until     timestamptz;
  v_said      text;
BEGIN
  SELECT coalesce(is_banned, false), banned_at, suspended_until, suspension_reason
    INTO v_banned, v_banned_at, v_until, v_said
    FROM public.profiles WHERE id = p_user FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- The verdicts that still hold: never lifted, never overturned (an overturned one is lifted too).
  SELECT * INTO v_ban FROM public.mod_actions
   WHERE target_user_id = p_user AND action IN ('ban', 'permanent_exile') AND lifted_at IS NULL
   ORDER BY (action = 'permanent_exile') DESC, created_at DESC, id DESC LIMIT 1;
  SELECT * INTO v_susp FROM public.mod_actions
   WHERE target_user_id = p_user AND action IN ('suspend', 'mute_user') AND lifted_at IS NULL AND expires_at > now()
   ORDER BY expires_at DESC, created_at DESC, id DESC LIMIT 1;

  -- 'ban' reads the ban again, 'suspension' the suspension, 'all' both: a part not asked of is left as
  -- it stands, so a verdict overturned never touches a standing it did not make.
  IF p_what IN ('ban', 'all') THEN
    v_banned := v_ban.id IS NOT NULL;
    v_banned_at := v_ban.created_at;
  END IF;
  IF p_what IN ('suspension', 'all') THEN
    v_until := v_susp.expires_at;
  END IF;

  -- The reason on the member's page is the one of what governs: a ban's while one stands, else the
  -- longest suspension's; none when nothing stands.
  v_said := CASE
    WHEN v_banned AND v_ban.id IS NOT NULL AND p_what IN ('ban', 'all')
      THEN CASE WHEN v_ban.action = 'permanent_exile' THEN 'PERMANENT EXILE: ' ELSE '' END || v_ban.reason
    WHEN v_banned THEN v_said
    WHEN v_until > now() AND v_susp.id IS NOT NULL
      THEN CASE WHEN v_susp.action = 'mute_user' THEN 'Muted: ' ELSE '' END || v_susp.reason
    WHEN v_until > now() THEN v_said
    ELSE NULL
  END;

  UPDATE public.profiles
     SET is_banned = v_banned, banned_at = v_banned_at, suspended_until = v_until, suspension_reason = v_said
   WHERE id = p_user;
END;
$$;


--
-- Name: submit_report(uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_report(p_reporter_id uuid, p_content_id uuid, p_content_type text, p_reason text, p_details text DEFAULT NULL::text, p_target_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reporter_id uuid := auth.uid();
  v_report_id uuid;
  v_recent_count int;
  v_target uuid;
  v_words jsonb;
BEGIN
  IF v_reporter_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;

  SELECT COUNT(*) INTO v_recent_count
  FROM reports
  WHERE reporter_id = v_reporter_id
    AND created_at > now() - interval '1 hour';

  IF v_recent_count >= 10 THEN
    RAISE EXCEPTION 'Rate limit exceeded: maximum 10 reports per hour';
  END IF;

  -- The member is read from the item, never taken from the caller.
  v_target := CASE p_content_type
    WHEN 'profile'          THEN (SELECT id FROM profiles WHERE id = p_content_id)
    WHEN 'log'              THEN (SELECT user_id FROM logs WHERE id = p_content_id)
    WHEN 'list'             THEN (SELECT user_id FROM lists WHERE id = p_content_id)
    WHEN 'log_comment'      THEN (SELECT user_id FROM log_comments WHERE id = p_content_id)
    WHEN 'list_comment'     THEN (SELECT user_id FROM list_comments WHERE id = p_content_id)
    WHEN 'dossier'          THEN (SELECT user_id FROM dispatch_posts WHERE id = p_content_id)
    WHEN 'dispatch_post'    THEN (SELECT user_id FROM dispatch_posts WHERE id = p_content_id)
    WHEN 'dossier_comment'  THEN (SELECT user_id FROM dispatch_comments WHERE id = p_content_id)
    WHEN 'dispatch_comment' THEN (SELECT user_id FROM dispatch_comments WHERE id = p_content_id)
    WHEN 'lounge_message'   THEN (SELECT user_id FROM lounge_messages WHERE id = p_content_id)
    WHEN 'lounge'           THEN (SELECT creator_id FROM lounges WHERE id = p_content_id)
  END;

  IF p_content_type = 'profile' AND v_reporter_id = v_target THEN
    RAISE EXCEPTION 'Cannot report your own profile';
  END IF;

  BEGIN
    INSERT INTO reports (reporter_id, content_id, content_type, reason, details, target_user_id, status)
    VALUES (v_reporter_id, p_content_id, p_content_type, p_reason, p_details, v_target, 'pending')
    RETURNING id INTO v_report_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Already reported' USING ERRCODE = '23505';
  END;

  -- The words reported, as they stand now: whatever their author does before the verdict, the
  -- Tribunal reads what was reported beside what is left (get_report_evidence).
  v_words := public.piece_as_it_stands(p_content_type, p_content_id);
  IF coalesce((v_words ->> 'found')::boolean, false) THEN
    INSERT INTO public.reported_words (report_id, words) VALUES (v_report_id, v_words - 'found');
  END IF;

  RETURN v_report_id;
END;
$$;


--
-- Name: sync_denormalized_username(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_denormalized_username() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.username IS DISTINCT FROM OLD.username THEN
    UPDATE public.dispatch_posts SET author_username = NEW.username
     WHERE user_id = NEW.id AND author_username IS DISTINCT FROM NEW.username;
    UPDATE public.dispatch_comments SET author_username = NEW.username
     WHERE user_id = NEW.id AND author_username IS DISTINCT FROM NEW.username;
    UPDATE public.log_comments SET username = NEW.username
     WHERE user_id = NEW.id AND username IS DISTINCT FROM NEW.username;
    UPDATE public.notifications SET from_username = NEW.username
     WHERE from_user_id = NEW.id AND from_username IS DISTINCT FROM NEW.username;
    UPDATE public.lounge_messages r SET reply_to_username = NEW.username
      FROM public.lounge_messages m
     WHERE r.reply_to_id = m.id AND m.user_id = NEW.id
       AND r.reply_to_username IS DISTINCT FROM NEW.username;
  END IF;
  RETURN NULL;  -- AFTER trigger: the return value is ignored
END $$;


--
-- Name: taste_shape(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.taste_shape(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  WITH l AS (
    SELECT round(rating) AS reel,
           CASE WHEN year::text ~ '^\d{1,4}$' THEN (year::text::int / 10) * 10 END AS decade
      FROM public.logs WHERE user_id = p_user_id
        -- a log the house withholds counts for its author alone (H-B10)
        AND (withheld_at IS NULL OR user_id = auth.uid())
  )
  SELECT jsonb_build_object(
    'logs', (SELECT count(*) FROM l),
    'ratings', (SELECT jsonb_agg((SELECT count(*) FROM l WHERE l.reel = r) ORDER BY r)
                  FROM generate_series(1, 5) AS r),
    'decades', coalesce((SELECT jsonb_object_agg(decade::text, n)
                           FROM (SELECT decade, count(*) AS n FROM l
                                  WHERE decade IS NOT NULL AND decade > 0 GROUP BY decade) d), '{}'::jsonb)
  );
$_$;


--
-- Name: tg_notify_push(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_notify_push() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_secret   text;
  v_pref_key text;
  v_thing    text;
BEGIN
  -- Switched off by the owner: every notice stays under the bell, unpushed.
  IF NOT coalesce((SELECT pushes_sent FROM public.house_settings WHERE id), true) THEN
    RETURN NEW;
  END IF;

  -- The Lobby's edition turns at 00:00 UTC, while much of the house sleeps:
  -- its notice waits under the bell and is never pushed.
  IF NEW.type = 'featured' THEN
    RETURN NEW;
  END IF;

  IF NEW.from_user_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.user_blocks
    WHERE (blocker_id = NEW.user_id      AND blocked_id = NEW.from_user_id)
       OR (blocker_id = NEW.from_user_id AND blocked_id = NEW.user_id AND type = 'block')
  ) THEN
    RETURN NEW;
  END IF;

  v_pref_key := CASE NEW.type
                  WHEN 'follow'         THEN 'notif_follows'
                  WHEN 'follow_request' THEN 'notif_follows'
                  WHEN 'follow_accept'  THEN 'notif_follows'
                  WHEN 'endorse'        THEN 'notif_endorsements'
                  WHEN 'endorse_log'    THEN 'notif_endorsements'
                  WHEN 'comment'        THEN 'notif_comments'
                  WHEN 'annotate'       THEN 'notif_comments'
                  WHEN 'ballot'         THEN 'notif_comments'
                  WHEN 'salon'          THEN 'notif_salons'
                  WHEN 'system'         THEN 'notif_system'
                  ELSE NULL
                END;

  IF v_pref_key IS NOT NULL THEN
    IF (SELECT preferences ->> v_pref_key
          FROM public.profiles
         WHERE id = NEW.user_id) = 'false'
    THEN
      RETURN NEW;
    END IF;
  END IF;

  -- An act one member may repeat at another at will buzzes the phone once: given again after it
  -- was taken back, its notice is written, and its push is not sent. Each is named as its notice
  -- names it: a certification of a critique by the critique (its group key is the filing's), every
  -- other certification by its group key; a follow or a follow request by the one followed; a
  -- request to enter a salon by the salon (an admission, sent by the host, is no request); a
  -- critique taken as the answer by the critique; any other critique by the member it is to, once
  -- within the hour, whatever piece it is on.
  IF NEW.from_user_id IS NOT NULL THEN
    v_thing := CASE
      WHEN NEW.type = 'endorse' THEN
        CASE WHEN NEW.metadata ? 'comment_id' THEN 'endorse:comment:' || (NEW.metadata ->> 'comment_id')
             ELSE NEW.group_key END
      WHEN NEW.type IN ('follow', 'follow_request') THEN 'follow:' || NEW.user_id
      WHEN NEW.type IN ('salon', 'system') AND NEW.related_lounge_id IS NOT NULL
           AND NEW.from_user_id IS DISTINCT FROM (SELECT l.creator_id FROM public.lounges l WHERE l.id = NEW.related_lounge_id)
        THEN 'salon_request:' || NEW.related_lounge_id
      WHEN NEW.type = 'comment' AND NEW.metadata ? 'answer' AND NEW.metadata ? 'comment_id'
        THEN 'answer:' || (NEW.metadata ->> 'comment_id')
      WHEN NEW.type = 'comment'
        THEN 'critique_to:' || NEW.user_id
      ELSE NULL
    END;
    IF v_thing IS NOT NULL AND char_length(v_thing) <= 200 THEN
      IF NEW.type IN ('follow', 'follow_request') THEN
        -- A follow is told again once a month has passed since it was last pushed.
        INSERT INTO public.certifications_pushed (from_user_id, user_id, thing)
        VALUES (NEW.from_user_id, NEW.user_id, v_thing)
        ON CONFLICT (from_user_id, thing) DO UPDATE SET pushed_at = now()
          WHERE public.certifications_pushed.pushed_at < now() - interval '30 days';
      ELSIF v_thing LIKE 'critique_to:%' THEN
        -- A member's critiques to another are told again once an hour has passed since one was last pushed.
        INSERT INTO public.certifications_pushed (from_user_id, user_id, thing)
        VALUES (NEW.from_user_id, NEW.user_id, v_thing)
        ON CONFLICT (from_user_id, thing) DO UPDATE SET pushed_at = now()
          WHERE public.certifications_pushed.pushed_at < now() - interval '1 hour';
      ELSE
        INSERT INTO public.certifications_pushed (from_user_id, user_id, thing)
        VALUES (NEW.from_user_id, NEW.user_id, v_thing)
        ON CONFLICT (from_user_id, thing) DO NOTHING;
      END IF;
      IF NOT FOUND THEN
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = 'notify_push_secret' LIMIT 1;

  PERFORM net.http_post(
    url     := 'https://wihyqkpoymwcvbprslyz.supabase.co/functions/v1/notify-push',
    headers := jsonb_build_object('Content-Type','application/json','x-function-secret', v_secret),
    body    := jsonb_build_object('type','INSERT','table','notifications','record', to_jsonb(NEW))
  );
  RETURN NEW;
END;
$$;


--
-- Name: tier_weight(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tier_weight(t text) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE lower(coalesce(t, ''))
           WHEN 'archivist' THEN 1
           WHEN 'auteur'    THEN 2
           WHEN 'founding'  THEN 3
           ELSE 0 END;
$$;


--
-- Name: toggle_dossier_certify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_dossier_certify(dossier_uuid uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    DECLARE
      already  boolean;
      v_banned boolean;
      v_until  timestamptz;
    BEGIN
      SELECT is_banned, suspended_until INTO v_banned, v_until
        FROM public.profiles WHERE id = auth.uid();
      IF COALESCE(v_banned, false) THEN
        RAISE EXCEPTION 'Your account has been silenced by The Society.'
          USING ERRCODE = '42501';
      END IF;
      IF v_until IS NOT NULL AND v_until > now() THEN
        RAISE EXCEPTION 'Your account is suspended until %.',
          to_char(v_until AT TIME ZONE 'UTC', 'DD Mon YYYY HH24:MI "UTC"')
          USING ERRCODE = '42501';
      END IF;

      SELECT EXISTS(SELECT 1 FROM public.dispatch_certifications
                     WHERE user_id = auth.uid() AND post_id = dossier_uuid) INTO already;
      IF already THEN
        DELETE FROM public.dispatch_certifications
         WHERE user_id = auth.uid() AND post_id = dossier_uuid;
        RETURN FALSE;
      ELSE
        IF NOT EXISTS (SELECT 1 FROM public.dispatch_posts p
                        WHERE p.id = dossier_uuid AND p.ended_at IS NULL AND p.withheld_at IS NULL) THEN
          RAISE EXCEPTION 'new row violates row-level security policy for table "dispatch_certifications"'
            USING ERRCODE = '42501';
        END IF;
        INSERT INTO public.dispatch_certifications (user_id, post_id)
        VALUES (auth.uid(), dossier_uuid);
        RETURN TRUE;
      END IF;
    END $$;


--
-- Name: tribunal_waiting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tribunal_waiting() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
BEGIN
  IF v_admin_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_admin_id AND role = 'admin') THEN
    RAISE EXCEPTION 'Unauthorized: admin role required' USING ERRCODE = '42501';
  END IF;
  -- The cases pending, and the appeals this moderator may hear (never those of their own verdicts, nor of
  -- verdicts about themselves: a_judge_is_refused).
  RETURN jsonb_build_object(
    'cases', (SELECT count(*) FROM public.reports WHERE status = 'pending'),
    'appeals', (SELECT count(*) FROM public.mod_actions
                 WHERE appeal_status = 'pending' AND private.a_judge_is_refused(v_admin_id, admin_id, target_user_id) IS NULL));
END;
$$;


--
-- Name: update_my_preferences(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_preferences(p_preferences jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_user_id UUID := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Not authenticated.'; END IF;
  UPDATE public.profiles SET preferences = preferences || p_preferences, updated_at = NOW() WHERE id = v_user_id;
END;
$$;


