--
-- Name: viewing_fields_uncovered(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.viewing_fields_uncovered() RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(array_agg(a.attname ORDER BY a.attnum), '{}'::text[])
    FROM pg_attribute a
   WHERE a.attrelid = 'public.logs'::regclass
     AND a.attnum > 0 AND NOT a.attisdropped
     AND NOT (public.viewing_fields()->'archived' ? a.attname)
     AND NOT (public.viewing_fields()->'not_a_viewing' @> to_jsonb(a.attname));
$$;


--
-- Name: viewing_note_remove(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.viewing_note_remove(p_viewing_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.viewing_note_remove(p_viewing_id, now());
END $$;


--
-- Name: viewing_note_remove(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.viewing_note_remove(p_viewing_id uuid, p_written_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_at timestamptz := LEAST(COALESCE(p_written_at, now()), now());
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  -- One viewing's note is set and taken away one act after the other: a note queued on one phone and
  -- a removal on another at the same moment otherwise each read the other as not there, and the older
  -- note stood after the later removal. Held to the end of the transaction.
  PERFORM pg_advisory_xact_lock(hashtext('note:' || p_viewing_id::text));
  -- Taken away unless the member wrote it again later than they took it away.
  DELETE FROM public.log_private_notes
   WHERE viewing_id = p_viewing_id AND user_id = auth.uid() AND updated_at <= v_at;
  -- Its moment kept, unless a later note still stands; only for a viewing of the caller's own record.
  IF NOT EXISTS (SELECT 1 FROM public.log_private_notes WHERE viewing_id = p_viewing_id)
     AND EXISTS (SELECT 1 FROM public.viewings v JOIN public.logs l ON l.id = v.log_id
                  WHERE v.viewing_id = p_viewing_id AND l.user_id = auth.uid()) THEN
    INSERT INTO public.viewing_notes_removed AS r (viewing_id, user_id, removed_at)
    VALUES (p_viewing_id, auth.uid(), v_at)
    ON CONFLICT (viewing_id) DO UPDATE
      SET removed_at = GREATEST(r.removed_at, EXCLUDED.removed_at), user_id = EXCLUDED.user_id;
  END IF;
END $$;


--
-- Name: viewing_note_set(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.viewing_note_set(p_log_id uuid, p_viewing_id uuid, p_notes text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.viewing_note_set(p_log_id, p_viewing_id, p_notes, now());
END $$;


--
-- Name: viewing_note_set(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.viewing_note_set(p_log_id uuid, p_viewing_id uuid, p_notes text, p_written_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v    text := NULLIF(btrim(COALESCE(p_notes, '')), '');
  -- When the member wrote it, never later than now: a phone's clock ahead of the house's cannot
  -- make a note stand over every later one.
  v_at timestamptz := LEAST(COALESCE(p_written_at, now()), now());
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;
  -- One viewing's note is set and taken away one act after the other: a note queued on one phone and
  -- a removal on another at the same moment otherwise each read the other as not there, and the older
  -- note stood after the later removal. Held to the end of the transaction.
  PERFORM pg_advisory_xact_lock(hashtext('note:' || p_viewing_id::text));

  IF v IS NULL THEN
    -- An empty note takes the note away, with its moment kept.
    PERFORM public.viewing_note_remove(p_viewing_id, v_at);
    RETURN;
  END IF;
  IF char_length(v) > 1000 THEN
    RAISE EXCEPTION 'A note holds 1,000 characters at most.' USING ERRCODE = '22001';
  END IF;

  -- Taken away after this was written: done, unwritten.
  IF EXISTS (SELECT 1 FROM public.viewing_notes_removed
              WHERE viewing_id = p_viewing_id AND user_id = auth.uid() AND removed_at > v_at) THEN
    RETURN;
  END IF;

  INSERT INTO public.log_private_notes (log_id, viewing_id, user_id, notes, updated_at)
  VALUES (p_log_id, p_viewing_id, auth.uid(), v, v_at)
  ON CONFLICT (viewing_id) DO UPDATE
    SET notes = EXCLUDED.notes, updated_at = EXCLUDED.updated_at
    WHERE public.log_private_notes.user_id = auth.uid()
      AND public.log_private_notes.updated_at <= EXCLUDED.updated_at;

  IF NOT FOUND THEN
    -- The member's own note, written later than this: it stands, and this older one is done.
    IF EXISTS (SELECT 1 FROM public.log_private_notes WHERE viewing_id = p_viewing_id AND user_id = auth.uid()) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'That viewing is not yours.' USING ERRCODE = '42501';
  END IF;
  -- Written after the removal: the kept moment has done its work.
  DELETE FROM public.viewing_notes_removed WHERE viewing_id = p_viewing_id AND removed_at <= v_at;
END $$;


--
-- Name: viewing_set_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.viewing_set_list() RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT string_agg(format('%I = ($4::public.logs).%I', col, col), ', ' ORDER BY col)
    FROM jsonb_object_keys(public.viewing_fields()->'archived') AS col;
$_$;


--
-- Name: whose_words_a_message_carries(uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.whose_words_a_message_carries(p_writer uuid, p_type text, p_metadata jsonb, p_reply_to_id uuid) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The members whose words a message carries besides its writer's: the writer of the message it
  -- answers (its quote), the author of its own card, and the author of a card it answers (a caption
  -- the website wrote carries the stack's title and its curator). NULL: none but its writer's.
  SELECT nullif(ARRAY(
    SELECT DISTINCT w.id
      FROM (SELECT public.a_cards_author(p_type, p_metadata) AS id
            UNION ALL
            SELECT q.user_id FROM public.lounge_messages q WHERE q.id = p_reply_to_id
            UNION ALL
            SELECT public.a_cards_author(q.type, q.metadata) FROM public.lounge_messages q WHERE q.id = p_reply_to_id) w
     WHERE w.id IS NOT NULL AND w.id IS DISTINCT FROM p_writer
     ORDER BY w.id), '{}'::uuid[])
$$;


--
-- Name: withdraw_lounge_message(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdraw_lounge_message(p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_author uuid; v_lounge uuid; v_creator uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  SELECT user_id, lounge_id INTO v_author, v_lounge FROM public.lounge_messages WHERE id = p_message_id;
  IF v_author IS NULL THEN RETURN; END IF;
  SELECT creator_id INTO v_creator FROM public.lounges WHERE id = v_lounge;
  IF auth.uid() IS DISTINCT FROM v_author AND auth.uid() IS DISTINCT FROM v_creator THEN
    RAISE EXCEPTION 'You can only withdraw your own dispatch'; END IF;
  UPDATE public.lounge_messages SET content = '', deleted_at = now() WHERE id = p_message_id;
END $$;


--
-- Name: withheld_kind(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withheld_kind(p_content_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The kind of piece a report's content type names, as the house withholds it; none for a kind it
  -- does not withhold (a salon message, a page, a salon: each has its own way back).
  SELECT CASE p_content_type
    WHEN 'log'              THEN 'log'
    WHEN 'list'             THEN 'list'
    WHEN 'log_comment'      THEN 'log_comment'
    WHEN 'list_comment'     THEN 'list_comment'
    WHEN 'dossier_comment'  THEN 'dispatch_comment'
    WHEN 'dispatch_comment' THEN 'dispatch_comment'
    WHEN 'dossier'          THEN 'dispatch_post'
    WHEN 'dispatch_post'    THEN 'dispatch_post'
  END
$$;


--
-- Name: withhold_piece(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withhold_piece(p_action_id uuid, p_kind text, p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_author  uuid;
  v_film    integer;
  v_parent  uuid;
  v_at      timestamptz;
  v_notices jsonb := '[]'::jsonb;
BEGIN
  -- The piece, withheld where it stands; one already withheld or gone is not withheld again.
  IF p_kind = 'log' THEN
    UPDATE public.logs SET withheld_at = now() WHERE id = p_id AND withheld_at IS NULL RETURNING user_id, film_id INTO v_author, v_film;
  ELSIF p_kind = 'list' THEN
    UPDATE public.lists SET withheld_at = now() WHERE id = p_id AND withheld_at IS NULL RETURNING user_id INTO v_author;
  ELSIF p_kind = 'log_comment' THEN
    UPDATE public.log_comments SET withheld_at = now() WHERE id = p_id AND withheld_at IS NULL RETURNING user_id, log_id, created_at INTO v_author, v_parent, v_at;
  ELSIF p_kind = 'list_comment' THEN
    UPDATE public.list_comments SET withheld_at = now() WHERE id = p_id AND withheld_at IS NULL RETURNING user_id, list_id, created_at INTO v_author, v_parent, v_at;
  ELSIF p_kind = 'dispatch_comment' THEN
    UPDATE public.dispatch_comments SET withheld_at = now() WHERE id = p_id AND withheld_at IS NULL RETURNING user_id, post_id INTO v_author, v_parent;
  ELSIF p_kind = 'dispatch_post' THEN
    UPDATE public.dispatch_posts SET withheld_at = now() WHERE id = p_id AND withheld_at IS NULL AND ended_at IS NULL RETURNING user_id INTO v_author;
  ELSE
    RETURN false;
  END IF;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Its cards in the salons, gone with it, live.
  PERFORM private.a_withheld_piece_turns_its_cards(p_kind, p_id, true);

  -- The counts that held it leave it out; the notices of it other members held are set aside, whole.
  IF p_kind = 'log' THEN
    PERFORM public.refresh_film_verdict(v_film);
  ELSIF p_kind = 'log_comment' THEN
    UPDATE public.log_counts SET critique_count = GREATEST(0, critique_count - 1) WHERE log_id = v_parent;
    WITH gone AS (
      DELETE FROM public.notifications n
       WHERE n.from_user_id = v_author AND n.type = 'comment' AND n.group_key = 'endorse:log:' || v_parent
         AND n.created_at = v_at AND n.user_id IS DISTINCT FROM v_author
      RETURNING n.*)
    SELECT coalesce(jsonb_agg(to_jsonb(gone)), '[]'::jsonb) INTO v_notices FROM gone;
  ELSIF p_kind = 'list_comment' THEN
    WITH gone AS (
      DELETE FROM public.notifications n
       WHERE n.from_user_id = v_author AND n.type = 'comment' AND n.group_key = 'endorse:list:' || v_parent
         AND n.created_at = v_at AND n.user_id IS DISTINCT FROM v_author
      RETURNING n.*)
    SELECT coalesce(jsonb_agg(to_jsonb(gone)), '[]'::jsonb) INTO v_notices FROM gone;
  ELSIF p_kind = 'dispatch_comment' THEN
    UPDATE public.dispatch_posts SET comment_count = GREATEST(0, comment_count - 1) WHERE id = v_parent;
    -- Told of it by its writer (the critique), of its taking as the answer, of a mark on it: each names it.
    WITH gone AS (
      DELETE FROM public.notifications n
       WHERE n.metadata ->> 'comment_id' = p_id::text AND n.user_id IS DISTINCT FROM v_author
         AND (n.from_user_id = v_author
              OR n.user_id IN (SELECT p.user_id FROM public.dispatch_posts p WHERE p.id = v_parent))
      RETURNING n.*)
    SELECT coalesce(jsonb_agg(to_jsonb(gone)), '[]'::jsonb) INTO v_notices FROM gone;
  ELSIF p_kind = 'dispatch_post' THEN
    -- Told to the members it touched: its critics (an answer, a mark on their critique) and its voters
    -- (a ballot's close). Each notice names the filing; its author's own stay.
    WITH gone AS (
      DELETE FROM public.notifications n
       WHERE n.user_id IN (SELECT c.user_id FROM public.dispatch_comments c WHERE c.post_id = p_id
                           UNION SELECT v.user_id FROM public.dispatch_votes v WHERE v.post_id = p_id)
         AND n.user_id IS DISTINCT FROM v_author
         AND n.metadata ->> 'dispatch_post_id' = p_id::text
      RETURNING n.*)
    SELECT coalesce(jsonb_agg(to_jsonb(gone)), '[]'::jsonb) INTO v_notices FROM gone;
  END IF;

  INSERT INTO public.withheld_pieces (mod_action_id, kind, piece_id, author_id, delete_after, notices)
  VALUES (p_action_id, p_kind, p_id, v_author, now() + interval '30 days', v_notices)
  ON CONFLICT (mod_action_id) DO NOTHING;
  RETURN true;
END;
$$;


--
-- Name: year_viewings(uuid, integer, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.year_viewings(p_user_id uuid, p_year integer, p_before_day date DEFAULT NULL::date, p_before_viewing uuid DEFAULT NULL::uuid) RETURNS TABLE(log_id uuid, viewing_id uuid, film_id integer, film_title text, poster_path text, rating numeric, day date)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT v.log_id, v.viewing_id, v.film_id, v.film_title, v.poster_path, v.rating, v.day
    FROM private.viewings_between(p_user_id, make_date(p_year, 1, 1),
                                  CASE WHEN p_before_day IS NULL THEN make_date(p_year, 12, 31)
                                       ELSE LEAST(make_date(p_year, 12, 31), p_before_day) END) v
   WHERE (p_before_day IS NULL OR (v.day, v.viewing_id) < (p_before_day, p_before_viewing))
   ORDER BY v.day DESC, v.viewing_id DESC
   LIMIT 1000;
$$;


